import type { ReactNode } from 'react';

import type { ViewPane } from '../../../../core/ui/features/trace-viewer';
import type {
  TracerCapabilities,
  TracerFeatures,
} from '../../types/capabilities';

export interface PaneProps extends Pick<
  ViewPane,
  'minSize' | 'maxSize' | 'preferredSize' | 'visible'
> {
  id: string;
  children: ReactNode;
  /** Render this pane only when the named feature is enabled. */
  feature?: keyof TracerFeatures;
  /** Render this pane only when the named capability is granted. */
  capability?: keyof TracerCapabilities;
}

/**
 * Marker component consumed by `<Row>`/`<Col>`. Never rendered directly —
 * its parent split extracts props and content to build the pane tree.
 */
export const Pane = ({ children }: PaneProps) => <>{children}</>;
