import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
  VerdictResultIndicator,
} from '@heal/front-core/ui';
import { useEffect, useState, type MouseEvent } from 'react';
import { createPortal } from 'react-dom';

import { FileTabs, type FileTabItem } from './_components/file-tabs';
import { useCodeEditor } from './_hooks/use-code-editor';
import { getBaseName, resolveLanguage } from './_utils/resolve-language';
import type { CodeEditorFile, CodeEditorViewProps } from './code-editor.types';

export type { CodeEditorFile, CodeEditorLanguage } from './code-editor.types';

const getActivePath = (
  files: CodeEditorFile[],
  selectedPath: string | undefined,
): string | undefined => {
  const isSelectionOpen = files.some((file) => file.path === selectedPath);
  if (isSelectionOpen) {
    return selectedPath;
  }

  return files[0]?.path;
};

const getTabItems = (files: CodeEditorFile[]): FileTabItem[] =>
  files.map((file) => ({
    value: file.path,
    label: file.name ?? getBaseName(file.path),
    language: resolveLanguage(file),
    title: file.path,
  }));

export const CodeEditorView = ({
  files,
  defaultActivePath,
  theme = 'vs-dark',
  ariaLabel,
  revealTarget,
}: CodeEditorViewProps) => {
  const [selectedPath, setSelectedPath] = useState(
    () => defaultActivePath ?? files[0]?.path,
  );
  const [menu, setMenu] = useState<{
    goToTarget: string | null;
    canCopy: boolean;
  }>({ goToTarget: null, canCopy: false });

  // Switch to the requested file; the hook reveals the line once it's active.
  useEffect(() => {
    if (revealTarget) {
      setSelectedPath(revealTarget.path);
    }
  }, [revealTarget]);

  const activePath = getActivePath(files, selectedPath);
  const {
    hostRef,
    ready,
    resolveImportAtPoint,
    getSelectionText,
    annotationPortals,
  } = useCodeEditor({
    files,
    activePath,
    theme,
    onNavigate: setSelectedPath,
    revealTarget,
  });

  const handleContextMenu = (event: MouseEvent<HTMLDivElement>) => {
    setMenu({
      goToTarget: resolveImportAtPoint(event.clientX, event.clientY),
      canCopy: getSelectionText().length > 0,
    });
  };

  const handleGoToFile = () => {
    if (menu.goToTarget) {
      setSelectedPath(menu.goToTarget);
    }
  };

  const handleCopy = () => {
    const text = getSelectionText();
    if (text) {
      void navigator.clipboard.writeText(text);
    }
  };

  const hasFiles = files.length > 0;
  const showLoading = hasFiles && !ready;

  return (
    <div
      aria-label={ariaLabel}
      role="region"
      className="flex h-full w-full flex-col"
    >
      {hasFiles && (
        <FileTabs
          value={activePath}
          onValueChange={setSelectedPath}
          items={getTabItems(files)}
        />
      )}
      <ContextMenu>
        <ContextMenuTrigger asChild>
          <div
            className="relative min-h-0 flex-1"
            onContextMenu={handleContextMenu}
          >
            {/* Host is always mounted so the editor can be created as soon as
                Monaco bootstraps, even if `files` arrive asynchronously. */}
            <div ref={hostRef} className="absolute inset-0" />
            {!hasFiles && (
              <div className="absolute inset-0 flex items-center justify-center text-sm text-muted-foreground">
                No files to display
              </div>
            )}
            {showLoading && (
              <div className="absolute inset-0 flex items-center justify-center text-sm text-muted-foreground">
                Loading editor…
              </div>
            )}
          </div>
        </ContextMenuTrigger>
        <ContextMenuContent>
          <ContextMenuItem
            disabled={!menu.goToTarget}
            onSelect={handleGoToFile}
          >
            Go to File
          </ContextMenuItem>
          <ContextMenuItem disabled={!menu.canCopy} onSelect={handleCopy}>
            Copy
          </ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>
      {annotationPortals.map((portal) =>
        createPortal(
          <VerdictResultIndicator
            status={portal.status}
            verdictType={portal.verdictType}
            variant="iconOnly"
            size="sm"
          />,
          portal.node,
          portal.key,
        ),
      )}
    </div>
  );
};
