import { useAuth } from '../../../lib/auth-context';

import { AuthLoading } from './_components/auth-loading';
import { AuthLoggedIn } from './_components/auth-logged-in';
import { AuthLoggedOut } from './_components/auth-logged-out';
import { AuthNotInstalled } from './_components/auth-not-installed';

/**
 * Renders the auth chip in the standalone tracer's header. Reads auth
 * state directly from the auth context (`heal whoami --json`), surfacing
 * the freemium funnel: install CLI / sign in / profile chip.
 */
export const Auth = () => {
  const { state, signIn } = useAuth();

  switch (state.status) {
    case 'loading':
      return <AuthLoading />;

    case 'not_installed':
      return <AuthNotInstalled />;

    case 'logged_out':
      return <AuthLoggedOut onSignIn={signIn} />;

    case 'logged_in':
      return <AuthLoggedIn profile={state.profile} />;
  }
};
