import { Button } from '@heal/front-core/ui';
import { XIcon } from '@phosphor-icons/react';

import { useTestListPaneConfig } from '../../../../core/ui/features/trace-viewer';
import { useDataProvider } from '../../context/data-provider/data-provider.hooks';
import { useTriageVerdictForm } from '../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import { useViewProvider } from '../../context/view-provider/view-provider.hooks';
import { useDelayedFlag } from '../../hooks/use-delayed-flag';
import { Col, ModeLayout, Pane, Row } from '../layout';
import {
  CREATE_TRIAGE_VERDICT_FORM_VIEW_ID,
  CreateTriageVerdictFormView,
} from '../views/create-triage-verdict-form/create-triage-verdict-form.view';
import { HeaderView } from '../views/header/header.view';
import { MediaView } from '../views/media/media.view';
import {
  TEST_CASE_VIEW_ID,
  TestCaseView,
} from '../views/test-case/test-case.view';
import {
  TEST_CONTENT_VIEW_ID,
  TestContentView,
} from '../views/test-content/test-content.view';
import {
  TEST_LIST_VIEW_ID,
  TestListView,
} from '../views/test-list/test-list.view';
import { VerdictFormView } from '../views/verdict-form/verdict-form.view';

import { MediaSkeleton } from './_loading/_components/media.skeleton';
import { TestCaseSkeleton } from './_loading/_components/test-case.skeleton';
import { TestContentSkeleton } from './_loading/_components/test-content.skeleton';

export const TRIAGE_MODE_ID = 'triage';
const SKELETON_DELAY_MS = 150;
const SKELETON_MIN_DURATION_MS = 400;

export const TriageMode = () => {
  const { testListVisibility } = useViewProvider();
  const { loading } = useDataProvider();
  const testListPaneConfig = useTestListPaneConfig(testListVisibility.isFolded);
  const showSkeleton = useDelayedFlag(loading, {
    delay: SKELETON_DELAY_MS,
    minDuration: SKELETON_MIN_DURATION_MS,
  });
  const { state } = useTriageVerdictForm();

  if (state.isOpen) {
    return (
      <>
        <HeaderView />
        <ModeLayout mode={TRIAGE_MODE_ID}>
          <Row>
            <Pane id={TEST_LIST_VIEW_ID} {...testListPaneConfig}>
              <TestListView />
            </Pane>
            <Pane id="content-panel">
              <Col>
                <Pane id="media" preferredSize="65%">
                  <MediaView />
                </Pane>
                <Pane id={TEST_CONTENT_VIEW_ID}>
                  <TestContentView />
                </Pane>
              </Col>
            </Pane>
            <Pane
              id={CREATE_TRIAGE_VERDICT_FORM_VIEW_ID}
              preferredSize="35%"
              feature="verdictForm"
            >
              <TriageVerdictFormPane />
            </Pane>
          </Row>
        </ModeLayout>
      </>
    );
  }

  return (
    <>
      <HeaderView />
      <ModeLayout mode={TRIAGE_MODE_ID}>
        <Row>
          <Pane id={TEST_LIST_VIEW_ID} {...testListPaneConfig}>
            <TestListView />
          </Pane>
          <Pane id="col-1">
            <Col>
              <Pane id="media" preferredSize="65%">
                {showSkeleton ? <MediaSkeleton /> : <MediaView />}
              </Pane>
              <Pane id="col-1-row-1" preferredSize="65%">
                <Row>
                  <Pane id={TEST_CONTENT_VIEW_ID}>
                    {showSkeleton ? (
                      <TestContentSkeleton />
                    ) : (
                      <TestContentView />
                    )}
                  </Pane>
                  <Pane id={TEST_CASE_VIEW_ID}>
                    {showSkeleton ? <TestCaseSkeleton /> : <TestCaseView />}
                  </Pane>
                </Row>
              </Pane>
            </Col>
          </Pane>
        </Row>
      </ModeLayout>
    </>
  );
};

const TriageVerdictFormPane = () => {
  const { close } = useTriageVerdictForm();
  const { currentTest } = useDataProvider();
  const hasVerdict = !!(
    currentTest?.finalVerdict ?? currentTest?.triagedVerdict
  );

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex shrink-0 items-center justify-end border-b border-border px-2 py-1">
        <Button
          type="button"
          variant="ghost"
          size="iconSm"
          onClick={close}
          aria-label="Close"
        >
          <XIcon size={14} />
        </Button>
      </div>
      <div className="min-h-0 flex-1">
        {hasVerdict ? (
          <VerdictFormView forceReadOnly />
        ) : (
          <CreateTriageVerdictFormView />
        )}
      </div>
    </div>
  );
};
