import { ChevronDownIcon, ChevronRightIcon } from 'lucide-react';
import { ReactNode, useEffect, useState } from 'react';
import { type BundledLanguage, type ThemedToken, codeToTokens } from 'shiki';

import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from '../../../../lib/shadcn/hover-card';
import { cn } from '../../../../lib/utils';
import type { TraceViewerErrorInfo } from '../stack-trace/trace-viewer-stack-trace';
import { TraceViewerStackTrace } from '../stack-trace/trace-viewer-stack-trace';
import type {
  StepCardVariant,
  StepCardStatus,
  VerdictType,
} from '../step-card/use-step-config';
import { useStepConfig } from '../step-card/use-step-config';

// ─── Types ──────────────────────────────────────────────────────

export interface TraceViewerGraphItemData {
  id: number;
  code: string;
  language?: BundledLanguage;
  status?: StepCardStatus;
  verdictType?: VerdictType;
  duration?: string;
  active?: boolean;
  selected?: boolean;
  error?: TraceViewerErrorInfo;
  /**
   * Source file for this step. Surfaced as a `data-explore-file` attribute on
   * the row so a host context menu can resolve "explore code" to the exact row
   * that was clicked (rather than the top-level step).
   */
  file?: string | null;
  /** 1-based source line for this step; paired with `file`. */
  line?: number | null;
  /** Nested child steps — named `steps` to avoid React's reserved `children` prop */
  steps?: TraceViewerGraphItemData[];

  onClick?: (id: number) => void;
}

export interface TraceViewerCodeGraphItemProps extends TraceViewerGraphItemData {
  /** Nesting depth */
  depth?: number;
  /** Whether nested steps start collapsed */
  defaultCollapsed?: boolean;
  /** Shiki theme override */
  theme?: string;
  /** Draw vertical guide lines to visualise nesting depth */
  showIndentGuides?: boolean;
  /** Bump this to broadcast a collapse/expand-all to the whole subtree */
  collapseSignal?: number;
  /** Collapsed state applied to every row when `collapseSignal` changes */
  collapseSignalValue?: boolean;
  /** Render a step */
  renderStep?: (props: {
    step: TraceViewerGraphItemData;
    element: ReactNode;
  }) => ReactNode;
  /** Statement id */
  id: number;
}

// ─── Layout ───────────────────────────────────────────────────────
//
//  [paddingLeft = BASE + depth * INDENT] [toggle?] [code flex-1] [icon] [duration]
//
//  Icon and duration live on the RIGHT — code reads like a clean script
//  from the left with no icon interrupting the left margin.
//  Toggle is present only on parent rows (no empty spacer for leaves).

const BASE_PAD = 4;
const INDENT = 16;

// ─── State highlight constants (mirrors trace-viewer-code-block) ──

const VARIANT_LINE_HIGHLIGHT: Partial<Record<StepCardVariant, string>> = {
  danger: 'bg-danger-subtle',
  brand: 'bg-brand-subtle',
};

const VARIANT_ACTIVE_LINE_HIGHLIGHT: Partial<Record<StepCardVariant, string>> =
  {
    danger: 'bg-danger-subtle',
    brand: 'bg-brand-subtle',
    neutral: 'bg-info-subtle',
    info: 'bg-info-subtle',
    warning: 'bg-warning-subtle',
    success: 'bg-success-subtle',
  };

const ACCENT_BORDER: Record<StepCardVariant, string> = {
  danger: 'border-l-danger-solid',
  success: 'border-l-success-solid',
  warning: 'border-l-warning-solid',
  brand: 'border-l-brand-solid',
  info: 'border-l-info-solid',
  neutral: 'border-l-info-solid',
};

// ─── Dark mode detection ─────────────────────────────────────────

const useIsDarkMode = (): boolean => {
  const [isDark, setIsDark] = useState(
    () =>
      typeof document !== 'undefined' &&
      document.documentElement.classList.contains('dark'),
  );

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    const update = () => setIsDark(root.classList.contains('dark'));
    update();
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ['class'] });

    return () => observer.disconnect();
  }, []);

  return isDark;
};

// ─── Component ──────────────────────────────────────────────────

export const TraceViewerCodeGraphItem = ({
  id,
  code,
  language = 'typescript',
  theme,
  status,
  verdictType,
  duration,
  active = false,
  selected = false,
  error,
  file,
  line,
  steps = [],
  onClick,
  renderStep,
  depth = 0,
  defaultCollapsed = false,
  showIndentGuides = true,
  collapseSignal,
  collapseSignalValue = false,
}: TraceViewerCodeGraphItemProps) => {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);
  const [tokenLines, setTokenLines] = useState<ThemedToken[][] | null>(null);

  // Collapse/expand-all broadcast: when a parent bumps `collapseSignal`, snap
  // this row to the requested state. Guarded on `undefined` so the first mount
  // keeps its own `defaultCollapsed` value instead of being forced open.
  useEffect(() => {
    if (collapseSignal === undefined) return;
    setCollapsed(collapseSignalValue);
  }, [collapseSignal, collapseSignalValue]);

  const isDark = useIsDarkMode();
  // `dark-plus` / `light-plus` are Shiki's bundles of VS Code's Dark+ / Light+
  // themes — the same palettes behind Monaco's `vs-dark` / `vs`, so the code
  // graph matches the Monaco editor. (Shiki has no theme literally named
  // `vs-dark`.)
  const resolvedTheme = theme ?? (isDark ? 'dark-plus' : 'light-plus');
  const stepConfig = useStepConfig({ status, verdictType });

  const hasSteps = steps.length > 0;
  const rowPadLeft = BASE_PAD + depth * INDENT;
  const hasAccent = active || selected;
  const lineHighlight = VARIANT_LINE_HIGHLIGHT[stepConfig.variant];
  const activeHighlight = selected
    ? VARIANT_ACTIVE_LINE_HIGHLIGHT[stepConfig.variant]
    : undefined;

  const rowBg =
    activeHighlight ??
    lineHighlight ??
    (hasAccent ? 'bg-muted' : 'bg-code-editor-background');

  useEffect(() => {
    let cancelled = false;
    const tokenize = async () => {
      const result = await codeToTokens(code || ' ', {
        lang: language,
        theme: resolvedTheme,
      });
      if (!cancelled) setTokenLines(result.tokens);
    };
    tokenize();

    return () => {
      cancelled = true;
    };
  }, [code, language, resolvedTheme]);

  const displayLines =
    tokenLines ??
    (code || ' ')
      .split('\n')
      .map((line) => [{ content: line, color: undefined }] as ThemedToken[]);

  function handleClick(e: React.MouseEvent<HTMLDivElement>) {
    e.stopPropagation();
    onClick?.(id);
  }

  const block = (
    <div className="w-full">
      {displayLines.map((tokens, lineIndex) => {
        const isFirst = lineIndex === 0;

        return (
          <div
            key={lineIndex}
            data-explore-file={file ?? undefined}
            data-explore-line={line ?? undefined}
            className={cn(
              'relative flex w-fit min-w-full items-center gap-2 border-l-2 py-0.5 font-mono text-xs',
              hasAccent
                ? ACCENT_BORDER[stepConfig.variant]
                : 'border-l-transparent',
              lineHighlight,
              activeHighlight,
              !lineHighlight && !activeHighlight && hasAccent && 'bg-muted',
              // Interaction
              isFirst && hasSteps && 'cursor-pointer hover:brightness-[0.97]',
              isFirst &&
                !hasSteps &&
                onClick &&
                'cursor-pointer hover:brightness-[0.97]',
              error && isFirst && 'cursor-help',
            )}
            style={{ paddingLeft: `${rowPadLeft}px` }}
            onClick={handleClick}
          >
            {/* Tree lines — one vertical guide per ancestor level, aligned
                under each parent's toggle chevron. Absolutely positioned so
                the flex/padding layout stays untouched; inset-y-0 makes them
                join up across stacked rows into continuous lines. */}
            {showIndentGuides &&
              Array.from({ length: depth }).map((_, level) => (
                <span
                  key={level}
                  aria-hidden
                  className="pointer-events-none absolute inset-y-0 border-l border-border"
                  style={{
                    left: `${BASE_PAD + level * INDENT + INDENT / 2}px`,
                  }}
                />
              ))}

            {/* Toggle — parent rows only, no empty spacer for leaves */}
            {hasSteps && isFirst ? (
              <span className="flex w-4 shrink-0 items-center justify-center">
                {collapsed ? (
                  <ChevronRightIcon className="size-3 text-muted-foreground/60" />
                ) : (
                  <ChevronDownIcon className="size-3 text-muted-foreground/60" />
                )}
              </span>
            ) : (
              <span className="flex w-4 shrink-0 items-center justify-center opacity-0">
                <ChevronDownIcon className="size-3 text-muted-foreground/60" />
              </span>
            )}

            {/* Code — flex-1, code reads uninterrupted from the left */}
            <code className="flex-1 whitespace-pre leading-6">
              {tokens.map((token, tokenIndex) => (
                <span key={tokenIndex} style={{ color: token.color }}>
                  {token.content}
                </span>
              ))}
              {tokens.length === 0 && <span>&nbsp;</span>}
            </code>

            {/* Icon + duration — sticky right. An opaque `bg-background` base
                fully occludes the code scrolling underneath, with the row's
                (often translucent) tint layered on top so it still matches the
                row colour. Without the opaque base, code bleeds through the
                `*-subtle` tints on horizontal scroll. */}
            {isFirst && (
              <span className="sticky -right-[16px] z-10 flex shrink-0 items-center gap-1.5 bg-code-editor-background pl-2 pr-[20px]">
                <span
                  aria-hidden
                  className={cn('pointer-events-none absolute inset-0', rowBg)}
                />
                <span className="relative flex w-4 items-center justify-center">
                  {stepConfig.icon}
                </span>
                {duration && (
                  <span className="relative w-10 text-right tabular-nums text-muted-foreground/40">
                    {duration}
                  </span>
                )}
              </span>
            )}
          </div>
        );
      })}

      {/* Nested steps */}
      {hasSteps && !collapsed && (
        <div>
          {steps.map((step, i) =>
            renderStep?.({
              step,
              element: (
                <TraceViewerCodeGraphItem
                  key={i}
                  {...step}
                  id={step.id}
                  depth={depth + 1}
                  theme={theme}
                  showIndentGuides={showIndentGuides}
                  collapseSignal={collapseSignal}
                  collapseSignalValue={collapseSignalValue}
                  onClick={onClick}
                  renderStep={renderStep}
                />
              ),
            }),
          )}
        </div>
      )}
    </div>
  );

  if (!error) {
    return block;
  }

  return (
    <HoverCard openDelay={500} closeDelay={300}>
      <HoverCardTrigger asChild>{block}</HoverCardTrigger>
      <HoverCardContent
        align="start"
        sideOffset={6}
        className="w-[600px] max-w-[90vw] overflow-hidden p-0"
      >
        <TraceViewerStackTrace error={error} />
      </HoverCardContent>
    </HoverCard>
  );
};
