import { useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router';

import { NavigationProviderContext } from './navigation-provider.context';
import { NavigationProviderProps } from './navigation-provider.types';

export const NavigationProvider = ({
  children,
  basePath,
  onParamsChange,
}: NavigationProviderProps) => {
  const { testId, attemptNumber, executionId } = useParams<{
    testId: string;
    attemptNumber: string;
    executionId: string;
  }>();
  const testIdRef = useRef<string | undefined>(undefined);
  const attemptNumberRef = useRef<number | undefined>(undefined);
  const executionIdRef = useRef<string | undefined>(undefined);
  const navigate = useNavigate();

  const goToIndex = () => {
    navigate(basePath);
  };

  const goToExecution = (executionId: string) => {
    navigate(`${basePath}/executions/${executionId}`);
  };

  const goToTest = (
    testId: string,
    options: { executionId: string; attemptNumber?: number },
  ) => {
    const e = options.executionId ?? executionId;
    const a = options.attemptNumber ?? 1;
    navigate(`${basePath}/executions/${e}/tests/${testId}/attempts/${a}`);
  };

  const goToTestAttempt = (
    attemptNumber: number,
    options: { executionId: string; testId: string },
  ) => {
    const e = options.executionId ?? executionId;
    const t = options.testId ?? testId;

    navigate(
      `${basePath}/executions/${e}/tests/${t}/attempts/${attemptNumber}`,
    );
  };

  function handleExecutionChange(executionId?: string) {
    if (executionId === executionIdRef.current) {
      return;
    }

    executionIdRef.current = executionId;
    testIdRef.current = undefined;
    attemptNumberRef.current = undefined;

    return;
  }

  function handleTestIdChange(testId?: string) {
    if (testId === testIdRef.current) {
      return;
    }

    if (!executionIdRef.current) {
      return;
    }

    testIdRef.current = testId;
    attemptNumberRef.current = undefined;

    return;
  }

  function handleAttemptChange(attemptNumber?: number) {
    if (attemptNumber === attemptNumberRef.current) {
      return;
    }

    if (!executionIdRef.current || !testIdRef.current) {
      return;
    }

    attemptNumberRef.current = attemptNumber;

    return;
  }

  useEffect(() => {
    handleExecutionChange(executionId);
    handleTestIdChange(testId);
    handleAttemptChange(
      attemptNumber ? parseInt(attemptNumber, 10) : undefined,
    );

    onParamsChange?.({
      executionId: executionIdRef.current,
      testId: testIdRef.current,
      attemptNumber: attemptNumberRef.current,
    });
  }, [executionId, testId, attemptNumber]);

  return (
    <NavigationProviderContext.Provider
      value={{
        basePath,
        goToIndex,
        goToExecution,
        goToTest,
        goToTestAttempt,
      }}
    >
      {children}
    </NavigationProviderContext.Provider>
  );
};
