import * as z from 'zod';

import type { VerdictSubmitPayload } from '../../../../context/event-provider/event-provider.types';
import type { TriagedVerdict, VerdictType } from '../../../../types/test';

export const FORM_TYPES = [
  'bug',
  'ui_changed',
  'heal_system_issue',
  'unstable_locator',
  'broken_test_logic',
] as const;

export type FormType = (typeof FORM_TYPES)[number];

export interface FormTypeOption {
  value: FormType;
  label: string;
  verdictType: VerdictType;
}

export const FORM_TYPE_OPTIONS: FormTypeOption[] = [
  { value: 'bug', label: 'Bug', verdictType: 'BUG' },
  { value: 'ui_changed', label: 'UI changed', verdictType: 'UI_CHANGED' },
  {
    value: 'heal_system_issue',
    label: 'Heal system issue',
    verdictType: 'HEAL_SYSTEM_ISSUE',
  },
  {
    value: 'unstable_locator',
    label: 'Unstable locator',
    verdictType: 'UNSTABLE_LOCATOR',
  },
  {
    value: 'broken_test_logic',
    label: 'Broken test logic',
    verdictType: 'BROKEN_TEST_LOGIC',
  },
];

export const VERDICT_TYPE_TO_FORM_TYPE: Record<VerdictType, FormType> = {
  BUG: 'bug',
  UI_CHANGED: 'ui_changed',
  HEAL_SYSTEM_ISSUE: 'heal_system_issue',
  UNSTABLE_LOCATOR: 'unstable_locator',
  BROKEN_TEST_LOGIC: 'broken_test_logic',
  // NO_VERDICT is an analysis output, not a user-selectable type. When such a
  // verdict is opened in the form, default to the bug layout so the operator
  // can reclassify it.
  NO_VERDICT: 'bug',
};

export const createTriageVerdictFormSchema = z
  .object({
    type: z.enum(FORM_TYPES),
    expected: z.string().trim().optional(),
    actual: z.string().trim().optional(),
    description: z.string().trim().optional(),
    reason: z.string().trim().optional(),
    suggestedFix: z.string().trim().optional(),
    comment: z.string().trim().optional(),
    failingStatementIndex: z.number().int().nonnegative().optional(),
  })
  .superRefine((data, ctx) => {
    if (data.type === 'bug') {
      if (!data.expected) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['expected'],
          message: 'Required',
        });
      }
      if (!data.actual) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['actual'],
          message: 'Required',
        });
      }
    }
    if (
      (data.type === 'ui_changed' ||
        data.type === 'heal_system_issue' ||
        data.type === 'unstable_locator') &&
      !data.description
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['description'],
        message: 'Required',
      });
    }
    if (data.type === 'broken_test_logic' && !data.reason) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['reason'],
        message: 'Required',
      });
    }
  });

export type CreateTriageVerdictFormValues = z.infer<
  typeof createTriageVerdictFormSchema
>;

// NO_VERDICT is an analysis output, never produced by the form, so it is
// excluded here to keep `buildPayload`'s switch exhaustive.
const FORM_TYPE_TO_VERDICT_TYPE: Record<
  FormType,
  Exclude<VerdictType, 'NO_VERDICT'>
> = {
  bug: 'BUG',
  ui_changed: 'UI_CHANGED',
  heal_system_issue: 'HEAL_SYSTEM_ISSUE',
  unstable_locator: 'UNSTABLE_LOCATOR',
  broken_test_logic: 'BROKEN_TEST_LOGIC',
};

export const buildSubmitPayload = (
  values: CreateTriageVerdictFormValues,
): VerdictSubmitPayload => ({
  payload: buildPayload(values),
  failingStatementIndex: values.failingStatementIndex ?? 0,
});

const buildPayload = (
  values: CreateTriageVerdictFormValues,
): VerdictSubmitPayload['payload'] => {
  const type = FORM_TYPE_TO_VERDICT_TYPE[values.type];
  switch (type) {
    case 'BUG':
      return {
        type: 'BUG',
        expected: values.expected ?? '',
        actual: values.actual ?? '',
      };
    case 'UI_CHANGED':
      return { type: 'UI_CHANGED', description: values.description ?? '' };
    case 'HEAL_SYSTEM_ISSUE':
      return {
        type: 'HEAL_SYSTEM_ISSUE',
        description: values.description ?? '',
      };
    case 'UNSTABLE_LOCATOR':
      return {
        type: 'UNSTABLE_LOCATOR',
        description: values.description ?? '',
      };
    case 'BROKEN_TEST_LOGIC':
      return {
        type: 'BROKEN_TEST_LOGIC',
        reason: values.reason ?? '',
        suggestedFix:
          values.suggestedFix && values.suggestedFix !== ''
            ? values.suggestedFix
            : null,
      };
  }
};

interface DraftSeed {
  type?: VerdictType;
  /** 0-based index of the statement the form is being opened for. */
  failingStatementIndex?: number;
}

export const buildDefaultValues = (
  verdict: TriagedVerdict | null,
  seed?: DraftSeed,
): CreateTriageVerdictFormValues => {
  const seededType = seed?.type
    ? VERDICT_TYPE_TO_FORM_TYPE[seed.type]
    : undefined;
  const seededIndex = seed?.failingStatementIndex;

  if (!verdict) {
    return {
      type: seededType ?? 'bug',
      expected: '',
      actual: '',
      description: '',
      reason: '',
      suggestedFix: '',
      comment: '',
      ...(seededIndex !== undefined && {
        failingStatementIndex: seededIndex,
      }),
    };
  }

  const base = {
    type: seededType ?? VERDICT_TYPE_TO_FORM_TYPE[verdict.payload.type],
    failingStatementIndex: seededIndex ?? verdict.failingStatementIndex,
    comment: '',
    expected: '',
    actual: '',
    description: '',
    reason: '',
    suggestedFix: '',
  };

  switch (verdict.payload.type) {
    case 'BUG':
      return {
        ...base,
        expected: verdict.payload.expected,
        actual: verdict.payload.actual,
      };
    case 'UI_CHANGED':
    case 'HEAL_SYSTEM_ISSUE':
    case 'UNSTABLE_LOCATOR':
      return { ...base, description: verdict.payload.description };
    case 'BROKEN_TEST_LOGIC':
      return {
        ...base,
        reason: verdict.payload.reason,
        suggestedFix: verdict.payload.suggestedFix ?? '',
      };
    case 'NO_VERDICT':
      return base;
  }
};
