import { PlayIcon, VideoIcon } from '@phosphor-icons/react';
import { useMemo } from 'react';

import {
  TraceViewerPagesContainer,
  TraceViewerVideoPlayer,
  type SegmentStatus,
  type TimelineSegment,
} from '../../../../../core/ui/features/trace-viewer';
import {
  useDataProvider,
  useVerdictStatement,
} from '../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../context/statement-provider/statement-provider.hooks';
import { useVideoProvider } from '../../../context/video-provider/video-provider.hooks';
import { Statement } from '../../../types/test';
import { EmptyState } from '../_components/empty-state';

const getSegmentStatus = (status: Statement['status']): SegmentStatus => {
  if (status === 'passed') {
    return 'pass';
  }

  return 'fail';
};

const buildSegments = (statements: Statement[]): TimelineSegment[] => {
  return statements.map((s) => ({
    id: String(s.id),
    startMs: s.timestampMs,
    endMs: s.timestampMs + s.durationMs,
    status: getSegmentStatus(s.status),
    label: s.code ?? undefined,
  }));
};

export const VIDEO_VIEW_ID = 'video';
export const VideoView = () => {
  const { currentTest } = useDataProvider();
  const { activeStatement } = useStatementProvider();
  const { controller, activeVideoId, setActiveVideoId } = useVideoProvider();
  const verdictHit = useVerdictStatement();

  const segments = useMemo(() => {
    if (!currentTest) {
      return [];
    }

    const built = buildSegments(currentTest.statements);
    if (!verdictHit) {
      return built;
    }
    const targetId = String(verdictHit.statement.id);

    return built.map((segment) =>
      segment.id === targetId
        ? { ...segment, verdictType: verdictHit.verdict.payload.type }
        : segment,
    );
  }, [currentTest, verdictHit]);

  if (!currentTest || currentTest.videos.length === 0) {
    return (
      <EmptyState
        icon={<PlayIcon size={32} className="opacity-60" />}
        message="No video available"
        size="compact"
      />
    );
  }

  return (
    <TraceViewerPagesContainer
      activePage={activeVideoId}
      onActivePageChange={setActiveVideoId}
      pages={currentTest.videos.map((video) => ({
        id: video.id,
        label: video.label,
        icon: <VideoIcon className="size-4" />,
        props: { url: video.url },
      }))}
      renderPage={({ url }) => (
        <TraceViewerVideoPlayer
          controller={controller}
          src={url}
          segments={segments}
          activeSegmentId={
            activeStatement ? String(activeStatement.id) : undefined
          }
        />
      )}
    />
  );
};
