import {
  Children,
  isValidElement,
  type ReactElement,
  type ReactNode,
} from 'react';

import {
  TraceViewerView,
  type ViewPane,
} from '../../../../core/ui/features/trace-viewer';
import {
  useCapabilities,
  useFeatures,
} from '../../context/capabilities-provider/capabilities-provider.hooks';
import type {
  TracerCapabilities,
  TracerFeatures,
} from '../../types/capabilities';

import { useLayoutContext } from './layout.context';
import { Pane, type PaneProps } from './pane';

interface SplitProps {
  direction: 'horizontal' | 'vertical';
  children: ReactNode;
}

interface InternalPane extends ViewPane {
  feature?: keyof TracerFeatures;
  capability?: keyof TracerCapabilities;
}

const isPaneElement = (child: ReactNode): child is ReactElement<PaneProps> => {
  return isValidElement(child) && child.type === Pane;
};

const collectPanes = (children: ReactNode): InternalPane[] => {
  const panes: InternalPane[] = [];

  Children.forEach(children, (child) => {
    // Skip falsy children so conditional rendering (`{flag && <Pane … />}`)
    // is supported.
    if (!isValidElement(child)) {
      return;
    }
    if (!isPaneElement(child)) {
      throw new Error('Row/Col only accept <Pane> as direct children');
    }

    const { id, children: content, feature, capability, ...rest } = child.props;
    panes.push({ id, content, feature, capability, ...rest });
  });

  return panes;
};

const isPaneVisible = (
  pane: InternalPane,
  features: TracerFeatures,
  capabilities: TracerCapabilities,
): boolean => {
  if (pane.feature && !features[pane.feature]) {
    return false;
  }
  if (pane.capability && !capabilities[pane.capability]) {
    return false;
  }

  return true;
};

const stripGates = (pane: InternalPane): ViewPane => {
  const { feature: _f, capability: _c, ...rest } = pane;

  return rest;
};

const Split = ({ direction, children }: SplitProps) => {
  const features = useFeatures();
  const capabilities = useCapabilities();
  const { getDefaultSizes, onLayoutChange } = useLayoutContext();

  const visiblePanes = collectPanes(children)
    .filter((pane) => isPaneVisible(pane, features, capabilities))
    .map(stripGates);

  if (visiblePanes.length === 0) {
    return null;
  }

  const defaultSizes = getDefaultSizes(visiblePanes.map((p) => p.id));

  return (
    <TraceViewerView
      direction={direction}
      panes={visiblePanes}
      defaultSizes={defaultSizes}
      onLayoutChange={onLayoutChange}
    />
  );
};

interface SplitMarkerProps {
  children: ReactNode;
  /** Render this row/col only when the named feature is enabled. */
  feature?: keyof TracerFeatures;
  /** Render this row/col only when the named capability is granted. */
  capability?: keyof TracerCapabilities;
}

const useGateGuard = (
  feature: keyof TracerFeatures | undefined,
  capability: keyof TracerCapabilities | undefined,
): boolean => {
  const features = useFeatures();
  const capabilities = useCapabilities();
  if (feature && !features[feature]) {
    return false;
  }
  if (capability && !capabilities[capability]) {
    return false;
  }

  return true;
};

export const Row = ({ children, feature, capability }: SplitMarkerProps) => {
  const allowed = useGateGuard(feature, capability);
  if (!allowed) {
    return null;
  }

  return <Split direction="horizontal">{children}</Split>;
};

export const Col = ({ children, feature, capability }: SplitMarkerProps) => {
  const allowed = useGateGuard(feature, capability);
  if (!allowed) {
    return null;
  }

  return <Split direction="vertical">{children}</Split>;
};
