import {
  BugIcon,
  CheckCircleIcon,
  CircleDashedIcon,
  CircleNotchIcon,
  GitDiffIcon,
  HourglassIcon,
  WrenchIcon,
  XCircleIcon,
} from '@phosphor-icons/react';
import type { IconProps } from '@phosphor-icons/react';
import type { ComponentType } from 'react';

import { cn } from '../../../lib/utils';
import { CustomTooltip } from '../../components/custom-tooltip/custom-tooltip';

// ─── Types ──────────────────────────────────────────────────────

export type VerdictResultStatus =
  | 'pending'
  | 'running'
  | 'passed'
  | 'failed'
  | 'skipped';

export type VerdictType =
  | 'BUG'
  | 'UI_CHANGED'
  | 'HEAL_SYSTEM_ISSUE'
  | 'UNSTABLE_LOCATOR'
  | 'BROKEN_TEST_LOGIC'
  | 'NO_VERDICT';

export type VerdictResultVariant = 'iconOnly' | 'compact' | 'expanded';

export type VerdictResultSize = 'sm' | 'md' | 'lg';

export interface VerdictResultIndicatorProps {
  status?: VerdictResultStatus;
  verdictType?: VerdictType;
  variant?: VerdictResultVariant;
  size?: VerdictResultSize;
  showTooltip?: boolean;
  className?: string;
  sideElement?: React.ReactNode;
}

// ─── Config ─────────────────────────────────────────────────────

export interface VerdictResultConfig {
  Icon: ComponentType<IconProps>;
  weight: IconProps['weight'];
  colorClass: string;
  accentClass: string;
  borderClass: string;
  label: string;
  description: string;
}

