// ─── Utility ────────────────────────────────────────────────────

export const getVerdictResultConfig = (
  status: VerdictResultStatus | undefined,
  verdictType?: VerdictType,
): VerdictResultConfig => {
  if (verdictType) {
    return VERDICT_CONFIG[verdictType];
  }

  if (!status) {
    return STATUS_CONFIG.pending;
  }

  return STATUS_CONFIG[status];
};

// ─── Size constants ─────────────────────────────────────────────

const ICON_SIZES: Record<VerdictResultSize, number> = {
  sm: 12,
  md: 16,
  lg: 18,
};

// ─── Component ──────────────────────────────────────────────────

export const VerdictResultIndicator = ({
  status,
  verdictType,
  variant = 'iconOnly',
  size = 'md',
  showTooltip,
  className,
  sideElement,
}: VerdictResultIndicatorProps) => {
  const config = getVerdictResultConfig(status, verdictType);
  const iconSize = ICON_SIZES[size];
  const shouldShowTooltip = showTooltip ?? variant === 'iconOnly';

  const icon = (
    <config.Icon
      size={iconSize}
      weight={config.weight}
      className={cn('shrink-0', config.colorClass)}
      aria-hidden
    />
  );

  if (variant === 'iconOnly') {
    return (
      <CustomTooltip content={config.description} enabled={shouldShowTooltip}>
        <span className={cn('inline-flex items-center', className)}>
          {icon}
        </span>
      </CustomTooltip>
    );
  }

  if (variant === 'compact') {
    const sizeClasses = (() => {
      if (size === 'sm') {
        return 'gap-1 text-[10px]';
      }
      if (size === 'lg') {
        return 'gap-1.5 text-sm';
      }

      return 'gap-1 text-xs';
    })();

    return (
      <CustomTooltip content={config.description} enabled={shouldShowTooltip}>
        <span
          className={cn(
            'inline-flex items-center font-medium whitespace-nowrap text-foreground',
            sizeClasses,
            className,
          )}
        >
          {icon}
          {config.label}
          <span>{sideElement}</span>
        </span>
      </CustomTooltip>
    );
  }

  // expanded
  const textSizeClass = (() => {
    if (size === 'sm') {
      return 'text-xs';
    }
    if (size === 'lg') {
      return 'text-sm';
    }

    return 'text-xs';
  })();

  const descSizeClass = (() => {
    if (size === 'sm') {
      return 'text-[10px]';
    }
    if (size === 'lg') {
      return 'text-xs';
    }

    return 'text-[11px]';
  })();

  return (
    <CustomTooltip content={config.description} enabled={shouldShowTooltip}>
      <div className={cn('flex flex-col gap-0.5', className)}>
        <span
          className={cn(
            'inline-flex items-center gap-1.5 font-medium text-foreground',
            textSizeClass,
          )}
        >
          {icon}
          {config.label}
          <span>{sideElement}</span>
        </span>
        <span className={cn('text-muted-foreground', descSizeClass)}>
          {config.description}
        </span>
      </div>
    </CustomTooltip>
  );
};
