import {
  Button,
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Textarea,
  VerdictResultIndicator,
} from '@heal/front-core/ui';
import { zodResolver } from '@hookform/resolvers/zod';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';

import { useDataProvider } from '../../../../context/data-provider/data-provider.hooks';
import { useEventProvider } from '../../../../context/event-provider/event-provider.hooks';
import { useTriageVerdictForm } from '../../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import {
  buildDefaultValues,
  buildSubmitPayload,
  createTriageVerdictFormSchema,
  FORM_TYPE_OPTIONS,
  VERDICT_TYPE_TO_FORM_TYPE,
  type CreateTriageVerdictFormValues,
  type FormType,
} from '../_lib/create-triage-verdict-form-schema';

import { StepField } from './step-field';
import { TypeFields } from './type-fields';

export const CreateTriageVerdictForm = () => {
  const { flatStatements } = useDataProvider();
  const { onVerdictCreate } = useEventProvider();
  const { state, close } = useTriageVerdictForm();

  const seed = {
    failingStatementIndex: state.selectedFailingStatementIndex,
    type: state.selectedType,
  };

  const form = useForm<CreateTriageVerdictFormValues>({
    defaultValues: buildDefaultValues(null, seed),
    resolver: zodResolver(createTriageVerdictFormSchema),
  });

  // Re-seed the form whenever the open() input changes (the menu may switch
  // from bug → ui_change without closing the form between).
  useEffect(() => {
    form.reset(
      buildDefaultValues(null, {
        failingStatementIndex: state.selectedFailingStatementIndex,
        type: state.selectedType,
      }),
    );
  }, [state.selectedFailingStatementIndex, state.selectedType, form]);

  const formType = form.watch('type');
  const failingStatementIndex = form.watch('failingStatementIndex');

  const stepOptions = flatStatements.map((statement) => ({
    value: statement.id,
    label: statement.code?.trim() ?? '',
    status: statement.status,
  }));

  const onSubmit = (values: CreateTriageVerdictFormValues) => {
    onVerdictCreate?.(buildSubmitPayload(values));
    close();
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLFormElement>) => {
    if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
      event.preventDefault();
      void form.handleSubmit(onSubmit)();
    }
  };

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        onKeyDown={handleKeyDown}
        className="flex flex-col gap-3"
      >
        <DraftHeader
          formType={formType}
          failingStatementIndex={failingStatementIndex}
        />

        <FormField
          control={form.control}
          name="type"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Report type</FormLabel>
              <Select value={field.value} onValueChange={field.onChange}>
                <FormControl>
                  <SelectTrigger className="h-8 w-full border-border bg-background text-xs">
                    <SelectValue />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {FORM_TYPE_OPTIONS.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </FormItem>
          )}
        />

        <StepField form={form} stepOptions={stepOptions} />

        <TypeFields formType={formType} form={form} />

        <FormField
          control={form.control}
          name="comment"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Comment (optional)</FormLabel>
              <FormControl>
                <Textarea
                  {...field}
                  className="min-h-[60px] border-border bg-background text-xs"
                  placeholder="Free-text rationale for this verdict"
                />
              </FormControl>
            </FormItem>
          )}
        />

        <div className="flex items-center justify-end gap-2">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={close}
            disabled={form.formState.isSubmitting}
          >
            Cancel
          </Button>
          <Button
            type="submit"
            variant="primary"
            size="sm"
            tooltip="Submit verdict (Cmd+Enter)"
            disabled={form.formState.isSubmitting}
          >
            Submit verdict
          </Button>
        </div>
      </form>
    </Form>
  );
};

const DraftHeader = ({
  formType,
  failingStatementIndex,
}: {
  formType: FormType;
  failingStatementIndex?: number;
}) => {
  const verdictType = FORM_TYPE_OPTIONS.find(
    (option) => option.value === formType,
  )?.verdictType;

  return (
    <div className="flex items-center gap-1.5 text-xs">
      {verdictType && (
        <VerdictResultIndicator
          verdictType={verdictType}
          variant="compact"
          size="md"
          showTooltip={false}
          sideElement={
            failingStatementIndex !== undefined && (
              <span className="font-normal text-muted-foreground">
                at step {failingStatementIndex + 1}
              </span>
            )
          }
        />
      )}
    </div>
  );
};

// Type re-export to satisfy isolatedModules (used by the schema's narrowing).
export type { CreateTriageVerdictFormValues };
export { VERDICT_TYPE_TO_FORM_TYPE };
