import { useQuery } from '@tanstack/react-query';

import { executionsKeys, getExecutions } from '../executions.api';

export const useExecutionsQuery = () =>
  useQuery({
    queryKey: executionsKeys.list(),
    queryFn: getExecutions,
  });
