import { useQuery } from '@tanstack/react-query';

import { executionsKeys, getExecutionIndex } from '../executions.api';

export const useExecutionIndexQuery = (executionId?: string) =>
  useQuery({
    queryKey: executionsKeys.index(executionId ?? ''),
    queryFn: () => getExecutionIndex(executionId as string),
    enabled: Boolean(executionId),
  });
