import type { editor } from 'monaco-editor/esm/vs/editor/editor.api.js';

// Read-only by construction. Anything that could pull in a language service or
// touch a worker (quickSuggestions, parameter hints, semantic highlighting,
// code lens, formatting on type, …) is explicitly off so the stub worker is
// never invoked.
export const READONLY_OPTIONS: editor.IStandaloneEditorConstructionOptions = {
  readOnly: true,
  domReadOnly: true,
  automaticLayout: true,
  // Needed to host the per-line verdict indicators (glyph margin widgets).
  glyphMargin: true,
  minimap: { enabled: false },
  scrollBeyondLastLine: false,
  renderLineHighlight: 'none',
  fontSize: 12,
  padding: { top: 12, bottom: 12 },
  overviewRulerBorder: false,
  overviewRulerLanes: 0,
  hideCursorInOverviewRuler: true,
  // Disabled — Monaco's built-in menu surfaces worker-dependent actions (Go to
  // Definition/References/Symbol) that are dead here. We render our own menu.
  contextmenu: false,
  quickSuggestions: false,
  parameterHints: { enabled: false },
  codeLens: false,
  inlayHints: { enabled: 'off' },
  occurrencesHighlight: 'off',
  selectionHighlight: false,
  links: false,
  folding: true,
  wordWrap: 'on',
  scrollbar: {
    useShadows: false,
    verticalScrollbarSize: 8,
    horizontalScrollbarSize: 8,
  },
};
