import type { TraceViewerGraphItemData } from '@heal/front-core/ui';
import { TraceViewerCodeGraphItem } from '@heal/front-core/ui';
import { FileTextIcon } from '@phosphor-icons/react';
import { useEffect, useRef } from 'react';

import {
  useDataProvider,
  useVerdictStatement,
} from '../../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../../context/statement-provider/statement-provider.hooks';
import { useTriageVerdictForm } from '../../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import type { Statement } from '../../../../types/test';
import { formatDuration } from '../../../../utils/format-duration';
import { ActionMenu } from '../../_components/action-menu';
import { EmptyState } from '../../_components/empty-state';

type VerdictHit = ReturnType<typeof useVerdictStatement>;

function mapStatement(
  statement: Statement,
  activeStatementId: number | undefined,
  verdictHit: VerdictHit,
  isFormOpen: boolean,
  onSelect: (id: number) => void,
): TraceViewerGraphItemData {
  const isVerdictStatement = verdictHit?.statement.id === statement.id;

  return {
    code: statement.code ?? '',
    id: statement.id,
    status: statement.status === 'passed' ? 'pass' : 'fail',
    duration: formatDuration(statement.durationMs),
    error: statement.error ?? undefined,
    file: statement.file,
    line: statement.line,
    active: activeStatementId === statement.id,
    selected: isFormOpen && isVerdictStatement,
    verdictType: isVerdictStatement
      ? verdictHit?.verdict.payload.type
      : undefined,
    onClick: (id) => onSelect(id),
    steps: statement.children
      .filter((c) => c.code !== null)
      .map((c) =>
        mapStatement(c, activeStatementId, verdictHit, isFormOpen, onSelect),
      ),
  };
}

interface CodeViewProps {
  /** Bumped by the tab-bar collapse/expand-all controls */
  collapseSignal?: number;
  /** Collapsed state applied to every row when `collapseSignal` changes */
  collapseValue?: boolean;
}

export const CodeView = ({ collapseSignal, collapseValue }: CodeViewProps) => {
  const { currentTest } = useDataProvider();
  const verdictHit = useVerdictStatement();
  const { state } = useTriageVerdictForm();

  if (!currentTest) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no content yet."
      />
    );
  }

  // Single scroll container (both axes): this view already lives inside the
  // scrollable TabsContent of TraceViewerContainer, so adding extra nested
  // overflow layers caused them to fight and clip the last rows. One scroller
  // here keeps the sticky right-hand icons working on horizontal scroll while
  // letting the full list scroll to the bottom.
  return (
    <div className="h-full w-full overflow-auto bg-code-editor-background p-2">
      <div className="inline-flex w-fit min-w-full flex-col">
        {currentTest.statements
          .filter((s) => s.code !== null)
          .map((statement) => (
            <TopLevelCodeItem
              key={statement.id}
              statement={statement}
              verdictHit={verdictHit}
              isFormOpen={state.isOpen}
              collapseSignal={collapseSignal}
              collapseValue={collapseValue}
            />
          ))}
      </div>
    </div>
  );
};

function TopLevelCodeItem({
  statement,
  verdictHit,
  isFormOpen,
  collapseSignal,
  collapseValue,
}: {
  statement: Statement;
  verdictHit: VerdictHit;
  isFormOpen: boolean;
  collapseSignal?: number;
  collapseValue?: boolean;
}) {
  const { activeStatement, selectActiveStatement } = useStatementProvider();
  const ref = useRef<HTMLDivElement>(null);
  const isActive = activeStatement?.id === statement.id;
  const isVerdictStatement = verdictHit?.statement.id === statement.id;

  useEffect(() => {
    if ((isActive || isVerdictStatement) && ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [isActive, isVerdictStatement]);

  return (
    <div ref={ref}>
      <ActionMenu
        failingStatementIndex={statement.id}
        file={statement.file}
        line={statement.line}
      >
        <TraceViewerCodeGraphItem
          {...mapStatement(
            statement,
            activeStatement?.id,
            verdictHit,
            isFormOpen,
            selectActiveStatement,
          )}
          collapseSignal={collapseSignal}
          collapseSignalValue={collapseValue}
          renderStep={({ step, element }) => (
            <div ref={ref}>
              <ActionMenu
                failingStatementIndex={step.id}
                file={step.file}
                line={step.line}
              >
                {element}
              </ActionMenu>
            </div>
          )}
        />
      </ActionMenu>
    </div>
  );
}
