import { useQuery } from '@tanstack/react-query';

import { analyzeKeys, getAnalyzeStatus } from '../analyze.api';

export const ANALYZE_POLL_INTERVAL_MS = 1500;

interface UseAnalyzeStatusQueryParams {
  executionId?: string;
  playwrightTestId?: string;
  attempt?: number;
  /** Only fetch for analyzable, fully-routed tests. */
  enabled: boolean;
  /**
   * Whether an analyze run is in flight. While true, poll until the
   * status reaches a terminal state. Tolerates a transient `null` (404
   * before `analyze.ndjson` exists) so we keep polling after a trigger.
   */
  poll: boolean;
}

export const useAnalyzeStatusQuery = ({
  executionId,
  playwrightTestId,
  attempt,
  enabled,
  poll,
}: UseAnalyzeStatusQueryParams) =>
  useQuery({
    queryKey: analyzeKeys.status(
      executionId ?? '',
      playwrightTestId ?? '',
      attempt ?? 0,
    ),
    queryFn: () =>
      getAnalyzeStatus(
        executionId as string,
        playwrightTestId as string,
        attempt as number,
      ),
    enabled,
    refetchInterval: (query) => {
      const status = query.state.data?.status;
      if (status === 'completed' || status === 'failed') {
        return false;
      }

      return poll ? ANALYZE_POLL_INTERVAL_MS : false;
    },
  });
