import { XCircleIcon } from '@phosphor-icons/react';

import type {
  FinalVerdict,
  TestFailure,
  TriagedVerdict,
} from '../../../../types/test';

import { VerdictBody } from './verdict-body';
import { VerdictHeadline } from './verdict-headline';

interface VerdictFormResultProps {
  failure: TestFailure | null;
  verdict: TriagedVerdict | FinalVerdict | null;
}

export const VerdictFormResult = ({
  failure,
  verdict,
}: VerdictFormResultProps) => {
  if (verdict) {
    return <VerdictDetails verdict={verdict} />;
  }
  if (failure) {
    return <FailureSummary failure={failure} />;
  }

  return (
    <div className="py-4 text-sm text-muted-foreground">
      No result recorded for this attempt.
    </div>
  );
};

const VerdictDetails = ({
  verdict,
}: {
  verdict: TriagedVerdict | FinalVerdict;
}) => (
  <div className="flex flex-col">
    <div className="sticky top-0 z-10 bg-background py-3">
      <VerdictHeadline verdict={verdict} />
    </div>
    <div className="pb-2">
      <VerdictBody verdict={verdict} />
    </div>
  </div>
);

const FailureSummary = ({ failure }: { failure: TestFailure }) => (
  <div className="flex items-start gap-2 py-4 text-sm leading-relaxed text-foreground">
    <XCircleIcon
      size={20}
      weight="fill"
      className="mt-0.5 shrink-0 text-danger-solid"
      aria-hidden
    />
    <p>Test failed: {failure.message}</p>
  </div>
);
