const mapStatementStatusToStepCardStatus = (
  status: StatementStatus,
): 'pass' | 'fail' => (status === 'passed' ? 'pass' : 'fail');

// ─── Verb → icon ─────────────────────────────────────────────────

const ACTION_ICON_MAP: { keywords: string[]; Icon: Icon }[] = [
  { keywords: ['navigate', 'open', 'visit', 'load', 'go'], Icon: GlobeIcon },
  { keywords: ['click', 'press', 'tap'], Icon: CursorClickIcon },
  { keywords: ['select', 'choose', 'pick'], Icon: HandPointingIcon },
  { keywords: ['type', 'fill', 'enter', 'input'], Icon: KeyboardIcon },
  { keywords: ['search', 'find', 'look'], Icon: MagnifyingGlassIcon },
  { keywords: ['wait', 'pause'], Icon: ClockIcon },
  {
    keywords: ['assert', 'verify', 'expect', 'check', 'ensure', 'confirm'],
    Icon: SealCheckIcon,
  },
  { keywords: ['submit', 'send'], Icon: PaperPlaneTiltIcon },
  { keywords: ['upload', 'attach'], Icon: UploadSimpleIcon },
  { keywords: ['download', 'export'], Icon: DownloadSimpleIcon },
  { keywords: ['scroll'], Icon: ArrowsDownUpIcon },
];

function getActionIcon(action: string): ReactNode {
  const normalized = action.trim().toLowerCase();
  const entry = ACTION_ICON_MAP.find((candidate) =>
    candidate.keywords.some((keyword) => normalized.startsWith(keyword)),
  );
  const IconComponent = entry?.Icon ?? BracketsCurlyIcon;

  return <IconComponent className="size-3.5" aria-hidden />;
}

// ─── Statement tree → action block data ──────────────────────────

interface BuildContext {
  activeStatementId: number | undefined;
  /** Whether the triage form is open for this top-level subtree. */
  formSelected: boolean;
  onSelect: (id: number) => void;
}

/**
 * Maps statements to the action block's recursive data shape.
 *
 * Comments live mostly on leaf actions while the hierarchy is carried by
 * comment-less wrappers, so:
 * - a commented statement becomes a row, nesting its (processed) children;
 * - a comment-less wrapper with a single resulting child is a pure pass-through
 *   and is dropped (collapses the deep wrapper chains);
 * - a comment-less wrapper that groups several actions promotes its first
 *   resulting child to head the group and nests the rest under it, so every
 *   collapsible row is a real action (no empty header rows).
 */
function buildActionNodes(
  statements: Statement[],
  ctx: BuildContext,
): TraceViewerActionBlockData[] {
  const nodes: TraceViewerActionBlockData[] = [];

  for (const statement of statements) {
    if (!hasComments(statement)) {
      continue;
    }

    const childNodes = buildActionNodes(statement.children, ctx);

    if (!statement.comment) {
      if (childNodes.length <= 1) {
        // Pure pass-through — drop the empty level, keep its child.
        nodes.push(...childNodes);
      } else {
        // Promote the first child to head the group; nest the rest under it.
        const [head, ...rest] = childNodes;
        nodes.push({ ...head, steps: [...(head.steps ?? []), ...rest] });
      }
      continue;
    }

    const { action, target } = splitComment(statement.comment);

    nodes.push({
      action,
      target,
      icon: getActionIcon(action),
      status: mapStatementStatusToStepCardStatus(statement.status),
      duration: formatDuration(statement.durationMs),
      error: statement.error ?? undefined,
      file: statement.file,
      line: statement.line,
      screenshotUrl: statement.screenshot ?? undefined,
      active: ctx.activeStatementId === statement.id,
      selected: ctx.formSelected,
      onClick: () => ctx.onSelect(statement.id),
      steps: childNodes,
    });
  }

  return nodes;
}

const MENU_HOVER_CLASS =
  'group-hover/menu:bg-brand-subtle/40 group-data-[state=open]/menu:bg-brand-subtle';

export const ActionView = () => {
  const { currentTest } = useDataProvider();
  const { activeStatement, selectActiveStatement } = useStatementProvider();
  const { state } = useTriageVerdictForm();

  if (!currentTest) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no content yet."
      />
    );
  }

  const hasAnyAction = currentTest.statements.some((statement) =>
    hasComments(statement),
  );

  if (!hasAnyAction) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no action items."
      />
    );
  }

  return (
    <div className="flex h-full flex-1 flex-col overflow-auto p-2">
      <div className="flex flex-col [&>*+*]:border-t [&>*+*]:border-border/60">
        {currentTest.statements.map((statement, index) => {
          if (!hasComments(statement)) {
            return null;
          }

          const nodes = buildActionNodes([statement], {
            activeStatementId: activeStatement?.id,
            formSelected:
              state.isOpen && state.selectedFailingStatementIndex === index,
            onSelect: selectActiveStatement,
          });

          // One context menu per top-level subtree: verdict actions seed the
          // top-level index (unchanged), while "explore code" resolves the
          // right-clicked row via its data-explore-* attributes.
          return (
            <ActionMenu
              key={statement.id}
              failingStatementIndex={statement.id}
              file={statement.file}
              line={statement.line}
            >
              {nodes.map((node, i) => (
                <TraceViewerActionBlock
                  key={i}
                  {...node}
                  classNames={{ root: MENU_HOVER_CLASS }}
                />
              ))}
            </ActionMenu>
          );
        })}
      </div>
    </div>
  );
};

const ACTION_VERBS = [
  'Navigate to',
  'Navigates to',
  'Click on',
  'Clicks on',
  'Click',
  'Clicks',
  'Fill in',
  'Fills in',
  'Fill',
  'Fills',
  'Type in',
  'Types in',
  'Type',
  'Types',
  'Wait for',
  'Waits for',
  'Select',
  'Selects',
  'Search for',
  'Searches for',
  'Submit',
  'Submits',
  'Scroll to',
  'Scrolls to',
  'Scroll',
  'Scrolls',
  'Upload',
  'Uploads',
  'Download',
  'Downloads',
  'Open',
  'Opens',
  'Close',
  'Closes',
  'Hover',
  'Hovers',
  'Check',
  'Checks',
  'Uncheck',
  'Unchecks',
  'Accept',
  'Accepts',
  'Dismiss',
  'Dismisses',
  'Verify',
  'Verifies',
  'Assert',
  'Asserts',
  'Expect',
  'Expects',
];

function splitComment(comment: string | null): {
  action: string;
  target: string;
} {
  if (!comment) {
    return { action: '', target: '' };
  }

  const cleaned = comment.replace(/^-+\s*|\s*-+$/g, '').trim();

  const lowerCleaned = cleaned.toLowerCase();
  for (const verb of ACTION_VERBS) {
    if (lowerCleaned.startsWith(verb.toLowerCase() + ' ')) {
      return {
        action: verb,
        target: cleaned.slice(verb.length + 1),
      };
    }
  }

  const [action, ...rest] = cleaned.split(' ');

  return { action, target: rest.join(' ') };
}

function hasComments(statement: Statement): boolean {
  return (
    !!statement.comment ||
    statement.children.some((child) => hasComments(child))
  );
}
