import { cn } from '@heal/front-core/lib/utils';

import { type AuthQuota, useAuth } from '../../../lib/auth-context';

// Compact "12.4k / 1M" rendering — compresses large counts to keep the
// widget narrow while staying readable. Under 10k, no rounding.
const formatTokenCount = (n: number): string => {
  if (n < 10_000) return n.toLocaleString();
  if (n < 1_000_000) return `${(n / 1_000).toFixed(n < 100_000 ? 1 : 0)}k`;

  return `${(n / 1_000_000).toFixed(n < 10_000_000 ? 1 : 0)}M`;
};

const WARN_THRESHOLD = 0.7;

// Hide the quota slot if the usage is less than 90% of the limit
const DISPLAY_THRESHOLD = 0.9;

const fillColorClass = (pct: number, reached: boolean): string => {
  if (reached || pct >= 1) return 'bg-danger-solid';
  if (pct >= WARN_THRESHOLD) return 'bg-warning-solid';

  return 'bg-brand-solid';
};

/**
 * Renders the quota widget in the standalone tracer's top bar. Reads the
 * token quota directly from the auth context (`heal quota --json`). Opt-in:
 * renders nothing when the quota is unavailable or usage is below the 90%
 * display threshold.
 *
 * Layout: raw "<used> / <limit> tokens" label on top, a thin horizontal
 * progress bar underneath. Bar fills proportionally and changes colour
 * at 70% (warning) and 100% / hasReachedLimit (danger).
 */

export const Quota = () => {
  const { quotaState } = useAuth();
  const quota = quotaState.status === 'ok' ? quotaState.quota : null;

  if (!quota) {
    return null;
  }

  const pct = getPercentage(quota);
  const pctClamped = getPercentageClamped(pct);

  const label = formatLabel(quota);
  const fill = fillColorClass(pctClamped, quota.hasReachedLimit);
  const tooltip = formatTooltip(quota, pctClamped);

  // if (pctClamped < DISPLAY_THRESHOLD) {
  //   return null;
  // }

  return (
    <div
      className={cn(
        'inline-flex h-8 w-[160px] flex-col items-center justify-center gap-1 px-2',
      )}
      title={tooltip}
      role="meter"
      aria-valuemin={0}
      aria-valuemax={quota.tokenLimit}
      aria-valuenow={quota.tokenCurrentUsage}
      aria-label="Heal token quota"
    >
      <span
        className={cn(
          'w-full truncate text-center text-[10px] leading-none tabular-nums',
          quota.hasReachedLimit
            ? 'font-medium text-danger-solid'
            : 'text-muted-foreground',
        )}
      >
        {label}
      </span>
      <div
        className="h-1 w-full overflow-hidden rounded-full bg-muted"
        aria-hidden
      >
        <div
          className={cn('h-full transition-[width]', fill)}
          style={{ width: `${(pctClamped * 100).toFixed(1)}%` }}
        />
      </div>
    </div>
  );
};

const formatLabel = (q: AuthQuota): string =>
  `${formatTokenCount(q.tokenCurrentUsage)} / ${formatTokenCount(q.tokenLimit)} tokens`;

const formatTooltip = (q: AuthQuota, pct: number): string => {
  const exact = `${q.tokenCurrentUsage.toLocaleString()} / ${q.tokenLimit.toLocaleString()} tokens (${Math.round(pct * 100)}%)`;

  return q.hasReachedLimit ? `${exact}\nQuota limit reached.` : exact;
};

function getPercentage(q: AuthQuota): number {
  return q.tokenLimit > 0 ? q.tokenCurrentUsage / q.tokenLimit : 0;
}

function getPercentageClamped(pct: number): number {
  return Math.min(1, Math.max(0, pct));
}
