import { ArrowRightIcon } from '@phosphor-icons/react';
import type { KeyboardEvent } from 'react';

import { cn } from '../../../lib/utils';
import { Button } from '../../components/button/button';
import { Textarea } from '../../components/textarea/textarea';
import {
  VerdictResultIndicator,
  type VerdictResultStatus,
  type VerdictType,
} from '../verdict-result-indicator/verdict-result-indicator';

// ─── Types ──────────────────────────────────────────────────────

export interface VerdictFormOptionInput {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
}

export interface VerdictFormOptionConfirmation {
  label: string;
  onConfirm: () => void;
  isPending?: boolean;
  disabled?: boolean;
}

export interface VerdictFormOptionProps {
  letter?: string;
  title: string;
  description?: string;
  savedDescription?: string;
  verdictType?: VerdictType;
  status?: VerdictResultStatus;
  selected: boolean;
  saved?: boolean;
  onSelect: () => void;
  disabled?: boolean;
  input?: VerdictFormOptionInput;
  confirmation?: VerdictFormOptionConfirmation;
  className?: string;
}

// ─── Component ──────────────────────────────────────────────────

export const VerdictFormOption = ({
  letter,
  title,
  description,
  savedDescription,
  verdictType,
  status,
  selected,
  saved = false,
  onSelect,
  disabled = false,
  input,
  confirmation,
  className,
}: VerdictFormOptionProps) => {
  const hasIcon = verdictType !== undefined || status !== undefined;
  const hasInput = input !== undefined;
  const hasConfirmation = confirmation !== undefined;
  const inlineConfirmation = hasConfirmation && !hasInput;
  const isExpanded = selected && !saved;
  const visibleDescription =
    saved && savedDescription !== undefined ? savedDescription : description;

  const containerClass = (() => {
    if (selected) {
      return 'border-brand-solid ring-2 ring-brand-solid/30 bg-surface';
    }

    return 'border-border bg-surface hover:bg-muted/40';
  })();

  const handleClick = () => {
    if (disabled) {
      return;
    }
    onSelect();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) {
      return;
    }
    if (event.target !== event.currentTarget) {
      return;
    }
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      onSelect();
    }
  };

  return (
    <div
      role="radio"
      aria-checked={selected}
      aria-disabled={disabled}
      tabIndex={disabled ? -1 : 0}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      className={cn(
        'flex w-full flex-col rounded-lg border p-4 text-left',
        'transition-[box-shadow,border-color,background-color] duration-200 ease-out',
        'focus:outline-none focus-visible:ring-2 focus-visible:ring-foreground/40',
        disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
        containerClass,
        className,
      )}
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-start gap-3">
          {hasIcon && (
            <span className="mt-0.5 inline-flex items-center">
              <VerdictResultIndicator
                verdictType={verdictType}
                status={status}
                variant="iconOnly"
                size="md"
                showTooltip={false}
              />
            </span>
          )}
          <span className="flex flex-col">
            <span className="text-sm font-semibold text-foreground">
              {letter ? `${letter}. ${title}` : title}
            </span>
            {visibleDescription && (
              <span className="mt-0.5 text-sm text-muted-foreground">
                {visibleDescription}
              </span>
            )}
          </span>
        </div>
        {inlineConfirmation && (
          <div
            aria-hidden={!isExpanded}
            className={cn(
              'shrink-0 transition-opacity duration-300 ease-out',
              isExpanded ? 'opacity-100' : 'pointer-events-none opacity-0',
            )}
          >
            <VerdictFormOptionConfirmButton
              confirmation={confirmation}
              disabled={disabled}
            />
          </div>
        )}
      </div>
      {hasInput && (
        <div
          aria-hidden={!isExpanded}
          className={cn(
            'grid transition-[grid-template-rows,opacity] duration-300 ease-out',
            isExpanded
              ? 'grid-rows-[1fr] opacity-100'
              : 'pointer-events-none grid-rows-[0fr] opacity-0',
          )}
        >
          <div className="overflow-hidden">
            <div className="flex flex-col gap-3 pt-3">
              <VerdictFormOptionInputArea input={input} disabled={disabled} />
              {hasConfirmation && (
                <VerdictFormOptionConfirmButton
                  confirmation={confirmation}
                  disabled={disabled}
                />
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// ─── Input area ─────────────────────────────────────────────────

interface VerdictFormOptionInputAreaProps {
  input: VerdictFormOptionInput;
  disabled: boolean;
}

const VerdictFormOptionInputArea = ({
  input,
  disabled,
}: VerdictFormOptionInputAreaProps) => {
  const {
    value,
    onChange,
    placeholder,
    disabled: inputDisabled = false,
  } = input;

  const handleChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    onChange(event.target.value);
  };

  const handleClick = (event: React.MouseEvent) => {
    event.stopPropagation();
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    event.stopPropagation();
  };

  return (
    <div onClick={handleClick} onKeyDown={handleKeyDown}>
      <Textarea
        value={value}
        onChange={handleChange}
        placeholder={placeholder}
        disabled={disabled || inputDisabled}
        className="min-h-[42px] resize-none border-border bg-surface text-sm text-foreground placeholder:text-muted-foreground focus-visible:ring-0 focus-visible:ring-offset-0"
      />
    </div>
  );
};

// ─── Confirm button ─────────────────────────────────────────────

interface VerdictFormOptionConfirmButtonProps {
  confirmation: VerdictFormOptionConfirmation;
  disabled: boolean;
}

const VerdictFormOptionConfirmButton = ({
  confirmation,
  disabled,
}: VerdictFormOptionConfirmButtonProps) => {
  const {
    label,
    onConfirm,
    isPending = false,
    disabled: confirmDisabled = false,
  } = confirmation;

  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    onConfirm();
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    event.stopPropagation();
  };

  return (
    <div className="flex justify-end">
      <Button
        type="button"
        variant="secondary"
        size="sm"
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        disabled={disabled || confirmDisabled || isPending}
        className="gap-2"
      >
        {label}
        <ArrowRightIcon size={14} weight="bold" aria-hidden />
      </Button>
    </div>
  );
};
