import type { AnalyzeState, TriagedVerdict } from '@heal-dev/front-run-viewer';
import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect, useMemo, useState } from 'react';

import {
  analyzeFailureToTriaged,
  analyzeVerdictToTriaged,
} from '../../../lib/analyze-to-verdict';
import { useAuth } from '../../../lib/auth-context';
import type { AnalyzeRunStatus, TestSummary } from '../../types';
import { analyzeKeys, startAnalyze } from '../analyze.api';

import { useAnalyzeStatusQuery } from './use-analyze-status-query';
import { useStartAnalyzeMutation } from './use-start-analyze-mutation';

const ANALYZE_ALL_CONCURRENCY = 10;

/**
 * Fan an async `worker` across `items` with a fixed pool size. Failures are
 * absorbed inside the worker — this helper never rejects. Used to dispatch a
 * batch of analyze POSTs without saturating the LLM rate limit; per-test
 * state is surfaced separately via polling.
 */
async function runWithConcurrency<T>(
  items: readonly T[],
  concurrency: number,
  worker: (item: T) => Promise<void>,
): Promise<void> {
  let index = 0;
  const runner = async (): Promise<void> => {
    while (index < items.length) {
      const i = index++;
      try {
        await worker(items[i]);
      } catch {
        // Swallow — per-test polling owns failure surfacing.
      }
    }
  };
  const workers = Array.from(
    { length: Math.min(concurrency, items.length) },
    runner,
  );
  await Promise.all(workers);
}

interface UseAnalyzeParams {
  executionId?: string;
  testId?: string;
  attempt?: number;
  /** Whether the current trace is analyzable (failed/timedOut/interrupted). */
  analyzable: boolean;
  /** Raw per-attempt index rows, used to derive the "Analyze all" batch. */
  rawSummaries: TestSummary[];
}

interface UseAnalyzeResult {
  analyzeState: AnalyzeState;
  /** Synthesised verdict for the current test, or null while none/running. */
  triagedVerdict: TriagedVerdict | null;
  onTrigger: () => void;
  isTriggering: boolean;
  onTriggerAll: () => void;
  isTriggeringAll: boolean;
  failingTestCount: number;
}

/**
 * Owns the analyze lifecycle for the currently-viewed attempt: a polling
 * status query, the single-test trigger, and the batch "Analyze all" fan-out.
 * Replaces the imperative `analyzeState` machine + `setTimeout` poll that
 * used to live in `app.tsx`.
 */
export const useAnalyze = ({
  executionId,
  testId,
  attempt,
  analyzable,
  rawSummaries,
}: UseAnalyzeParams): UseAnalyzeResult => {
  const { refreshQuota } = useAuth();
  const queryClient = useQueryClient();
  const enabled = Boolean(executionId && testId && attempt && analyzable);

  // Durable "a run is in flight" intent. Survives the transient 404 window
  // between a successful POST and the first `running` event on disk, so we
  // keep polling. Reset whenever the viewed attempt changes.
  const [poll, setPoll] = useState(false);

  const statusQuery = useAnalyzeStatusQuery({
    executionId,
    playwrightTestId: testId,
    attempt,
    enabled,
    poll,
  });
  const startMutation = useStartAnalyzeMutation();

  const status = statusQuery.data ?? null;
  const statusKind = status?.status;

  // Reset poll intent when navigating to a different attempt.
  useEffect(() => {
    setPoll(false);
  }, [executionId, testId, attempt]);

  // Start polling once a run is detected; stop on a terminal status.
  useEffect(() => {
    if (statusKind === 'running') {
      setPoll(true);
    }
    if (statusKind === 'completed' || statusKind === 'failed') {
      setPoll(false);
    }
  }, [statusKind]);

  // Refresh quota on terminal transitions — even errors burn tokens.
  useEffect(() => {
    if (statusKind === 'completed' || statusKind === 'failed') {
      void refreshQuota();
    }
  }, [statusKind, refreshQuota]);

  const analyzeState = useMemo<AnalyzeState>(() => {
    if (!analyzable) {
      return { kind: 'unknown' };
    }
    if (startMutation.isError) {
      return { kind: 'failed', message: startMutation.error.message };
    }
    if (status?.status === 'completed') {
      return { kind: 'completed' };
    }
    if (status?.status === 'failed') {
      return { kind: 'failed', message: status.message };
    }
    if (startMutation.isPending || poll || status?.status === 'running') {
      return { kind: 'running' };
    }
    if (statusQuery.isFetched) {
      return { kind: 'none' };
    }

    return { kind: 'unknown' };
  }, [
    analyzable,
    startMutation.isError,
    startMutation.error,
    startMutation.isPending,
    status,
    poll,
    statusQuery.isFetched,
  ]);

  const triagedVerdict = useMemo<TriagedVerdict | null>(() => {
    if (!executionId || !testId || attempt === undefined) {
      return null;
    }
    if (status?.status === 'completed') {
      return analyzeVerdictToTriaged(
        status.verdict,
        executionId,
        testId,
        attempt,
      );
    }
    if (status?.status === 'failed') {
      return analyzeFailureToTriaged(
        status.message,
        executionId,
        testId,
        attempt,
      );
    }

    return null;
  }, [status, executionId, testId, attempt]);

  const onTrigger = useCallback(() => {
    if (!executionId || !testId || attempt === undefined) {
      return;
    }
    setPoll(true);
    startMutation.mutate({ executionId, playwrightTestId: testId, attempt });
  }, [executionId, testId, attempt, startMutation]);

  /**
   * Latest failing attempt per failing test in the current execution,
   * EXCLUDING tests that already have an analyze verdict on disk. Drives the
   * "Analyze all N failing tests" count and fan-out. Terminal errors don't
   * set `hasAnalyzeVerdict`, so previously-failed analyses remain candidates.
   */
  const failingAttempts = useMemo(() => {
    const latestByTest = new Map<string, TestSummary>();
    for (const s of rawSummaries) {
      const prev = latestByTest.get(s.playwrightTestId);
      if (!prev || s.attempt > prev.attempt) {
        latestByTest.set(s.playwrightTestId, s);
      }
    }
    const out: { playwrightTestId: string; attempt: number }[] = [];
    for (const s of latestByTest.values()) {
      if (
        (s.status === 'failed' || s.status === 'timedOut') &&
        !s.hasAnalyzeVerdict
      ) {
        out.push({ playwrightTestId: s.playwrightTestId, attempt: s.attempt });
      }
    }

    return out;
  }, [rawSummaries]);

  const [isTriggeringAll, setIsTriggeringAll] = useState(false);

  const onTriggerAll = useCallback(() => {
    if (
      !executionId ||
      isTriggeringAll ||
      startMutation.isPending ||
      failingAttempts.length === 0
    ) {
      return;
    }
    const currentInBatch =
      testId !== undefined &&
      attempt !== undefined &&
      failingAttempts.some(
        (a) => a.playwrightTestId === testId && a.attempt === attempt,
      );
    setIsTriggeringAll(true);
    // If the viewed test is in the batch, seed its status to running so its
    // verdict pane clears immediately and polling latches on. Uses the raw
    // api (not the single-test mutation) so a batch failure never leaks into
    // the current test's analyze state.
    if (currentInBatch && executionId && testId && attempt !== undefined) {
      queryClient.setQueryData<AnalyzeRunStatus | null>(
        analyzeKeys.status(executionId, testId, attempt),
        { status: 'running' },
      );
      setPoll(true);
    }
    // Fan out POSTs at concurrency=10. Per-test polling owns failure
    // surfacing, so absorb errors here.
    void runWithConcurrency(failingAttempts, ANALYZE_ALL_CONCURRENCY, (item) =>
      startAnalyze(executionId, item.playwrightTestId, item.attempt).then(
        () => undefined,
        () => undefined,
      ),
    ).finally(() => {
      setIsTriggeringAll(false);
    });
  }, [
    executionId,
    testId,
    attempt,
    failingAttempts,
    isTriggeringAll,
    startMutation.isPending,
    queryClient,
  ]);

  return {
    analyzeState,
    triagedVerdict,
    onTrigger,
    isTriggering: startMutation.isPending,
    onTriggerAll,
    isTriggeringAll,
    failingTestCount: failingAttempts.length,
  };
};
