import { ChevronDownIcon, ChevronRightIcon } from 'lucide-react';
import { type ReactNode, useEffect, useRef, useState } from 'react';

import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from '../../../../lib/shadcn/hover-card';
import { cn } from '../../../../lib/utils';
import type { TraceViewerErrorInfo } from '../stack-trace/trace-viewer-stack-trace';
import { TraceViewerStackTrace } from '../stack-trace/trace-viewer-stack-trace';
import type { StepCardStatus, VerdictType } from '../step-card/use-step-config';
import { useStepConfig } from '../step-card/use-step-config';

// ─── Types ──────────────────────────────────────────────────────

export interface TraceViewerActionBlockClassNames {
  /** Card wrapper */
  root?: string;
  /** Left accent bar */
  accent?: string;
  /** Action verb */
  action?: string;
  /** Target value chip */
  target?: string;
  /** Right meta area (screenshot + duration) */
  meta?: string;
  /** Screenshot thumbnail */
  screenshot?: string;
}

export interface TraceViewerActionBlockData {
  /** The action verb (e.g. "Navigate to", "Click", "Type") */
  action: string;
  /** The target or argument (e.g. URL, selector, text value) */
  target?: string;
  /** Optional icon before the action verb */
  icon?: ReactNode;
  /** Step status */
  status?: StepCardStatus;
  /** Verdict type (overrides status icon via the step config) */
  verdictType?: VerdictType;
  /** Duration text (e.g. "1.2s") */
  duration?: string;
  /** Screenshot thumbnail URL */
  screenshotUrl?: string;
  /** Callback when the screenshot is clicked */
  onScreenshotClick?: () => void;
  /** Video is currently at this step */
  active?: boolean;
  /** User has selected this step for inspection */
  selected?: boolean;
  /** Error surfaced in a hover card (mirrors the code graph item) */
  error?: TraceViewerErrorInfo;
  /**
   * Source file for this step. Surfaced as a `data-explore-file` attribute on
   * the row so a host context menu can resolve "explore code" to the exact row
   * that was clicked (rather than the top-level step).
   */
  file?: string | null;
  /** 1-based source line for this step; paired with `file`. */
  line?: number | null;
  /** Content rendered below the row (e.g. output logs) */
  bottomContent?: ReactNode;
  /**
   * Render no row of its own — only its indented children. Use for structural
   * groups that should keep their nesting without showing a header (e.g. a
   * comment-less wrapper that still groups several actions).
   */
  headerless?: boolean;
  /** Nested child actions — named `steps` to avoid React's reserved `children` */
  steps?: TraceViewerActionBlockData[];
  /** Callback when the card is clicked */
  onClick?: () => void;
  /** Style overrides */
  classNames?: TraceViewerActionBlockClassNames;
}

export interface TraceViewerActionBlockProps extends TraceViewerActionBlockData {
  /** Nesting depth (informational; nesting is rendered via indentation) */
  depth?: number;
  /** Whether nested steps start collapsed */
  defaultCollapsed?: boolean;
  /** Draw the vertical tree line connecting nested steps */
  showIndentGuides?: boolean;
  /** Bump this to broadcast a collapse/expand-all to the whole subtree */
  collapseSignal?: number;
  /** Collapsed state applied to every card when `collapseSignal` changes */
  collapseSignalValue?: boolean;
}

// ─── Component ──────────────────────────────────────────────────

export const TraceViewerActionBlock = ({
  action,
  target,
  icon,
  status,
  verdictType,
  duration,
  screenshotUrl,
  onScreenshotClick,
  active = false,
  selected = false,
  error,
  file,
  line,
  bottomContent,
  headerless = false,
  steps = [],
  onClick,
  classNames,
  depth = 0,
  defaultCollapsed = false,
  showIndentGuides = true,
  collapseSignal,
  collapseSignalValue = false,
}: TraceViewerActionBlockProps) => {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);

  // Collapse/expand-all broadcast: when a parent bumps `collapseSignal`, snap
  // this card to the requested state. Guarded on `undefined` so the first mount
  // keeps its own `defaultCollapsed` value instead of being forced open.
  useEffect(() => {
    if (collapseSignal === undefined) return;
    setCollapsed(collapseSignalValue);
  }, [collapseSignal, collapseSignalValue]);

  const stepConfig = useStepConfig({ status, verdictType });

  const isParent = steps.length > 0;
  const isInteractive = isParent || !!onClick;

  // Bring the active row into view when playback/selection lands on it.
  const rowRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (active && rowRef.current) {
      rowRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [active]);

  const handleScreenshotClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onScreenshotClick?.();
  };

  // Section-header layout: a parent reads as a lightweight header (chevron +
  // status + count) and its children render as flat rows beneath it — no boxes
  // or tree lines, hierarchy comes from indentation and the header weight.
  const row = (
    <div
      ref={rowRef}
      data-explore-file={file ?? undefined}
      data-explore-line={line ?? undefined}
      className={cn(
        'flex items-center gap-2 rounded-md px-2 py-1.5 text-sm transition-colors',
        isParent && 'bg-muted/30 font-medium',
        isInteractive && 'cursor-pointer hover:bg-muted/60',
        active && !selected && 'bg-muted',
        selected && stepConfig.selectedBg,
        error && 'cursor-help',
        classNames?.root,
      )}
      onClick={
        isParent
          ? (e) => {
              e.stopPropagation();
              setCollapsed((c) => !c);
              onClick?.();
            }
          : onClick
      }
    >
      {/* Chevron — parents only; invisible spacer keeps leaf rows aligned */}
      {isParent ? (
        <span className="flex w-4 shrink-0 items-center justify-center text-muted-foreground/70">
          {collapsed ? (
            <ChevronRightIcon className="size-3.5" />
          ) : (
            <ChevronDownIcon className="size-3.5" />
          )}
        </span>
      ) : (
        <span aria-hidden className="w-4 shrink-0" />
      )}

      {/* Status / verdict icon */}
      <span className="flex shrink-0 items-center">{stepConfig.icon}</span>

      {/* Action icon */}
      {icon && <span className="shrink-0 text-muted-foreground">{icon}</span>}

      {/* Action verb — bolder on parents so they read as section headers */}
      <span
        className={cn(
          'shrink-0 truncate',
          isParent ? 'text-foreground' : 'font-normal text-muted-foreground',
          classNames?.action,
        )}
      >
        {action}
      </span>

      {/* Target chip */}
      {target && (
        <code
          className={cn(
            'truncate rounded bg-muted px-1.5 py-0.5 font-mono text-xs font-normal text-foreground',
            classNames?.target,
          )}
        >
          {target}
        </code>
      )}

      {/* Meta — duration, screenshot, and a child-count badge on parents */}
      <span
        className={cn(
          'ml-auto flex shrink-0 items-center gap-2 pl-2',
          classNames?.meta,
        )}
      >
        {/* Small thumbnail — indicates the step has a linked screenshot */}
        {screenshotUrl && (
          <button
            type="button"
            onClick={onScreenshotClick ? handleScreenshotClick : undefined}
            title="Screenshot"
            className={cn(
              'relative h-6 w-9 shrink-0 overflow-hidden rounded border border-border',
              onScreenshotClick && 'cursor-pointer hover:opacity-80',
              classNames?.screenshot,
            )}
          >
            <img
              src={screenshotUrl}
              alt="Step screenshot"
              className="h-full w-full object-cover"
            />
          </button>
        )}
        {duration && (
          <span className="text-xs font-normal tabular-nums text-muted-foreground">
            {duration}
          </span>
        )}
        {isParent && (
          <span className="flex h-4 min-w-4 items-center justify-center rounded-full border border-border px-1 text-[10px] font-medium tabular-nums text-muted-foreground">
            {steps.length}
          </span>
        )}
      </span>
    </div>
  );

  // Wrap only this row in the error hover card — nested steps carry their own
  // errors, so the trigger must not extend over them.
  const rowWithError = error ? (
    <HoverCard openDelay={500} closeDelay={300}>
      <HoverCardTrigger asChild>{row}</HoverCardTrigger>
      <HoverCardContent
        align="start"
        sideOffset={6}
        className="w-[600px] max-w-[90vw] overflow-hidden p-0"
      >
        <TraceViewerStackTrace error={error} />
      </HoverCardContent>
    </HoverCard>
  ) : (
    row
  );

  return (
    <div className="w-full">
      {headerless ? (
        // Header-less group: no real row, just a fold toggle in the gutter so
        // the structural group stays collapsible. Its children render one level
        // deeper (the `pl-6` container below).
        isParent && (
          <div
            onClick={() => setCollapsed((c) => !c)}
            className="flex cursor-pointer items-center px-2 py-0.5 text-muted-foreground/50 hover:text-muted-foreground"
          >
            <span className="flex w-4 shrink-0 items-center justify-center">
              {collapsed ? (
                <ChevronRightIcon className="size-3.5" />
              ) : (
                <ChevronDownIcon className="size-3.5" />
              )}
            </span>
          </div>
        )
      ) : (
        <>
          {rowWithError}
          {bottomContent && <div className="py-1 pl-7">{bottomContent}</div>}
        </>
      )}

      {/* Nested steps — flat rows indented beneath the header */}
      {isParent && !collapsed && (
        <div
          className={cn(
            'flex flex-col gap-0.5 pl-6',
            !headerless && 'mt-0.5 pb-1',
          )}
        >
          {steps.map((step, i) => (
            <TraceViewerActionBlock
              key={i}
              {...step}
              depth={depth + 1}
              showIndentGuides={showIndentGuides}
              collapseSignal={collapseSignal}
              collapseSignalValue={collapseSignalValue}
            />
          ))}
        </div>
      )}
    </div>
  );
};
