import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from 'react';

import { baseApiPath } from '../api/http';

export interface AuthProfile {
  email: string;
  firstName?: string;
  lastName?: string;
  username?: string;
  organization?: { name: string; slug: string };
}

export type AuthState =
  | { status: 'loading' }
  | { status: 'not_installed' }
  | { status: 'logged_out' }
  | { status: 'logged_in'; profile: AuthProfile };

export interface AuthQuota {
  tokenLimit: number;
  tokenCurrentUsage: number;
  hasReachedLimit: boolean;
}

/**
 * Quota lifecycle is tied to auth (same API key, same lifecycle): we
 * only fetch when the user is logged in, and refresh whenever an
 * analyze run completes.
 *  - `unavailable` covers not-logged-in, org keys (quotas don't apply),
 *    and fetch errors — UI treats them the same (just don't render).
 *  - `loading` only before the first fetch resolves.
 */
export type QuotaState =
  | { status: 'loading' }
  | { status: 'unavailable' }
  | { status: 'ok'; quota: AuthQuota };

interface AuthContextValue {
  state: AuthState;
  signIn: () => void;
  refresh: () => Promise<void>;
  quotaState: QuotaState;
  refreshQuota: () => Promise<void>;
}

const Ctx = createContext<AuthContextValue | null>(null);

export const useAuth = (): AuthContextValue => {
  const v = useContext(Ctx);
  if (!v) {
    throw new Error('useAuth must be used inside <AuthProvider>');
  }

  return v;
};

const POLL_MS = 250;
const WHOAMI_TIMEOUT_MS = 8_000;
const QUOTA_TIMEOUT_MS = 8_000;
const AUTH_URL_TIMEOUT_MS = 10_000;

interface JobSnapshot {
  status: 'running' | 'exited';
  exitCode: number | null;
  stdout: string[];
  stderr: string[];
}

class ExecForbidden extends Error {}

async function startExec(bin: string, args: string[]): Promise<string> {
  const res = await fetch(baseApiPath('/api/exec'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ bin, args }),
  });
  if (res.status === 403) {
    throw new ExecForbidden();
  }
  if (!res.ok) {
    throw new Error(`/api/exec ${res.status}`);
  }
  const body = (await res.json()) as { jobId: string };

  return body.jobId;
}

async function pollJob(jobId: string): Promise<JobSnapshot> {
  const res = await fetch(baseApiPath(`/api/exec/${jobId}`));
  if (!res.ok) {
    throw new Error(`/api/exec/${jobId} ${res.status}`);
  }

  return (await res.json()) as JobSnapshot;
}

function parseLastJsonLine(lines: string[]): Record<string, unknown> | null {
  for (let i = lines.length - 1; i >= 0; i--) {
    const t = lines[i].trim();
    if (!t.startsWith('{')) {
      continue;
    }
    try {
      return JSON.parse(t) as Record<string, unknown>;
    } catch {
      // keep scanning
    }
  }

  return null;
}

const wait = (ms: number): Promise<void> =>
  new Promise((r) => setTimeout(r, ms));

async function fetchWhoami(): Promise<AuthState> {
  let jobId: string;
  try {
    jobId = await startExec('heal', ['whoami', '--json']);
  } catch (err) {
    if (err instanceof ExecForbidden) {
      return { status: 'not_installed' };
    }
    throw err;
  }

  const deadline = Date.now() + WHOAMI_TIMEOUT_MS;
  for (;;) {
    const snap = await pollJob(jobId);
    if (snap.status === 'exited') {
      if (snap.exitCode !== 0) {
        return { status: 'not_installed' };
      }
      const parsed = parseLastJsonLine(snap.stdout);
      if (parsed && parsed.loggedIn === false) {
        return { status: 'logged_out' };
      }
      if (parsed && typeof parsed.email === 'string') {
        return {
          status: 'logged_in',
          profile: parsed as unknown as AuthProfile,
        };
      }

      return { status: 'logged_out' };
    }
    if (Date.now() > deadline) {
      return { status: 'logged_out' };
    }
    await wait(POLL_MS);
  }
}

async function fetchQuota(): Promise<QuotaState> {
  let jobId: string;
  try {
    jobId = await startExec('heal', ['quota', '--json']);
  } catch {
    return { status: 'unavailable' };
  }

  const deadline = Date.now() + QUOTA_TIMEOUT_MS;
  for (;;) {
    const snap = await pollJob(jobId);
    if (snap.status === 'exited') {
      if (snap.exitCode !== 0) {
        return { status: 'unavailable' };
      }
      const parsed = parseLastJsonLine(snap.stdout);
      if (
        parsed &&
        typeof parsed.tokenLimit === 'number' &&
        typeof parsed.tokenCurrentUsage === 'number' &&
        typeof parsed.hasReachedLimit === 'boolean'
      ) {
        return {
          status: 'ok',
          quota: {
            tokenLimit: parsed.tokenLimit,
            tokenCurrentUsage: parsed.tokenCurrentUsage,
            hasReachedLimit: parsed.hasReachedLimit,
          },
        };
      }

      // loggedIn:false, orgKey:true, fetchError:true — all treated as
      // "no quota to display".
      return { status: 'unavailable' };
    }
    if (Date.now() > deadline) {
      return { status: 'unavailable' };
    }
    await wait(POLL_MS);
  }
}

async function startSignIn(): Promise<void> {
  const jobId = await startExec('heal', [
    'login',
    '--json',
    '--return-to',
    window.location.href,
  ]);

  const deadline = Date.now() + AUTH_URL_TIMEOUT_MS;
  for (;;) {
    const snap = await pollJob(jobId);
    for (const line of snap.stdout) {
      const t = line.trim();
      if (!t.startsWith('{')) {
        continue;
      }
      try {
        const obj = JSON.parse(t) as { event?: string; url?: string };
        if (obj.event === 'auth_url' && typeof obj.url === 'string') {
          window.location.href = obj.url;

          return;
        }
      } catch {
        /* ignore */
      }
    }
    if (snap.status === 'exited') {
      throw new Error('heal login exited before emitting auth_url');
    }
    if (Date.now() > deadline) {
      throw new Error('Timed out waiting for auth URL');
    }
    await wait(POLL_MS);
  }
}

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [state, setState] = useState<AuthState>({ status: 'loading' });
  const [quotaState, setQuotaState] = useState<QuotaState>({
    status: 'loading',
  });

  const refreshQuota = async () => {
    try {
      setQuotaState(await fetchQuota());
    } catch {
      setQuotaState({ status: 'unavailable' });
    }
  };

  const refresh = async () => {
    try {
      const next = await fetchWhoami();
      setState(next);
      // Only fetch quota when actually logged in. Other states keep
      // the quota at its current value (no point hitting the CLI for
      // a quota when there's no key to authenticate the call).
      if (next.status === 'logged_in') {
        void refreshQuota();
      } else {
        setQuotaState({ status: 'unavailable' });
      }
    } catch {
      setState({ status: 'logged_out' });
      setQuotaState({ status: 'unavailable' });
    }
  };

  useEffect(() => {
    void refresh();
  }, []);

  const signIn = () => {
    startSignIn().catch((err: Error) => {
      // eslint-disable-next-line no-console -- surfaced for users running the standalone viewer
      console.error('[heal] sign-in failed:', err.message);
    });
  };

  return (
    <Ctx.Provider value={{ state, signIn, refresh, quotaState, refreshQuota }}>
      {children}
    </Ctx.Provider>
  );
};
