import type {
  CodeEditorFile,
  CodeLineAnnotation,
} from '../features/views/code-editor/code-editor.types';
import type { Statement, VerdictType } from '../types/test';

import { flattenStatements } from './flatten-statements';

/** The statement the active verdict points to, used to mark its line. */
export type VerdictMarker = {
  statementId: number;
  type: VerdictType;
};

type LocatedStatement = Statement & {
  file: string;
  line: number;
};

const isLocated = (statement: Statement): statement is LocatedStatement =>
  statement.file !== null && statement.line !== null;

const groupByFile = (
  statements: LocatedStatement[],
): Map<string, LocatedStatement[]> => {
  const byFile = new Map<string, LocatedStatement[]>();

  for (const statement of statements) {
    const existing = byFile.get(statement.file) ?? [];
    existing.push(statement);
    byFile.set(statement.file, existing);
  }

  return byFile;
};

const buildAnnotations = (
  statements: LocatedStatement[],
  verdict: VerdictMarker | null,
): CodeLineAnnotation[] => {
  const byLine = new Map<number, CodeLineAnnotation>();

  for (const statement of statements) {
    const isVerdict = verdict?.statementId === statement.id;
    byLine.set(statement.line, {
      line: statement.line,
      status: statement.status,
      verdictType: isVerdict ? verdict?.type : undefined,
    });
  }

  return [...byLine.values()];
};

/**
 * Builds editor files from a test's statements: one file per distinct
 * `statement.file`, plus per-line verdict annotations. Source content comes
 * from `sourceByPath` (keyed by the same project-relative `statement.file`
 * path); when it's missing — capture disabled or the file was truncated — the
 * file is shown empty rather than with placeholder content.
 */
export const buildCodeFiles = (
  statements: Statement[],
  verdict: VerdictMarker | null = null,
  sourceByPath?: Map<string, string>,
): CodeEditorFile[] => {
  const located = flattenStatements(statements).filter(isLocated);
  const byFile = groupByFile(located);

  return [...byFile.entries()].map(([path, fileStatements]) => ({
    path,
    content: sourceByPath?.get(path) ?? '',
    annotations: buildAnnotations(fileStatements, verdict),
  }));
};
