import { cn } from '@heal/front-core/lib/utils';
import {
  CommandItem,
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
  VerdictResultIndicator,
} from '@heal/front-core/ui';
import { TagIcon, UsersThreeIcon } from '@phosphor-icons/react';

import type { ExecutionItem } from './types';

const FilterTag = ({
  tag,
}: {
  tag: NonNullable<ExecutionItem['filterTags']>[number];
}) => (
  <TooltipProvider delayDuration={300}>
    <Tooltip>
      <TooltipTrigger asChild>
        <span className="flex items-center gap-1">
          {tag.kind === 'team' ? (
            <UsersThreeIcon
              size={11}
              className="shrink-0 text-brand-solid"
              aria-hidden
            />
          ) : (
            <TagIcon
              size={11}
              className="shrink-0 text-muted-foreground"
              aria-hidden
            />
          )}
          <span
            className={cn(
              'max-w-[100px] truncate text-[11px] font-medium',
              tag.kind === 'team'
                ? 'text-brand-solid'
                : 'text-muted-foreground',
            )}
          >
            {tag.label}
          </span>
        </span>
      </TooltipTrigger>
      <TooltipContent side="left" className="text-xs">
        {tag.label}
      </TooltipContent>
    </Tooltip>
  </TooltipProvider>
);

const ExecutionStatusRow = ({ item }: { item: ExecutionItem }) => {
  if (item.status === 'running') {
    return (
      <div className="flex items-center gap-1.5">
        <span className="h-2 w-2 shrink-0 animate-pulse rounded-full bg-brand-solid" />
        <span className="text-xs text-brand-solid">Running</span>
      </div>
    );
  }
  if (
    item.status === 'pending' &&
    !item.passCount &&
    !item.failCount &&
    !item.skipCount &&
    !item.runningCount
  ) {
    return <span className="text-xs text-muted-foreground">Pending</span>;
  }

  return (
    <div className="flex items-center gap-2.5">
      <span className="flex items-center gap-1">
        <VerdictResultIndicator
          status="passed"
          variant="iconOnly"
          size="sm"
          showTooltip={false}
        />
        <span className="text-xs tabular-nums text-success-solid">
          {item.passCount ?? 0}
        </span>
      </span>
      <span
        className={cn(
          'flex items-center gap-1',
          item.failCount === 0 ? 'opacity-40' : '',
        )}
      >
        <VerdictResultIndicator
          status="failed"
          variant="iconOnly"
          size="sm"
          showTooltip={false}
        />
        <span className="text-xs tabular-nums text-danger-solid">
          {item.failCount ?? 0}
        </span>
      </span>
      <span className="flex items-center gap-1">
        <VerdictResultIndicator
          status="skipped"
          variant="iconOnly"
          size="sm"
          showTooltip={false}
        />
        <span className="text-xs tabular-nums text-muted-foreground">
          {item.skipCount ?? 0}
        </span>
      </span>
      <span className="flex items-center gap-1">
        <VerdictResultIndicator
          status="pending"
          variant="iconOnly"
          size="sm"
          showTooltip={false}
        />
        <span className="text-xs tabular-nums text-muted-foreground">
          {item.pendingCount ?? 0}
        </span>
      </span>
    </div>
  );
};

interface ExecutionDropdownItemProps {
  item: ExecutionItem;
  isSelected: boolean;
  onSelect: () => void;
  index: number;
}

export const ExecutionDropdownItem = ({
  item,
  isSelected,
  onSelect,
  index,
}: ExecutionDropdownItemProps) => {
  const hasTags = item.filterTags && item.filterTags.length > 0;

  return (
    <CommandItem
      key={item.key}
      onSelect={onSelect}
      className={cn(
        'flex cursor-pointer flex-col items-stretch gap-0.5 rounded-none border-l-2 py-2 pl-3',
        isSelected
          ? 'border-brand-solid bg-brand-subtle'
          : 'border-transparent',
      )}
    >
      <div className="flex min-w-0 items-center gap-2">
        <span
          className={cn(
            'text-body font-medium',
            isSelected ? 'text-brand-solid' : 'text-foreground',
          )}
        >
          <span className="hidden">{index}</span>
          {item.label}
        </span>
        <span className="shrink-0 text-xs text-muted-foreground">
          {item.timeAgo}
        </span>
      </div>
      {item.triggeredBy && (
        <div className="flex min-w-0 items-center gap-1 mb-2">
          <span className="text-xs text-muted-foreground">triggered by:</span>
          <span className="truncate text-xs text-muted-foreground">
            {item.triggeredBy.type === 'ci'
              ? 'CI'
              : (item.triggeredBy.userEmail ?? 'User')}
          </span>
        </div>
      )}
      <div className="flex items-center justify-between gap-3">
        <ExecutionStatusRow item={item} />
        {hasTags ? (
          item.filterTags!.length === 1 ? (
            <FilterTag tag={item.filterTags![0]} />
          ) : (
            <TooltipProvider delayDuration={300}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className="flex items-center gap-1">
                    <TagIcon
                      size={11}
                      className="shrink-0 text-muted-foreground"
                      aria-hidden
                    />
                    <span className="text-[11px] font-medium text-muted-foreground">
                      {item.filterTags!.length}
                    </span>
                  </span>
                </TooltipTrigger>
                <TooltipContent side="left" className="text-xs">
                  <ul className="flex flex-row flex-wrap gap-0.5 max-w-[300px] gap-x-1">
                    {item.filterTags!.map((tag) => (
                      <li key={tag.label}>{tag.label}</li>
                    ))}
                  </ul>
                </TooltipContent>
              </Tooltip>
            </TooltipProvider>
          )
        ) : item.hasFilter ? (
          <span className="flex items-center gap-1">
            <TagIcon
              size={11}
              className="shrink-0 text-muted-foreground"
              aria-hidden
            />
            <span className="text-[11px] font-medium text-muted-foreground">
              filtered
            </span>
          </span>
        ) : null}
      </div>
    </CommandItem>
  );
};
