import { useVideoController } from '@heal/front-core/ui';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { useDataProvider } from '../data-provider/data-provider.hooks';

import { VideoProviderContext } from './video-provider.context';
import { VideoProviderProps } from './video-provider.types';

export const VideoProvider = ({ children }: VideoProviderProps) => {
  const { currentTest, flatStatements } = useDataProvider();
  const controller = useVideoController();

  const [activeVideoId, setActiveVideoId] = useState<string | undefined>(
    undefined,
  );

  // Default to — and reset to — the first video whenever the test changes.
  useEffect(() => {
    setActiveVideoId(currentTest?.videos[0]?.id);
  }, [currentTest]);

  // When `seekToStatement` switches videos, the seek can't run synchronously:
  // the `<video>` src is about to change, and setting `currentTime` before the
  // new clip reports metadata is discarded. We stash the target and flush it
  // once the active clip is loaded.
  const pendingSeekMsRef = useRef<number | null>(null);

  useEffect(() => {
    const target = pendingSeekMsRef.current;
    if (target == null) {
      return;
    }
    const video = controller.videoRef.current;
    if (!video) {
      return;
    }

    const applySeek = () => {
      controller.actions.seek(target);
      pendingSeekMsRef.current = null;
    };

    if (video.readyState >= 1 /* HAVE_METADATA */) {
      applySeek();

      return;
    }

    video.addEventListener('loadedmetadata', applySeek, { once: true });

    return () => video.removeEventListener('loadedmetadata', applySeek);
  }, [activeVideoId, controller.videoRef, controller.actions]);

  const seekToStatement = useCallback(
    (statementId: number) => {
      const statement = flatStatements.find((s) => s.id === statementId);
      if (!statement) {
        return;
      }

      const timeMs = statement.videoTimeMs ?? statement.timestampMs;

      if (statement.videoId && statement.videoId !== activeVideoId) {
        pendingSeekMsRef.current = timeMs;
        setActiveVideoId(statement.videoId);

        return;
      }

      controller.actions.seek(timeMs);
    },
    [flatStatements, activeVideoId, controller.actions],
  );

  const value = useMemo(
    () => ({ controller, seekToStatement, activeVideoId, setActiveVideoId }),
    [controller, seekToStatement, activeVideoId],
  );

  return (
    <VideoProviderContext.Provider value={value}>
      {children}
    </VideoProviderContext.Provider>
  );
};
