import { type ReactNode, useState } from 'react';

import { cn } from '../../../../lib/utils';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '../../../components/tabs/tabs';

export interface ContainerView {
  /** Unique identifier for the view */
  id: string;
  /** Label displayed in the tab trigger */
  label: ReactNode;
  /** Content rendered when the view is active */
  content: ReactNode;
  /** Optional icon rendered before the label */
  icon?: ReactNode;
  /** Whether the tab is disabled */
  disabled?: boolean;
  /**
   * Optional actions rendered in the right-hand slot of the tab bar while this
   * view is active. Swaps with the active tab, so each view can surface its
   * own controls (e.g. collapse-all / expand-all).
   */
  actions?: ReactNode;
}

export interface TraceViewerContainerClassNames {
  /** Root wrapper / Tabs root */
  root?: string;
  /** Tabs list bar */
  tabsList?: string;
  /** Individual tab trigger */
  tabsTrigger?: string;
  /** Each tab content panel */
  tabsContent?: string;
}

export interface TraceViewerContainerProps {
  /** Single-view content. Ignored when `views` is provided. */
  children?: ReactNode;
  /** Array of tab views. When provided, tabs render instead of children. */
  views?: ContainerView[];
  /** Controlled active tab id */
  activeView?: string;
  /** Callback when the active tab changes */
  onActiveViewChange?: (id: string) => void;
  /** Uncontrolled default active tab id. Defaults to first view. */
  defaultActiveView?: string;
  /** When true, content area scrolls internally. Default: false */
  scrollable?: boolean;
  /** Override classNames for internal elements */
  classNames?: TraceViewerContainerClassNames;
}

export const TraceViewerContainer = ({
  children,
  views,
  activeView,
  onActiveViewChange,
  defaultActiveView,
  scrollable = false,
  classNames,
}: TraceViewerContainerProps) => {
  const hasViews = views && views.length > 0;
  // Track the active view so the tab bar can render its `actions`. Mirrors the
  // controlled `activeView` when provided, falling back to local state so the
  // slot still follows the active tab in uncontrolled usage.
  const [internalActive, setInternalActive] = useState(
    activeView ?? defaultActiveView ?? views?.[0]?.id,
  );
  const currentActive = activeView ?? internalActive;
  const handleValueChange = (id: string) => {
    setInternalActive(id);
    onActiveViewChange?.(id);
  };
  const overflowClass = scrollable ? 'overflow-auto' : 'overflow-hidden';
  const rootClass = cn(
    'flex h-full w-full flex-col overflow-hidden bg-background',
    classNames?.root,
  );

  // Single content: children or single view — no tabs needed
  if (!hasViews) {
    const content = hasViews ? views[0].content : children;
    const title = hasViews ? views[0].label : null;

    return (
      <div className={rootClass}>
        {title && <div className="px-3 py-2 text-sm font-medium">{title}</div>}
        <div className={cn('flex-1', overflowClass)}>{content}</div>
      </div>
    );
  }

  const defaultValue = defaultActiveView ?? views[0].id;
  const activeActions = views.find(
    (view) => view.id === currentActive,
  )?.actions;

  return (
    <Tabs
      value={activeView}
      onValueChange={handleValueChange}
      defaultValue={defaultValue}
      className={cn(
        'flex h-full w-full flex-col overflow-hidden bg-surface',
        classNames?.root,
      )}
    >
      <div className="flex w-full shrink-0 items-center justify-between border-b bg-muted/50">
        <TabsList
          className={cn(
            'justify-start rounded-none border-0 bg-transparent gap-1 p-1',
            classNames?.tabsList,
          )}
        >
          {views.map((view) => (
            <TabsTrigger
              key={view.id}
              value={view.id}
              disabled={view.disabled}
              className={cn('gap-1.5', classNames?.tabsTrigger)}
            >
              {view.icon}
              {view.label}
            </TabsTrigger>
          ))}
        </TabsList>

        {activeActions && (
          <div className="flex shrink-0 items-center gap-0.5 px-1">
            {activeActions}
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {views.map((view) => (
          <TabsContent
            key={view.id}
            value={view.id}
            className={cn('m-0 h-full', overflowClass, classNames?.tabsContent)}
          >
            {view.content}
          </TabsContent>
        ))}
      </div>
    </Tabs>
  );
};
