import { useMemo } from 'react';

import { useCodeNavigation } from '../../../../context/code-navigation-provider/code-navigation-provider.hooks';
import {
  useDataProvider,
  useVerdictStatement,
} from '../../../../context/data-provider/data-provider.hooks';
import {
  buildCodeFiles,
  type VerdictMarker,
} from '../../../../utils/build-code-files';
import { useSourceContent } from '../../../mode/_hooks/use-source-content';
import { CodeEditorView } from '../../code-editor/code-editor.view';

/**
 * "Code" tab content: the Monaco editor with its own file tabs, rendered
 * inside the test-content tab bar alongside the code-graph and intent views.
 * Only the local mode mounts this tab, since it depends on local source files.
 */
export const CodeTab = () => {
  const { currentTest } = useDataProvider();
  const verdictHit = useVerdictStatement();
  const { target } = useCodeNavigation();
  const sourceByPath = useSourceContent();

  const files = useMemo(() => {
    const verdict: VerdictMarker | null = verdictHit
      ? {
          statementId: verdictHit.statement.id,
          type: verdictHit.verdict.payload.type,
        }
      : null;

    return buildCodeFiles(currentTest?.statements ?? [], verdict, sourceByPath);
  }, [currentTest, verdictHit, sourceByPath]);

  return (
    <CodeEditorView
      files={files}
      revealTarget={target ?? undefined}
      ariaLabel="Code viewer"
    />
  );
};
