import {
  Button,
  TraceViewerContainer,
  VerdictResultIndicator,
} from '@heal/front-core/ui';
import {
  ArrowsInLineVerticalIcon,
  ArrowsOutLineVerticalIcon,
} from '@phosphor-icons/react';
import {
  useEffect,
  useState,
  type KeyboardEvent,
  type MouseEvent,
} from 'react';

import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';
import { useCodeNavigation } from '../../../context/code-navigation-provider/code-navigation-provider.hooks';
import {
  useDataProvider,
  useVerdictStatement,
} from '../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../context/statement-provider/statement-provider.hooks';
import { useTriageVerdictForm } from '../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import { useViewProvider } from '../../../context/view-provider/view-provider.hooks';
import type { FinalVerdict, TriagedVerdict } from '../../../types/test';
import { LOCAL_MODE_ID } from '../../mode/local.mode';

import { ActionView } from './_components/action-view';
import { CodeTab } from './_components/code-tab';
import { CodeView } from './_components/code-view';

export const TEST_CONTENT_VIEW_ID = 'test-content';

const TEST_CONTENT_TAB_STORAGE_KEY = 'heal:trace-viewer:test-content-tab';
const VALID_TEST_CONTENT_TABS = new Set(['steps', 'actions', 'code']);

const readStoredTab = (defaultTab: 'steps' | 'actions'): string => {
  if (typeof window === 'undefined') {
    return defaultTab;
  }
  const raw = window.localStorage.getItem(TEST_CONTENT_TAB_STORAGE_KEY);
  if (raw && VALID_TEST_CONTENT_TABS.has(raw)) {
    return raw;
  }

  return defaultTab;
};

export const TestContentView = () => {
  const { currentTest } = useDataProvider();
  const { features, mode } = useViewProvider();
  const { target } = useCodeNavigation();
  const configuredDefaultTab = features.defaultTestContentTab;
  // The Code tab relies on local source files, so it's only offered in the
  // local mode — other modes keep just the code-graph and intent views.
  const showCodeTab = mode === LOCAL_MODE_ID;
  const [activeTab, setActiveTab] = useState<string>(() =>
    readStoredTab(configuredDefaultTab),
  );
  // Collapse/expand-all broadcast for the code graph: bumping the signal snaps
  // every row to `collapseValue`. Lives here so the controls can sit in the
  // container's tab-bar actions slot while the rows render inside CodeView.
  const [collapseSignal, setCollapseSignal] = useState<number | undefined>();
  const [collapseValue, setCollapseValue] = useState(false);

  const broadcastCollapse = (collapsed: boolean) => {
    setCollapseValue(collapsed);
    setCollapseSignal((signal) => (signal ?? 0) + 1);
  };

  const handleActiveTabChange = (id: string) => {
    setActiveTab(id);
    window.localStorage.setItem(TEST_CONTENT_TAB_STORAGE_KEY, id);
  };

  // "Explore code" sets a navigation target — surface the Code tab so the
  // editor reveals the requested file/line.
  useEffect(() => {
    if (showCodeTab && target) {
      setActiveTab('code');
      window.localStorage.setItem(TEST_CONTENT_TAB_STORAGE_KEY, 'code');
    }
  }, [showCodeTab, target]);

  const verdict = currentTest?.finalVerdict ?? currentTest?.triagedVerdict;

  const views = [
    {
      id: 'steps',
      label: 'Code graph',
      content: (
        <CodeView
          collapseSignal={collapseSignal}
          collapseValue={collapseValue}
        />
      ),
      actions: (
        <>
          <Button
            variant="ghost"
            size="sm"
            className="gap-1.5 px-2 text-muted-foreground hover:text-foreground"
            onClick={() => broadcastCollapse(false)}
          >
            <ArrowsOutLineVerticalIcon className="size-4" />
            Expand all
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="gap-1.5 px-2 text-muted-foreground hover:text-foreground"
            onClick={() => broadcastCollapse(true)}
          >
            <ArrowsInLineVerticalIcon className="size-4" />
            Collapse all
          </Button>
        </>
      ),
    },
    {
      id: 'actions',
      label: 'Intent',
      content: <ActionView />,
    },
    ...(showCodeTab
      ? [
          {
            id: 'code',
            label: 'Code',
            content: <CodeTab />,
          },
        ]
      : []),
  ];

  // A persisted 'code' tab is meaningless outside the local mode — fall back
  // to the configured default so the container always has a matching view.
  const activeView =
    showCodeTab || activeTab !== 'code' ? activeTab : configuredDefaultTab;

  return (
    <div className="flex h-full w-full flex-col overflow-hidden">
      {verdict && <VerdictBanner verdict={verdict} />}
      <div className="min-h-0 flex-1">
        <TraceViewerContainer
          scrollable
          activeView={activeView}
          onActiveViewChange={handleActiveTabChange}
          views={views}
        />
      </div>
    </div>
  );
};

const VERDICT_BANNER_CLASS =
  'flex shrink-0 items-center gap-1.5 border-b border-border bg-muted/40 px-3 py-1.5 text-xs text-foreground';

const VerdictBanner = ({
  verdict,
}: {
  verdict: TriagedVerdict | FinalVerdict;
}) => {
  const { canWriteTriagedVerdict } = useCapabilities();
  const { open } = useTriageVerdictForm();
  const { selectActiveStatement } = useStatementProvider();
  const verdictHit = useVerdictStatement();

  const handleNavigateToStep = (event: MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    if (verdictHit) {
      selectActiveStatement(verdictHit.statement.id);
    }
  };

  const content = (
    <div className="flex items-center gap-1.5 text-xs font-semibold tracking-wide uppercase text-foreground">
      <VerdictResultIndicator
        verdictType={verdict.payload.type}
        variant="compact"
        size="sm"
        showTooltip={false}
        sideElement={
          <span
            onClick={handleNavigateToStep}
            className="cursor-pointer font-normal text-muted-foreground normal-case hover:text-foreground hover:underline"
          >
            at step {verdict.failingStatementIndex + 1}
          </span>
        }
      />
    </div>
  );

  if (!canWriteTriagedVerdict) {
    return <div className={VERDICT_BANNER_CLASS}>{content}</div>;
  }

  const handleOpenOperator = () => {
    open();
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={handleOpenOperator}
      onKeyDown={getOperatorKeyDownHandler(handleOpenOperator)}
      className={`${VERDICT_BANNER_CLASS} w-full cursor-pointer text-left transition-colors hover:bg-muted/60`}
    >
      {content}
    </div>
  );
};

const getOperatorKeyDownHandler =
  (onActivate: () => void) => (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== 'Enter' && event.key !== ' ') {
      return;
    }
    event.preventDefault();
    onActivate();
  };
