import { createContext } from 'react';

export type CodeNavigationTarget = {
  path: string;
  /** 1-based line to reveal. */
  line: number;
  /** Bumped on each request so re-selecting the same target re-fires. */
  nonce: number;
};

export type CodeNavigationContextValue = {
  target: CodeNavigationTarget | null;
  goToCode: (path: string, line: number) => void;
};

export const CodeNavigationContext =
  createContext<CodeNavigationContextValue | null>(null);
