import type {
  editor,
  IDisposable,
  Position,
} from 'monaco-editor/esm/vs/editor/editor.api.js';

import type { CodeEditorFile } from '../code-editor.types';

import {
  getImportBindings,
  getQuotedStringAt,
  resolveImportTarget,
} from './resolve-import-target';

// Models are created at `inmemory:///<path>`; recover the original file path.
const getModelPath = (model: editor.ITextModel): string =>
  model.uri.path.replace(/^\/+/, '');

/**
 * Resolves a "go to file" target at `position` in the editor's current model:
 *  1. the quoted import path directly under the cursor, or
 *  2. an identifier under the cursor that was imported from another file
 *     (so right-clicking a function/symbol jumps to where it comes from).
 * Returns the matching file `path` within `files`, or `null`.
 */
export const getImportTargetAtPosition = (
  codeEditor: editor.IStandaloneCodeEditor,
  position: Position,
  files: CodeEditorFile[],
): string | null => {
  const model = codeEditor.getModel();
  if (!model) {
    return null;
  }

  const fromPath = getModelPath(model);

  const quotedSpecifier = getQuotedStringAt(
    model.getLineContent(position.lineNumber),
    position.column,
  );
  if (quotedSpecifier) {
    return resolveImportTarget(fromPath, quotedSpecifier, files);
  }

  const word = model.getWordAtPosition(position);
  if (!word) {
    return null;
  }

  const importedFrom = getImportBindings(model.getValue()).get(word.word);
  if (!importedFrom) {
    return null;
  }

  return resolveImportTarget(fromPath, importedFrom, files);
};

type RegisterGoToFileOptions = {
  getFiles: () => CodeEditorFile[];
  onNavigate: (path: string) => void;
};

/**
 * Wires Ctrl/Cmd+click on an import specifier to navigate to that file.
 * Returns a disposable for the mouse listener.
 */
export const registerGoToFile = (
  codeEditor: editor.IStandaloneCodeEditor,
  { getFiles, onNavigate }: RegisterGoToFileOptions,
): IDisposable =>
  codeEditor.onMouseDown((event) => {
    const withModifier = event.event.ctrlKey || event.event.metaKey;
    if (!withModifier) {
      return;
    }

    const position = event.target.position;
    if (!position) {
      return;
    }

    const target = getImportTargetAtPosition(codeEditor, position, getFiles());
    if (target) {
      onNavigate(target);
    }
  });
