import { Button, Spinner } from '@heal/front-core/ui';
import { ArrowClockwiseIcon, SparkleIcon } from '@phosphor-icons/react';

import { useAnalyzeSlot } from '../../context/analyze-slot-provider/analyze-slot-provider.hooks';

/**
 * Renders the "Run analyze" affordance inside the verdict-form pane.
 * Opt-in: when the host hasn't wired an `analyzeSlot` prop into
 * `<Tracer>`, this renders nothing.
 *
 * Visual states:
 *  - `none`      → "Run analyze" button (primary content)
 *  - `running`   → spinner + "Analyzing…" (primary content)
 *  - `failed`    → "Re-run analyze" button (secondary; the host also
 *                  promotes a HEAL_SYSTEM_ISSUE verdict that renders
 *                  above this slot, so we render only the retry control)
 *  - `unknown`,
 *    `completed` → render nothing (the verdict body takes over).
 */
export const AnalyzeSlot = () => {
  const slot = useAnalyzeSlot();
  if (!slot) {
    return null;
  }
  const {
    state,
    onTrigger,
    isTriggering,
    onTriggerAll,
    isTriggeringAll,
    failingTestCount,
  } = slot;
  const showAnalyzeAll =
    onTriggerAll !== undefined && (failingTestCount ?? 0) > 0;

  switch (state.kind) {
    case 'unknown':
    case 'completed':
      return null;

    case 'none':
      return (
        <div className="flex flex-col items-center justify-center gap-3 py-6 text-center">
          <p className="max-w-[28ch] text-xs text-muted-foreground">
            Ask Heal to analyze this failure and surface a likely root cause.
          </p>
          <Button
            variant="primary"
            size="sm"
            onClick={onTrigger}
            disabled={isTriggering || isTriggeringAll}
          >
            <SparkleIcon className="size-4" weight="fill" aria-hidden />
            Run analyze
          </Button>
          {showAnalyzeAll && (
            <Button
              variant="secondary"
              size="sm"
              onClick={onTriggerAll}
              disabled={isTriggering || isTriggeringAll}
            >
              <SparkleIcon className="size-4" aria-hidden />
              {isTriggeringAll
                ? 'Dispatching…'
                : `Analyze all ${failingTestCount} failing tests`}
            </Button>
          )}
        </div>
      );

    case 'running':
      return (
        <div className="flex flex-col items-center justify-center gap-3 py-6 text-center">
          <Spinner />
          <p className="text-xs text-muted-foreground">Analyzing…</p>
        </div>
      );

    case 'failed':
      return (
        <div className="flex justify-center py-4">
          <Button
            variant="secondary"
            size="sm"
            onClick={onTrigger}
            disabled={isTriggering}
          >
            <ArrowClockwiseIcon className="size-4" aria-hidden />
            Re-run analyze
          </Button>
        </div>
      );
  }
};
