/**
 * A recorded video, reduced to the fields needed to link statements to it.
 * Multi-context tests produce one recording per browser page.
 */
export interface ResolverVideo {
  /** Stable id returned for matched statements (the run-viewer `Video.id`). */
  id: string;
  /** The page this recording belongs to; joins to a statement's `pageId`. */
  pageId?: string;
  /** Wall-clock ms at which the recording started. */
  videoStartWallMs?: number;
}

/** A statement, reduced to the fields needed to place it inside a video. */
export interface ResolverStatement {
  /** The page this statement acted on, if any. */
  pageId?: string;
  /** Server-precomputed offset into the page's video, in seconds. */
  videoTime?: number;
  /** Statement start, in ms from the test start. */
  timestampMs: number;
}

export interface ResolvedStatementVideo {
  /** Id of the video to play, or undefined when there is none. */
  videoId: string | undefined;
  /** Offset to seek that video to, in ms, or undefined when unknown. */
  videoTimeMs: number | undefined;
}

/** The recording that started last — the default before any page is seen. */
const mostRecentlyStarted = (
  videos: ResolverVideo[],
): ResolverVideo | undefined =>
  videos.reduce<ResolverVideo | undefined>((latest, video) => {
    const startedLater =
      !latest ||
      (video.videoStartWallMs ?? 0) >= (latest.videoStartWallMs ?? 0);

    return startedLater ? video : latest;
  }, undefined);

/**
 * Where a statement sits inside its video, in ms. Uses the server's precomputed
 * `videoTime` when available, otherwise derives it from when the recording
 * started relative to the test start.
 */
const videoTimeMsFor = ({
  statement,
  video,
  testStartedAtMs,
}: {
  statement: ResolverStatement;
  video: ResolverVideo | undefined;
  testStartedAtMs: number | undefined;
}): number | undefined => {
  if (statement.videoTime != null) {
    return statement.videoTime * 1000;
  }

  if (!video || testStartedAtMs == null) {
    return undefined;
  }

  const offsetMs =
    testStartedAtMs + statement.timestampMs - (video.videoStartWallMs ?? 0);

  return Math.max(0, offsetMs);
};

/**
 * Builds a resolver that links each statement to the video it plays against.
 *
 * Call the returned function once per statement, **in execution order** — it
 * remembers the last page it saw. A statement that acted on a page carries a
 * `pageId`; one that didn't keeps playing whatever page was last active (and,
 * before any page is seen, the most-recently-started recording).
 */
export const createStatementVideoResolver = ({
  videos,
  testStartedAtMs,
}: {
  videos: ResolverVideo[];
  testStartedAtMs: number | undefined;
}): ((statement: ResolverStatement) => ResolvedStatementVideo) => {
  const fallbackVideo = mostRecentlyStarted(videos);
  let lastSeenPageId: string | undefined;

  return (statement) => {
    const pageId = statement.pageId ?? lastSeenPageId ?? fallbackVideo?.pageId;
    if (statement.pageId) {
      lastSeenPageId = statement.pageId;
    }

    const video = videos.find((v) => v.pageId === pageId) ?? fallbackVideo;

    return {
      videoId: video?.id,
      videoTimeMs: videoTimeMsFor({ statement, video, testStartedAtMs }),
    };
  };
};
