import { Statement } from '../types/test';

export const flattenStatements = (statements: Statement[]): Statement[] => {
  const result: Statement[] = [];
  for (const statement of statements) {
    result.push(statement);
    if (statement.children.length > 0) {
      result.push(...flattenStatements(statement.children));
    }
  }

  return result;
};

export interface IndentedStatement {
  statement: Statement;
  indent: number;
}

export const flattenStatementsWithIndent = (
  statements: Statement[],
  indent = 0,
): IndentedStatement[] => {
  return statements.flatMap((statement) => [
    { statement, indent },
    ...flattenStatementsWithIndent(statement.children, indent + 1),
  ]);
};
