import type { VerdictResultStatus, VerdictType } from '@heal/front-core/ui';
import type { editor } from 'monaco-editor/esm/vs/editor/editor.api.js';
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type RefObject,
} from 'react';

import { READONLY_OPTIONS } from '../_utils/editor-options';
import {
  getImportTargetAtPosition,
  registerGoToFile,
} from '../_utils/register-go-to-file';
import { resolveAnnotationStyle } from '../_utils/resolve-annotation-style';
import { resolveLanguage } from '../_utils/resolve-language';
import type { CodeEditorFile, CodeRevealTarget } from '../code-editor.types';
import { bootstrapMonaco, type MonacoApi } from '../monaco-setup';

type UseCodeEditorParams = {
  files: CodeEditorFile[];
  activePath: string | undefined;
  theme: string;
  /** Switch to a file (e.g. when a "go to file" navigation resolves). */
  onNavigate: (path: string) => void;
  /** When set, reveal/center this line once the file's model is active. */
  revealTarget?: CodeRevealTarget;
};

/** A verdict indicator to render (via portal) into a Monaco glyph-margin node. */
export type AnnotationPortal = {
  key: string;
  node: HTMLElement;
  status?: VerdictResultStatus;
  verdictType?: VerdictType;
};

type UseCodeEditorResult = {
  /** Attach to the editor host element. */
  hostRef: RefObject<HTMLDivElement>;
  /** True once the Monaco editor instance has been created. */
  ready: boolean;
  /** Resolve the import specifier at a viewport point to a file path, or null. */
  resolveImportAtPoint: (clientX: number, clientY: number) => string | null;
  /** Currently selected text (empty string when there is no selection). */
  getSelectionText: () => string;
  /** Gutter verdict indicators to portal into their Monaco-managed nodes. */
  annotationPortals: AnnotationPortal[];
};

/**
 * Owns the imperative Monaco lifecycle for a read-only multi-file viewer:
 * a single editor instance, one model per file path, and per-file view-state
 * (scroll/cursor) that is saved and restored across tab switches. Returns the
 * ref to attach to the editor host element.
 */
export const useCodeEditor = ({
  files,
  activePath,
  theme,
  onNavigate,
  revealTarget,
}: UseCodeEditorParams): UseCodeEditorResult => {
  const hostRef = useRef<HTMLDivElement>(null);
  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null);
  const monacoRef = useRef<MonacoApi | null>(null);
  const modelsRef = useRef(new Map<string, editor.ITextModel>());
  const viewStatesRef = useRef(
    new Map<string, editor.ICodeEditorViewState | null>(),
  );
  const shownPathRef = useRef<string | null>(null);
  const revealedNonceRef = useRef<number | null>(null);
  const revealFrameRef = useRef<number | null>(null);
  const decorationsRef = useRef<editor.IEditorDecorationsCollection | null>(
    null,
  );
  const glyphWidgetsRef = useRef<editor.IGlyphMarginWidget[]>([]);
  // Read by the once-registered go-to-file handlers so they see the latest set.
  const filesRef = useRef(files);
  filesRef.current = files;

  const [ready, setReady] = useState(false);
  const [annotationPortals, setAnnotationPortals] = useState<
    AnnotationPortal[]
  >([]);

  // Create a single editor instance once Monaco is bootstrapped (dynamic import
  // keeps this off the SSR path); dispose it and every model on unmount.
  useEffect(() => {
    let cancelled = false;
    let goToFile: { dispose: () => void } | null = null;

    const create = (monaco: MonacoApi) => {
      if (cancelled || !hostRef.current) {
        return;
      }
      monacoRef.current = monaco;
      const codeEditor = monaco.editor.create(hostRef.current, {
        ...READONLY_OPTIONS,
        theme,
      });
      editorRef.current = codeEditor;
      goToFile = registerGoToFile(codeEditor, {
        getFiles: () => filesRef.current,
        onNavigate,
      });
      setReady(true);
    };

    const surface = (reason: unknown) => {
      // Surface failures instead of swallowing them (a silent catch was hiding
      // the cause of the blank editor). Re-throw on a microtask so it reaches
      // the console / error overlay without breaking the render.
      queueMicrotask(() => {
        throw reason instanceof Error ? reason : new Error(String(reason));
      });
    };

    bootstrapMonaco().then(create).catch(surface);

    return () => {
      cancelled = true;
      goToFile?.dispose();
      editorRef.current?.dispose();
      editorRef.current = null;
      monacoRef.current = null;
      modelsRef.current.forEach((model) => model.dispose());
      modelsRef.current.clear();
      viewStatesRef.current.clear();
      shownPathRef.current = null;
    };
  }, []);

  // Reflect prop changes onto the live editor: theme, plus the active file's
  // model with per-file view-state save/restore.
  useEffect(() => {
    const activeEditor = editorRef.current;
    const monaco = monacoRef.current;
    if (!ready || !activeEditor || !monaco || !activePath) {
      return;
    }

    monaco.editor.setTheme(theme);

    const file = files.find((candidate) => candidate.path === activePath);
    if (!file) {
      return;
    }

    const previousPath = shownPathRef.current;
    if (previousPath && previousPath !== activePath) {
      viewStatesRef.current.set(previousPath, activeEditor.saveViewState());
    }

    const model = getOrCreateModel(monaco, modelsRef.current, file);
    // Refresh stale content: the model is cached by path, so a model created
    // during an earlier (e.g. empty) render must pick up the latest content.
    if (model.getValue() !== file.content) {
      model.setValue(file.content);
    }
    if (activeEditor.getModel() !== model) {
      activeEditor.setModel(model);
    }

    const viewState = viewStatesRef.current.get(file.path);
    if (viewState) {
      activeEditor.restoreViewState(viewState);
    }
    shownPathRef.current = file.path;

    // A fresh reveal request for the now-active file wins over the restored
    // view state: center the line and place the cursor there.
    const shouldReveal =
      revealTarget !== undefined &&
      revealTarget.path === activePath &&
      revealTarget.nonce !== revealedNonceRef.current;
    if (shouldReveal) {
      activeEditor.revealLineInCenter(revealTarget.line);
      activeEditor.setPosition({ lineNumber: revealTarget.line, column: 1 });
      revealedNonceRef.current = revealTarget.nonce;
    }
  }, [ready, activePath, files, theme, revealTarget]);

  // Render the active file's verdict annotations: a whole-line tint + accent
  // (decorations) and a gutter indicator (glyph-margin widget hosting a React
  // portal target). Runs after the model swap above, so it targets the right
  // model. Rebuilt on every file/annotation change.
  useEffect(() => {
    const codeEditor = editorRef.current;
    const monaco = monacoRef.current;
    if (!ready || !codeEditor || !monaco) {
      return;
    }

    const annotations =
      files.find((file) => file.path === activePath)?.annotations ?? [];

    const toRange = (line: number) => ({
      startLineNumber: line,
      startColumn: 1,
      endLineNumber: line,
      endColumn: 1,
    });

    const collection =
      decorationsRef.current ?? codeEditor.createDecorationsCollection();
    decorationsRef.current = collection;
    collection.set(
      annotations.map((annotation) => {
        const style = resolveAnnotationStyle(annotation);

        return {
          range: toRange(annotation.line),
          options: {
            isWholeLine: true,
            className: style.lineClass,
            marginClassName: style.lineClass,
            linesDecorationsClassName: style.lineClass,
          },
        };
      }),
    );

    glyphWidgetsRef.current.forEach((widget) =>
      codeEditor.removeGlyphMarginWidget(widget),
    );

    const portals: AnnotationPortal[] = [];
    glyphWidgetsRef.current = annotations.map((annotation, index) => {
      const node = document.createElement('div');
      node.className = 'flex! pl-3 h-full w-full items-center justify-center';
      const key = `verdict-${annotation.line}-${index}`;
      const widget: editor.IGlyphMarginWidget = {
        getId: () => key,
        getDomNode: () => node,
        getPosition: () => ({
          lane: monaco.editor.GlyphMarginLane.Center,
          zIndex: 10,
          range: toRange(annotation.line),
        }),
      };
      codeEditor.addGlyphMarginWidget(widget);
      portals.push({
        key,
        node,
        status: annotation.status,
        verdictType: annotation.verdictType,
      });

      return widget;
    });

    setAnnotationPortals(portals);
  }, [ready, activePath, files]);

  const resolveImportAtPoint = useCallback(
    (clientX: number, clientY: number): string | null => {
      const codeEditor = editorRef.current;
      if (!codeEditor) {
        return null;
      }

      const position = codeEditor.getTargetAtClientPoint(
        clientX,
        clientY,
      )?.position;
      if (!position) {
        return null;
      }

      return getImportTargetAtPosition(codeEditor, position, filesRef.current);
    },
    [],
  );

  const getSelectionText = useCallback((): string => {
    const codeEditor = editorRef.current;
    const selection = codeEditor?.getSelection();
    const model = codeEditor?.getModel();
    if (!codeEditor || !selection || !model) {
      return '';
    }

    return model.getValueInRange(selection);
  }, []);

  return {
    hostRef,
    ready,
    resolveImportAtPoint,
    getSelectionText,
    annotationPortals,
  };
};

const getOrCreateModel = (
  monaco: MonacoApi,
  models: Map<string, editor.ITextModel>,
  file: CodeEditorFile,
): editor.ITextModel => {
  const cached = models.get(file.path);
  if (cached) {
    return cached;
  }

  const uri = monaco.Uri.parse(`inmemory:///${file.path}`);
  const model =
    monaco.editor.getModel(uri) ??
    monaco.editor.createModel(file.content, resolveLanguage(file), uri);
  models.set(file.path, model);

  return model;
};
