import { useCallback, useMemo, useState } from 'react';

import { DEFAULT_MODE_ID } from '../../features/mode/default.mode';
import { AttemptStatus } from '../../types/attempt';

import { ViewProviderContext } from './view-provider.context';
import {
  TestListFilters,
  TestListGroupBy,
  TestListVisibility,
  TracerFeatures,
  TracerMode,
  ViewProviderProps,
} from './view-provider.types';

const DEFAULT_FEATURES: TracerFeatures = {
  showGroupBy: true,
  defaultTestContentTab: 'steps',
};

const GROUP_BY_STORAGE_KEY = 'tracer.testList.groupBy';
const GROUP_BY_VALUES: TestListGroupBy[] = [
  'none',
  'project',
  'team',
  'team-and-feature',
];

const readStoredGroupBy = (): TestListGroupBy => {
  try {
    const raw = localStorage.getItem(GROUP_BY_STORAGE_KEY);
    if (raw && GROUP_BY_VALUES.includes(raw as TestListGroupBy)) {
      return raw as TestListGroupBy;
    }

    return 'none';
  } catch {
    return 'none';
  }
};

const writeStoredGroupBy = (value: TestListGroupBy): void => {
  try {
    localStorage.setItem(GROUP_BY_STORAGE_KEY, value);
  } catch {
    // ignore quota errors
  }
};

export const ViewProvider = ({
  children,
  features,
  mode,
}: ViewProviderProps) => {
  const [isTestListFolded, setIsTestListFolded] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<AttemptStatus[]>([]);
  const [groupBy, setGroupBy] = useState<TestListGroupBy>(readStoredGroupBy);
  // Lets the viewer override the host-provided mode (e.g. "Explore code"
  // switches to the code mode). Null means follow the `mode` prop.
  const [modeOverride, setModeOverride] = useState<TracerMode | null>(null);

  const setMode = useCallback((next: TracerMode) => {
    setModeOverride(next);
  }, []);

  const testListVisibility = useMemo<TestListVisibility>(
    () => ({
      isFolded: isTestListFolded,
      onFold: () => setIsTestListFolded(true),
      onUnfold: () => setIsTestListFolded(false),
    }),
    [isTestListFolded],
  );

  const handleSetSearchQuery = useCallback((query: string) => {
    setSearchQuery(query);
  }, []);

  const handleSetStatusFilter = useCallback((statuses: AttemptStatus[]) => {
    setStatusFilter(statuses);
  }, []);

  const handleSetGroupBy = useCallback((value: TestListGroupBy) => {
    setGroupBy(value);
    writeStoredGroupBy(value);
  }, []);

  const testListFilters = useMemo<TestListFilters>(
    () => ({
      searchQuery,
      setSearchQuery: handleSetSearchQuery,
      statusFilter,
      setStatusFilter: handleSetStatusFilter,
      groupBy,
      setGroupBy: handleSetGroupBy,
    }),
    [
      searchQuery,
      handleSetSearchQuery,
      statusFilter,
      handleSetStatusFilter,
      groupBy,
      handleSetGroupBy,
    ],
  );

  const resolvedFeatures = useMemo<TracerFeatures>(
    () => ({ ...DEFAULT_FEATURES, ...features }),
    [features],
  );

  return (
    <ViewProviderContext.Provider
      value={{
        testListVisibility,
        testListFilters,
        features: resolvedFeatures,
        mode: modeOverride ?? mode ?? DEFAULT_MODE_ID,
        setMode,
      }}
    >
      {children}
    </ViewProviderContext.Provider>
  );
};
