import { useEffect, useState } from 'react';

import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';

/**
 * Lazily resolves the current test's source files to a `path → content`
 * map. Runs only while mounted — the code view is the sole consumer, so
 * source is fetched the first time the user opens that view, not on every
 * trace load. Truncated entries are skipped (their URL 404s); per-file
 * fetch failures are dropped so one missing file never blanks the rest.
 * Returns an empty map when capture was off or no loader was injected, in
 * which case callers fall back to placeholder content.
 */
export const useSourceContent = (): Map<string, string> => {
  const { currentTest, loadSourceContent } = useDataProvider();
  const sources = currentTest?.sources;

  const [contentByPath, setContentByPath] = useState<Map<string, string>>(
    () => new Map(),
  );

  useEffect(() => {
    if (!loadSourceContent || !sources?.length) {
      setContentByPath(new Map());

      return;
    }

    let cancelled = false;
    const fetchable = sources.filter((source) => !source.truncated);

    Promise.allSettled(
      fetchable.map((source) =>
        loadSourceContent(source.url).then(
          (content) => [source.path, content] as const,
        ),
      ),
    ).then((results) => {
      if (cancelled) return;
      const next = new Map<string, string>();
      for (const result of results) {
        if (result.status === 'fulfilled') {
          next.set(result.value[0], result.value[1]);
        }
      }
      setContentByPath(next);
    });

    return () => {
      cancelled = true;
    };
  }, [sources, loadSourceContent]);

  return contentByPath;
};
