import { useEffect, useRef, type RefObject } from 'react';

import { cn } from '../../../../../lib/utils';
import { formatTime } from '../_utils/format-time';

const PREVIEW_WIDTH = 160;
const PREVIEW_HEIGHT = 90;

interface PreviewPosition {
  x: number;
  y: number;
}

interface TimelinePreviewTooltipProps {
  videoSrc?: string;
  hoverTimeMs: number | null;
  previewPos: PreviewPosition | null;
  barRef: RefObject<HTMLDivElement | null>;
}

const getPreviewLeft = (
  previewPos: PreviewPosition | null,
  barRef: RefObject<HTMLDivElement | null>,
): number => {
  if (!previewPos || !barRef.current) {
    return 0;
  }
  const barRect = barRef.current.getBoundingClientRect();
  const halfWidth = PREVIEW_WIDTH / 2;
  const minX = barRect.left + halfWidth;
  const maxX = barRect.right - halfWidth;

  return Math.max(minX, Math.min(maxX, previewPos.x));
};

export const TimelinePreviewTooltip = ({
  videoSrc,
  hoverTimeMs,
  previewPos,
  barRef,
}: TimelinePreviewTooltipProps) => {
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const video = previewVideoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) {
      return;
    }

    const handleSeeked = () => {
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        return;
      }
      ctx.drawImage(video, 0, 0, PREVIEW_WIDTH, PREVIEW_HEIGHT);
    };

    video.addEventListener('seeked', handleSeeked);

    return () => {
      video.removeEventListener('seeked', handleSeeked);
    };
  }, []);

  // Sync the hidden preview video's currentTime with the hover position.
  useEffect(() => {
    const video = previewVideoRef.current;
    if (!video || hoverTimeMs === null) {
      return;
    }
    video.currentTime = hoverTimeMs / 1000;
  }, [hoverTimeMs]);

  if (!videoSrc) {
    return null;
  }

  const isVisible = hoverTimeMs !== null && previewPos !== null;
  const left = isVisible ? getPreviewLeft(previewPos, barRef) : 0;
  const top = previewPos ? previewPos.y - 8 : 0;

  return (
    <>
      <video
        ref={previewVideoRef}
        src={videoSrc}
        muted
        preload="auto"
        className="hidden"
      />
      <div
        className={cn(
          'pointer-events-none fixed z-50 -translate-x-1/2 -translate-y-full transition-opacity duration-100',
          isVisible ? 'opacity-100' : 'opacity-0',
        )}
        style={{ left, top }}
      >
        <div className="overflow-hidden rounded-md border bg-surface shadow-lg">
          <canvas
            ref={canvasRef}
            width={PREVIEW_WIDTH}
            height={PREVIEW_HEIGHT}
            className="block"
          />
          <div className="px-2 py-1 text-center text-xs tabular-nums text-muted-foreground">
            {hoverTimeMs !== null ? formatTime(hoverTimeMs) : ''}
          </div>
        </div>
      </div>
    </>
  );
};
