import { cn } from '@heal/front-core/lib/utils';
import {
  BracketsCurly,
  FileCode,
  FileJs,
  FilePy,
  FileTs,
  type Icon,
} from '@phosphor-icons/react';

export type FileTabItem = {
  value: string;
  label: string;
  /** Resolved Monaco language id, used to pick the file-type icon. */
  language: string;
  /** Full path shown on hover. */
  title?: string;
};

type FileTabsProps = {
  items: FileTabItem[];
  /** Active tab value, or `undefined` when nothing is selected. */
  value: string | undefined;
  onValueChange: (value: string) => void;
};

type IconConfig = { Glyph: Icon; className: string };

const ICON_BY_LANGUAGE: Record<string, IconConfig> = {
  typescript: { Glyph: FileTs, className: 'text-[#3178c6]' },
  javascript: { Glyph: FileJs, className: 'text-[#e8d44d]' },
  python: { Glyph: FilePy, className: 'text-[#4b8bbe]' },
  json: { Glyph: BracketsCurly, className: 'text-[#cbcb41]' },
};

const FALLBACK_ICON: IconConfig = {
  Glyph: FileCode,
  className: 'text-muted-foreground',
};

export const FileTabs = ({ items, value, onValueChange }: FileTabsProps) => (
  <div
    role="tablist"
    aria-label="Open files"
    className={cn(
      'flex shrink-0 items-stretch overflow-x-auto border-b border-border bg-muted/30',
      '[scrollbar-width:none] [&::-webkit-scrollbar]:hidden',
    )}
  >
    {items.map((item) => {
      const isActive = item.value === value;
      const { Glyph, className } =
        ICON_BY_LANGUAGE[item.language] ?? FALLBACK_ICON;

      return (
        <button
          key={item.value}
          type="button"
          role="tab"
          aria-selected={isActive}
          title={item.title}
          onClick={() => onValueChange(item.value)}
          className={cn(
            'flex shrink-0 items-center gap-1.5 border-r border-border',
            'px-3 py-1.5 text-xs font-medium transition-colors',
            isActive
              ? 'bg-background text-foreground'
              : 'text-muted-foreground hover:bg-background/40 hover:text-foreground',
          )}
        >
          <Glyph
            size={14}
            weight="fill"
            className={cn('shrink-0', className)}
          />
          <span className="max-w-[12rem] truncate">{item.label}</span>
        </button>
      );
    })}
  </div>
);
