import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from '@heal/front-core/ui';
import {
  BugIcon,
  CodeIcon,
  DotsThreeIcon,
  EyeIcon,
  GitDiffIcon,
} from '@phosphor-icons/react';
import { useRef, type MouseEvent, type ReactNode } from 'react';

import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';
import { useCodeNavigation } from '../../../context/code-navigation-provider/code-navigation-provider.hooks';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { useTriageVerdictForm } from '../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import { useViewProvider } from '../../../context/view-provider/view-provider.hooks';
import type { VerdictType } from '../../../types/test';
import { TRIAGE_MODE_ID } from '../../mode/triage.mode';

interface ActionMenuProps {
  /** 0-based index of the failing statement to seed the form with. */
  failingStatementIndex: number;
  /** Source file of this statement, when known (enables "Explore code"). */
  file?: string | null;
  /** 1-based source line of this statement, when known. */
  line?: number | null;
  children: ReactNode;
}

interface CreateMenuItem {
  label: string;
  type?: VerdictType;
  Icon: typeof BugIcon;
  iconClass: string;
}

const CREATE_ITEMS: CreateMenuItem[] = [
  {
    label: 'Create a bug',
    type: 'BUG',
    Icon: BugIcon,
    iconClass: 'text-danger-solid',
  },
  {
    label: 'Create a UI change',
    type: 'UI_CHANGED',
    Icon: GitDiffIcon,
    iconClass: 'text-brand-solid',
  },
  {
    label: 'Other verdict…',
    type: undefined,
    Icon: DotsThreeIcon,
    iconClass: 'text-muted-foreground',
  },
];

export const ActionMenu = ({
  failingStatementIndex,
  file,
  line,
  children,
}: ActionMenuProps) => {
  const capabilities = useCapabilities();
  const { currentTest } = useDataProvider();
  const { mode } = useViewProvider();
  const { open } = useTriageVerdictForm();
  const { goToCode } = useCodeNavigation();

  const showVerdictItems =
    capabilities.canWriteTriagedVerdict && mode === TRIAGE_MODE_ID;
  const showExploreCode = file != null && line != null;

  if (!showVerdictItems && !showExploreCode) {
    return <>{children}</>;
  }

  const hasVerdict = !!(
    currentTest?.finalVerdict ?? currentTest?.triagedVerdict
  );

  // This menu wraps a whole step subtree, but each rendered row tags itself with
  // its own source location (`data-explore-file` / `-line`). On right-click we
  // resolve the location from the row under the cursor so "Explore code" opens
  // the clicked nested step's file — not the top-level step's. Falls back to the
  // wrapper's own file/line when the row isn't tagged.
  const exploreTargetRef = useRef<{ file: string; line: number } | null>(null);

  const captureExploreTarget = (event: MouseEvent<HTMLDivElement>) => {
    const row = (event.target as HTMLElement | null)?.closest?.(
      '[data-explore-file]',
    );
    if (row instanceof HTMLElement && row.dataset.exploreFile) {
      exploreTargetRef.current = {
        file: row.dataset.exploreFile,
        line: Number(row.dataset.exploreLine ?? 1),
      };

      return;
    }
    exploreTargetRef.current =
      file != null && line != null ? { file, line } : null;
  };

  const handleExploreCode = () => {
    const targetLocation =
      exploreTargetRef.current ??
      (file != null && line != null ? { file, line } : null);
    if (!targetLocation) {
      return;
    }
    // Reveal in the Code tab; test-content auto-selects that tab whenever the
    // navigation target changes.
    goToCode(targetLocation.file, targetLocation.line);
  };

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <div
          className="group/menu cursor-context-menu"
          onContextMenu={captureExploreTarget}
        >
          {children}
        </div>
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuLabel>Step {failingStatementIndex + 1}</ContextMenuLabel>
        <ContextMenuSeparator />
        {showExploreCode && (
          <ContextMenuItem onSelect={handleExploreCode}>
            <CodeIcon
              size={14}
              weight="fill"
              className="text-muted-foreground"
              aria-hidden
            />
            Explore code
          </ContextMenuItem>
        )}
        {showVerdictItems && hasVerdict && (
          <ContextMenuItem onSelect={() => open()}>
            <EyeIcon
              size={14}
              weight="fill"
              className="text-muted-foreground"
              aria-hidden
            />
            View verdict
          </ContextMenuItem>
        )}
        {showVerdictItems &&
          !hasVerdict &&
          CREATE_ITEMS.map(({ label, type, Icon, iconClass }) => (
            <ContextMenuItem
              key={label}
              onSelect={() => {
                open({
                  selectedFailingStatementIndex: failingStatementIndex,
                  selectedType: type,
                });
              }}
            >
              <Icon size={14} weight="fill" className={iconClass} aria-hidden />
              {label}
            </ContextMenuItem>
          ))}
      </ContextMenuContent>
    </ContextMenu>
  );
};
