import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react';

import type { ViewLayout } from '../../../../core/ui/features/trace-viewer';

import { LayoutContext, type LayoutContextValue } from './layout.context';

interface ModeLayoutProps {
  /** Mode identifier — used to derive the localStorage key. */
  mode: string;
  children: ReactNode;
}

const buildStorageKey = (mode: string): string => `tracer.${mode}.panelLayout`;

const readStoredSizes = (storageKey: string): Record<string, number> => {
  try {
    const raw = localStorage.getItem(storageKey);
    if (!raw) {
      return {};
    }

    const layout: ViewLayout = JSON.parse(raw);

    return layout.sizes ?? {};
  } catch {
    return {};
  }
};

const writeStoredSizes = (
  storageKey: string,
  sizes: Record<string, number>,
): void => {
  try {
    localStorage.setItem(storageKey, JSON.stringify({ sizes, visible: {} }));
  } catch {
    // ignore quota errors
  }
};

/**
 * Top-level wrapper that owns persisted size state for nested `<Row>`/`<Col>`
 * splits. Each split reads/writes its own pane sizes against a shared store
 * keyed by `mode`.
 */
export const ModeLayout = ({ mode, children }: ModeLayoutProps) => {
  const storageKey = buildStorageKey(mode);
  const [initialSizes] = useState(() => readStoredSizes(storageKey));
  const sizesRef = useRef<Record<string, number>>(initialSizes);

  const getDefaultSizes = useCallback(
    (paneIds: string[]): number[] | undefined => {
      const sizes = paneIds.map((id) => sizesRef.current[id]);
      if (sizes.every((s) => typeof s === 'number' && s > 0)) {
        return sizes;
      }

      return undefined;
    },
    [],
  );

  const onLayoutChange = useCallback(
    (layout: ViewLayout) => {
      sizesRef.current = { ...sizesRef.current, ...layout.sizes };
      writeStoredSizes(storageKey, sizesRef.current);
    },
    [storageKey],
  );

  const value = useMemo<LayoutContextValue>(
    () => ({ getDefaultSizes, onLayoutChange }),
    [getDefaultSizes, onLayoutChange],
  );

  return (
    <LayoutContext.Provider value={value}>{children}</LayoutContext.Provider>
  );
};
