import type { ReactNode } from 'react';

import { cn } from '../../../../lib/utils';

export interface TraceViewerHeaderClassNames {
  /** Root wrapper */
  root?: string;
  /** Left section */
  left?: string;
  /** Center section */
  center?: string;
  /** Right section */
  right?: string;
}

export interface TraceViewerHeaderProps {
  /** Left section (breadcrumb, title) */
  left?: ReactNode;
  /** Center section (attempt selector, metadata) */
  center?: ReactNode;
  /** Right section (actions, badges) */
  right?: ReactNode;
  /** Style overrides */
  classNames?: TraceViewerHeaderClassNames;
}

export const TraceViewerHeader = ({
  left,
  center,
  right,
  classNames,
}: TraceViewerHeaderProps) => {
  return (
    <div
      className={cn(
        'flex flex-1 items-center border-b bg-surface px-4 py-0.5 h-[36px] min-h-[36px]',
        classNames?.root,
      )}
    >
      {/* Left */}
      <div
        className={cn(
          'flex min-w-0 flex-1 items-center gap-2',
          classNames?.left,
        )}
      >
        {left}
      </div>

      {/* Center */}
      {center && (
        <div
          className={cn('flex shrink-0 items-center gap-2', classNames?.center)}
        >
          {center}
        </div>
      )}

      {/* Right */}
      <div
        className={cn(
          'flex shrink-0  items-center justify-end gap-2',
          classNames?.right,
        )}
      >
        {right}
      </div>
    </div>
  );
};
