import { VerdictForm, VerdictFormItem } from '@heal/front-core/ui';
import { ChatCircleIcon } from '@phosphor-icons/react';

import type { VerdictClassification } from '../../../../context/event-provider/event-provider.types';
import type { VerdictType } from '../../../../types/test';

interface VerdictFormOptionsProps {
  /** Current verdict type — drives option filtering and contextual wording. */
  currentType: VerdictType | null;
  onClassify?: (
    classification: VerdictClassification,
    comment: string | null,
  ) => void;
}

interface OptionContent {
  title: string;
  description: string;
  confirmLabel: string;
  inputPlaceholder: string;
}

interface OptionConfig extends OptionContent {
  classification: VerdictClassification;
  /**
   * Per-current-verdict-type wording overrides. Two effects:
   *   1) When the active verdict matches one of the keys, the override is
   *      merged on top of the base content.
   *   2) An option is normally hidden when its classification matches the
   *      current verdict type — but presence of an override for that key
   *      forces it to remain visible (recontextualized).
   */
  whenCurrent?: Partial<Record<VerdictType, Partial<OptionContent>>>;
}

const OPTIONS: OptionConfig[] = [
  {
    classification: 'BUG',
    title: 'This is a bug',
    description: 'Keep the test as is. Keep marking similar runs as bug.',
    confirmLabel: 'Mark as bug',
    inputPlaceholder: 'Give Heal additional context about this bug (optional)',
    whenCurrent: {
      UI_CHANGED: {
        title: "No it's a bug!",
        description: 'Report a real regression and keep the test failing.',
        confirmLabel: 'Mark as bug',
        inputPlaceholder:
          'Give Heal additional context about this bug (optional)',
      },
    },
  },
  {
    classification: 'UI_CHANGED',
    title: 'This is an intended change',
    description: 'This is an intended UI change. Update the test to match.',
    confirmLabel: 'Update test',
    inputPlaceholder:
      'Give Heal additional context about how to fix the test (optional)',
    whenCurrent: {
      BUG: {
        title: 'Not a bug, this is an intended change.',
        description: 'Update the test to match.',
        confirmLabel: 'Ignore this pattern',
        inputPlaceholder:
          'Give Heal additional context about how to fix the test (optional)',
      },
      UI_CHANGED: {
        title: 'This is intended. Update the test to match',
        description:
          'Mark this as expected and continue with updated baseline.',
        confirmLabel: 'Update the test',
        inputPlaceholder:
          'Give Heal additional context about how to fix the test (optional)',
      },
    },
  },
  {
    classification: 'BROKEN_TEST_LOGIC',
    title: 'The test code is broken.',
    description: 'Tell Heal how to repair the test.',
    confirmLabel: 'Fix test',
    inputPlaceholder: 'Tell Heal how to fix the test…',
  },
];

const resolveOptionContent = (
  option: OptionConfig,
  currentType: VerdictType | null,
): OptionContent => {
  const override = currentType ? option.whenCurrent?.[currentType] : undefined;

  return {
    title: override?.title ?? option.title,
    description: override?.description ?? option.description,
    confirmLabel: override?.confirmLabel ?? option.confirmLabel,
    inputPlaceholder: override?.inputPlaceholder ?? option.inputPlaceholder,
  };
};

const isOptionVisible = (
  option: OptionConfig,
  currentType: VerdictType | null,
): boolean => {
  if (option.classification !== currentType) {
    return true;
  }

  return Boolean(currentType && option.whenCurrent?.[currentType]);
};

const OPTIONS_USING_LETTERS: VerdictType[] = ['UI_CHANGED'];

export const VerdictFormOptions = ({
  currentType,
  onClassify,
}: VerdictFormOptionsProps) => {
  const visibleOptions = OPTIONS.filter((option) =>
    isOptionVisible(option, currentType),
  );

  if (visibleOptions.length === 0) {
    return null;
  }

  const handleSave = (value: string, comment: string | null) => {
    const option = visibleOptions.find(
      (entry) => entry.classification === value,
    );
    if (option) {
      onClassify?.(option.classification, comment);
    }
  };

  const withLetters = currentType
    ? OPTIONS_USING_LETTERS.includes(currentType)
    : false;

  return (
    <div className="flex flex-col gap-3">
      <OptionsPrompt currentType={currentType} />
      <VerdictForm onSave={handleSave} withLetters={withLetters}>
        {visibleOptions.map((option) => {
          const content = resolveOptionContent(option, currentType);

          return (
            <VerdictFormItem
              key={option.classification}
              value={option.classification}
              verdictType={option.classification}
              title={content.title}
              description={content.description}
              confirmLabel={content.confirmLabel}
              withInput
              inputPlaceholder={content.inputPlaceholder}
            />
          );
        })}
      </VerdictForm>
    </div>
  );
};

// ─── Prompt ─────────────────────────────────────────────────────

const OptionsPrompt = ({
  currentType,
}: {
  currentType: VerdictType | null;
}) => {
  if (currentType === 'UI_CHANGED') {
    return (
      <div className="flex items-start gap-2 text-sm font-medium text-foreground">
        <ChatCircleIcon
          size={16}
          weight="fill"
          className="mt-0.5 shrink-0 text-brand-solid"
          aria-hidden
        />
        This test is paused and needs your input. Tell Heal how to proceed.
      </div>
    );
  }

  return (
    <span className="text-sm font-medium text-foreground">
      Tell Heal what to do next
    </span>
  );
};
