import { baseApiPath, handle } from '../http';
import type { ExecutionsResponse, IndexResponse } from '../types';

/** Query-key factory ("tags") for the executions domain. */
export const executionsKeys = {
  all: ['executions'] as const,
  list: () => [...executionsKeys.all, 'list'] as const,
  index: (executionId: string) =>
    [...executionsKeys.all, 'index', executionId] as const,
};

export const getExecutions = async (): Promise<ExecutionsResponse> =>
  handle<ExecutionsResponse>(await fetch(baseApiPath('/api/executions')));

export const getExecutionIndex = async (
  executionId: string,
): Promise<IndexResponse> =>
  handle<IndexResponse>(
    await fetch(
      baseApiPath(
        `/api/executions/${encodeURIComponent(executionId)}/index.json`,
      ),
    ),
  );
