import { Button } from '@heal/front-core/ui';
import { CustomTooltip as Tooltip } from '@heal/front-core/ui';
import { CopySimpleIcon, FileIcon } from '@phosphor-icons/react';
import { ExternalLinkIcon, GitBranchIcon } from 'lucide-react';
import { type ReactNode, useMemo } from 'react';
import { useCopyToClipboard } from 'usehooks-ts';

import {
  AttemptMajorityBadge,
  HeaderAttemptSelector,
  HeaderBreadcrumb,
  TraceViewerHeader,
} from '../../../../../core/ui/features/trace-viewer';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { useEventProvider } from '../../../context/event-provider/event-provider.hooks';
import { useExecutionProvider } from '../../../context/execution-provider/execution-provider.hooks';
import { useNavigationProvider } from '../../../context/navigation-provider/navigation-provider.hooks';
import type { TestCase } from '../../../types/test';
import { TestListItemAttempt } from '../../../types/test-list';
import { getMajorityAttempt } from '../../../utils/get-majority-attempt';

interface BreadcrumbItem {
  label: ReactNode;
  icon?: ReactNode;
  onClick?: () => void;
}

const buildPlaywrightTraceViewerUrl = (traceUrl: string): string => {
  const absolute = new URL(traceUrl, window.location.origin).toString();

  return `https://trace.playwright.dev/?trace=${encodeURIComponent(absolute)}`;
};

const TestIdLabel = ({
  playwrightTestId,
  displayLabel,
  onCopy,
}: {
  playwrightTestId: string;
  displayLabel: string;
  onCopy: (text: string) => void;
}) => (
  <Tooltip
    enabled
    delayDuration={200}
    content={
      <button
        type="button"
        className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground underline underline-offset-2"
        onClick={() => void onCopy(playwrightTestId)}
      >
        <CopySimpleIcon size={12} aria-hidden />
        Test ID: {playwrightTestId}
      </button>
    }
  >
    <span className="ml-1">{displayLabel}</span>
  </Tooltip>
);

const formatExecutionLabel = (
  e: { id: string; startedAt?: number },
  index: number,
): string => {
  if (e.startedAt) {
    return new Date(e.startedAt).toLocaleString(undefined, {
      year: 'numeric',
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  if (index === 0) {
    return `${e.id.slice(0, 8)} (latest)`;
  }

  return e.id.slice(0, 12);
};

export const HEADER_VIEW_ID = 'header';
export const HeaderView = () => {
  const { currentTest, testList } = useDataProvider();
  const { onTestCaseClick } = useEventProvider();
  const { goToIndex, goToTestAttempt } = useNavigationProvider();
  const { executions, currentExecutionId, onExecutionChange } =
    useExecutionProvider();
  const [, copyToClipboard] = useCopyToClipboard();

  const executionOptions = useMemo(
    () =>
      executions.map((e, idx) => ({
        id: e.id,
        label: formatExecutionLabel(e, idx),
      })),
    [executions],
  );

  const currentExecution = useMemo(
    () => executions.find((e) => e.id === currentExecutionId) ?? null,
    [executions, currentExecutionId],
  );

  const branchLabel = currentExecution?.git?.branch?.trim() || null;

  const currentTestItem = useMemo(() => {
    if (!currentTest) {
      return null;
    }

    return (
      testList.find((t) =>
        t.attempts.some(
          (a) => a.playwrightTestId === currentTest.playwrightTestId,
        ),
      ) ?? null
    );
  }, [currentTest, testList]);

  const attemptOptions = useMemo(() => {
    if (!currentTestItem) {
      return [];
    }

    const majorityAttempt = getMajorityAttempt(currentTestItem.attempts);
    const showBadge = (a: TestListItemAttempt) => {
      if (currentTestItem?.attempts.length <= 1) {
        return false;
      }

      return a.attempt === majorityAttempt?.attempt;
    };

    return currentTestItem.attempts.map((a) => ({
      id: a.attempt,
      label: `Attempt ${a.attempt}`,
      badge: showBadge(a) ? <AttemptMajorityBadge /> : undefined,
      compactBadge: showBadge(a) ? <AttemptMajorityBadge compact /> : undefined,
    }));
  }, [currentTestItem]);

  const handleAttemptChange = (id: string) => {
    if (!currentTestItem) {
      return;
    }

    const attemptNumber = Number(id);

    goToTestAttempt(attemptNumber, {
      executionId: currentTestItem.executionId,
      testId:
        currentTestItem.attempts[attemptNumber - 1]?.playwrightTestId ?? '',
    });
  };

  const handleTestCaseClick = (testCase: TestCase) => {
    if (onTestCaseClick) {
      onTestCaseClick(testCase);
    }
  };

  const getBreadcrumbItems = (): BreadcrumbItem[] => {
    const items: BreadcrumbItem[] = [
      {
        label: branchLabel ?? currentTestItem?.repoName ?? 'Tests',
        icon: <GitBranchIcon className="size-3.5" />,
        onClick: goToIndex,
      },
    ];

    if (currentTest?.testCase) {
      items.push({
        label: currentTest.testCase.name,
        icon: <FileIcon className="size-3.5" />,
        onClick: () => handleTestCaseClick(currentTest.testCase!),
      });
    }

    if (currentTestItem && currentTest) {
      items.push({
        label: (
          <TestIdLabel
            playwrightTestId={currentTest.playwrightTestId}
            displayLabel={
              currentTestItem.title ?? currentTest.testCase?.name ?? ''
            }
            onCopy={copyToClipboard}
          />
        ),
      });
    }

    return items;
  };

  return (
    <TraceViewerHeader
      left={
        <>
          {executionOptions.length > 0 && currentExecutionId && (
            <HeaderAttemptSelector
              options={executionOptions}
              value={currentExecutionId}
              onChange={onExecutionChange}
              label={
                executionOptions.find((o) => o.id === currentExecutionId)
                  ?.label ?? 'Execution'
              }
            />
          )}
          <HeaderBreadcrumb items={getBreadcrumbItems()} />
          {currentTest && (
            <HeaderAttemptSelector
              options={attemptOptions}
              value={String(currentTest.attempt)}
              onChange={handleAttemptChange}
              label={`Attempt ${currentTest.attempt}/${attemptOptions.length}`}
            />
          )}
        </>
      }
      right={
        <>
          {currentTest?.playwrightTraceUrl ? (
            <Button variant="ghost" size="sm" asChild className="p-0">
              <a
                href={buildPlaywrightTraceViewerUrl(
                  currentTest.playwrightTraceUrl,
                )}
                target="_blank"
                rel="noreferrer"
              >
                <ExternalLinkIcon className="size-3.5" />
                Trace
              </a>
            </Button>
          ) : null}
        </>
      }
    />
  );
};
