import { useCallback, useMemo, useRef, useState, type RefObject } from 'react';

/** Default jump-back distance for the rewind control (in ms). */
export const REWIND_INTERVAL_MS = 10_000;

/** Default playback-rate options surfaced in the controls. */
export const DEFAULT_PLAYBACK_RATES: number[] = [0.25, 0.5, 1, 2, 4];

export interface VideoControllerState {
  currentTimeMs: number;
  isPlaying: boolean;
  durationMs: number;
  bufferedPercent: number;
  playbackRate: number;
}

export interface VideoControllerActions {
  pause: () => void;
  togglePlay: () => void;
  seek: (timeMs: number) => void;
  setPlaybackRate: (rate: number) => void;
}

export interface VideoElementHandlers {
  onTimeUpdate: () => void;
  onLoadedMetadata: () => void;
  onProgress: () => void;
  onPlay: () => void;
  onPause: () => void;
  onEnded: () => void;
  onRateChange: () => void;
}

export interface VideoController {
  state: VideoControllerState;
  actions: VideoControllerActions;
  /** Attach to the underlying <video> element. */
  videoRef: RefObject<HTMLVideoElement>;
  /** Spread onto the underlying <video> element to wire up state sync. */
  videoElementProps: VideoElementHandlers;
}

export const useVideoController = (): VideoController => {
  const videoRef = useRef<HTMLVideoElement>(null);

  const [currentTimeMs, setCurrentTimeMs] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [durationMs, setDurationMs] = useState(0);
  const [bufferedPercent, setBufferedPercent] = useState(0);
  const [playbackRate, setPlaybackRateState] = useState(1);

  const seek = useCallback((timeMs: number) => {
    const video = videoRef.current;
    if (video) {
      video.currentTime = timeMs / 1000;
    }
    setCurrentTimeMs(timeMs);
  }, []);

  const pause = useCallback(() => {
    videoRef.current?.pause();
  }, []);

  const togglePlay = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (video.paused || video.ended) {
      video.play();
    } else {
      video.pause();
    }
  }, []);

  const setPlaybackRate = useCallback((rate: number) => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    // State is mirrored by handleRateChange when the browser confirms.
    video.playbackRate = rate;
  }, []);

  const handleTimeUpdate = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    setCurrentTimeMs(video.currentTime * 1000);
  }, []);

  const handleLoadedMetadata = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    setDurationMs(video.duration * 1000);
  }, []);

  const handleProgress = useCallback(() => {
    const video = videoRef.current;
    if (!video || video.buffered.length === 0) {
      return;
    }
    const buffered = video.buffered.end(video.buffered.length - 1);
    setBufferedPercent((buffered / video.duration) * 100);
  }, []);

  const handlePlay = useCallback(() => setIsPlaying(true), []);
  const handlePause = useCallback(() => setIsPlaying(false), []);
  const handleEnded = useCallback(() => setIsPlaying(false), []);

  const handleRateChange = useCallback(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    setPlaybackRateState(video.playbackRate);
  }, []);

  const state = useMemo<VideoControllerState>(
    () => ({
      currentTimeMs,
      isPlaying,
      durationMs,
      bufferedPercent,
      playbackRate,
    }),
    [currentTimeMs, isPlaying, durationMs, bufferedPercent, playbackRate],
  );

  const actions = useMemo<VideoControllerActions>(
    () => ({ pause, togglePlay, seek, setPlaybackRate }),
    [pause, togglePlay, seek, setPlaybackRate],
  );

  const videoElementProps = useMemo<VideoElementHandlers>(
    () => ({
      onTimeUpdate: handleTimeUpdate,
      onLoadedMetadata: handleLoadedMetadata,
      onProgress: handleProgress,
      onPlay: handlePlay,
      onPause: handlePause,
      onEnded: handleEnded,
      onRateChange: handleRateChange,
    }),
    [
      handleTimeUpdate,
      handleLoadedMetadata,
      handleProgress,
      handlePlay,
      handlePause,
      handleEnded,
      handleRateChange,
    ],
  );

  return { state, actions, videoRef, videoElementProps };
};
