import { TestListGroupBy } from '../../../../context/view-provider/view-provider.types';
import { AttemptStatus } from '../../../../types/attempt';
import { TestListItem, TestListItemAttempt } from '../../../../types/test-list';

export interface TestGroup {
  label: string;
  tests: TestListItem[];
}

export function filterTests(
  tests: TestListItem[],
  searchQuery: string,
  statusFilter: AttemptStatus[],
): TestListItem[] {
  let filtered = tests;

  if (searchQuery.trim()) {
    const query = searchQuery.toLowerCase();
    filtered = filtered.filter((test) =>
      test.title?.toLowerCase().includes(query),
    );
  }

  if (statusFilter.length > 0) {
    filtered = filtered.filter((test) => {
      const lastAttempt = getLastAttempt(test);
      const status = lastAttempt?.status;

      return status && statusFilter.includes(status);
    });
  }

  return filtered;
}

export function groupTests(
  tests: TestListItem[],
  groupBy: TestListGroupBy,
): TestGroup[] {
  if (groupBy === 'none') {
    return [{ label: '', tests }];
  }

  const groups = new Map<string, TestListItem[]>();

  for (const test of tests) {
    const key = getGroupKey(test, groupBy);
    const existing = groups.get(key);
    if (existing) {
      existing.push(test);
    } else {
      groups.set(key, [test]);
    }
  }

  return Array.from(groups.entries()).map(([label, items]) => ({
    label,
    tests: items,
  }));
}

function getGroupKey(test: TestListItem, groupBy: TestListGroupBy): string {
  switch (groupBy) {
    case 'project': {
      return test.project ?? 'No project';
    }
    case 'team': {
      return test.testCase?.team?.slug ?? 'No team';
    }
    case 'team-and-feature': {
      const team = test.testCase?.team?.slug ?? 'No team';
      const feature = test.testCase?.feature?.slug ?? 'No feature';

      return `${team} / ${feature}`;
    }
    default: {
      return '';
    }
  }
}

function getLastAttempt(test: TestListItem): TestListItemAttempt | null {
  if (test.attempts.length === 0) {
    return null;
  }

  return test.attempts[test.attempts.length - 1];
}
