// Mappers from the tracer's wire format (as exposed by
// `@heal-dev/heal-playwright-tracer`'s local HTTP server) to the
// shapes consumed by `@heal-dev/front-run-viewer`'s `<Tracer>`.
//
// Two non-obvious choices, both load-bearing:
//
// 1. `executionId` flows through end-to-end. The server scopes
//    everything by execution; the SPA stores the currently-selected
//    one and routes <Tracer>'s `(executionId, playwrightTestId,
//    attempt)` triple off of it.
//
// 2. We fold our flat `TestSummary[]` (one entry per attempt
//    directory on disk) into one `TestListItem` per
//    `(file, title, project)` triple, with attempts as children.
//    Otherwise the attempt-selector in the header would always read
//    "Attempt 1 / 1" even on retried tests.

import { createStatementVideoResolver } from '@heal-dev/front-run-viewer';
import type {
  ResolverVideo,
  Statement as TracerStatement,
  Test as TracerTest,
  TestList,
  TestListItem,
  TriagedVerdict,
} from '@heal-dev/front-run-viewer';

import { baseApiPath } from '../api/http';
import type {
  AttachmentRef,
  Statement,
  TestSummary,
  TraceModel,
} from '../api/types';

const groupKey = (s: TestSummary): string =>
  `${s.file}::${s.title}::${s.project}`;

export const toTestList = (
  executionId: string,
  summaries: TestSummary[],
): TestList => {
  const groups = new Map<string, TestSummary[]>();
  for (const s of summaries) {
    const k = groupKey(s);
    const arr = groups.get(k) ?? [];
    arr.push(s);
    groups.set(k, arr);
  }

  const items: TestListItem[] = [];
  for (const arr of groups.values()) {
    arr.sort((a, b) => a.attempt - b.attempt);
    const head = arr[0];
    items.push({
      executionId,
      title: head.title,
      file: head.file,
      project: head.project,
      repoName: 'local',
      testCase: null,
      attempts: arr.map((a) => ({
        playwrightTestId: a.playwrightTestId,
        attempt: a.attempt,
        status: a.status === 'unknown' ? null : a.status,
        startedAt: new Date(a.startedAt).toISOString(),
        durationMs: a.duration,
        triagedVerdict: null,
        finalVerdict: null,
      })),
    });
  }

  // Stable ordering: by file then title
  items.sort((a, b) => {
    const byFile = (a.file ?? '').localeCompare(b.file ?? '');
    if (byFile !== 0) {
      return byFile;
    }

    return (a.title ?? '').localeCompare(b.title ?? '');
  });

  return items;
};

const toVideoId = (attachment: AttachmentRef): string =>
  attachment.pageId ?? attachment.url;

const toResolverVideo = (attachment: AttachmentRef): ResolverVideo => ({
  id: toVideoId(attachment),
  pageId: attachment.pageId,
  videoStartWallMs: attachment.videoStartWallMs,
});

const mapStatement = (
  stmt: Statement,
  resolveStatementVideo: ReturnType<typeof createStatementVideoResolver>,
): TracerStatement => {
  // Resolve before recursing into children to preserve execution order
  // (pre-order) for the carry-forward of `pageId`.
  const resolved = resolveStatementVideo({
    pageId: stmt.pageId,
    videoTime: stmt.videoTime,
    timestampMs: stmt.t,
  });

  return {
    id: stmt.seq,
    code: stmt.source,
    status: stmt.status === 'ok' ? 'passed' : 'failed',
    timestampMs: stmt.t,
    durationMs: stmt.duration,
    comment: stmt.leadingComment ?? null,
    children: stmt.children.map((child) =>
      mapStatement(child, resolveStatementVideo),
    ),
    screenshot: stmt.screenshot ?? null,
    error: stmt.error ?? null,
    file: stmt.file ?? null,
    line: stmt.line ?? null,
    endLine: stmt.endLine ?? null,
    videoId: resolved.videoId,
    videoTimeMs: resolved.videoTimeMs,
  };
};

const findPlaywrightTraceUrl = (trace: TraceModel): string | undefined =>
  trace.attachments?.find((a) => a.name === 'trace')?.url;

const deriveSources = (trace: TraceModel): TracerTest['sources'] =>
  trace.source?.map((ref) => ({
    url: ref.url,
    path: ref.path,
    bytes: ref.bytes,
    entry: ref.entry,
    truncated: ref.truncated,
  }));

const videoAttachments = (trace: TraceModel): AttachmentRef[] =>
  (trace.attachments ?? []).filter((a) =>
    a.contentType.toLowerCase().startsWith('video/'),
  );

const deriveVideos = (videos: AttachmentRef[]): TracerTest['videos'] =>
  videos
    .map((a) => ({
      id: toVideoId(a),
      url: baseApiPath(a.url),
      label: a.path.split('/').pop()?.toLowerCase() ?? a.name,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));

export const toTracerTest = (
  trace: TraceModel,
  playwrightTestId: string,
  triagedVerdict: TriagedVerdict | null = null,
): TracerTest => {
  const videos = videoAttachments(trace);
  const resolveStatementVideo = createStatementVideoResolver({
    videos: videos.map(toResolverVideo),
    testStartedAtMs: trace.header.startedAt,
  });

  return {
    playwrightTestId,
    attempt: trace.header.context.attempt,
    repoName: 'local',
    statements: trace.statements.map((stmt) =>
      mapStatement(stmt, resolveStatementVideo),
    ),
    videos: deriveVideos(videos),
    testCase: null,
    triagedVerdict,
    finalVerdict: null,
    // The standalone viewer surfaces analysis via the host-supplied analyze
    // slot, not the backend-derived status.
    analysisStatus: 'not_applicable',
    failure: null,
    playwrightTraceUrl: findPlaywrightTraceUrl(trace),
    sources: deriveSources(trace),
  };
};
