import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';

import { cn } from '../../../lib/utils';
import {
  VerdictFormOption,
  type VerdictFormOptionProps,
} from '../verdict-form-option/verdict-form-option';
import type {
  VerdictResultStatus,
  VerdictType,
} from '../verdict-result-indicator/verdict-result-indicator';

// ─── Types ──────────────────────────────────────────────────────

export interface VerdictFormProps {
  value?: string | null;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  saved?: string | null;
  onSave?: (value: string, comment: string | null) => void;
  pendingValue?: string | null;
  withLetters?: boolean;
  className?: string;
  children: React.ReactNode;
}

interface VerdictFormContextValue {
  selectedValue: string | null;
  savedValue: string | null;
  pendingValue: string | null;
  withLetters: boolean;
  itemValues: string[];
  registerItem: (value: string) => void;
  unregisterItem: (value: string) => void;
  selectItem: (value: string) => void;
  saveItem: (value: string, comment: string | null) => void;
}

const VerdictFormContext = createContext<VerdictFormContextValue | null>(null);

const useVerdictFormContext = (): VerdictFormContextValue => {
  const ctx = useContext(VerdictFormContext);
  if (!ctx) {
    throw new Error('VerdictFormItem must be rendered inside <VerdictForm>');
  }

  return ctx;
};

// ─── Root ───────────────────────────────────────────────────────

export const VerdictForm = ({
  value,
  defaultValue,
  onValueChange,
  saved = null,
  onSave,
  pendingValue = null,
  withLetters = false,
  className,
  children,
}: VerdictFormProps) => {
  const [internalSelected, setInternalSelected] = useState<string | null>(
    defaultValue ?? null,
  );
  const [itemValues, setItemValues] = useState<string[]>([]);

  const isControlled = value !== undefined;
  const selectedValue = isControlled ? (value ?? null) : internalSelected;

  const registerItem = useCallback((next: string) => {
    setItemValues((prev) => {
      if (prev.includes(next)) {
        return prev;
      }

      return [...prev, next];
    });
  }, []);

  const unregisterItem = useCallback((next: string) => {
    setItemValues((prev) => prev.filter((existing) => existing !== next));
  }, []);

  const selectItem = useCallback(
    (next: string) => {
      if (!isControlled) {
        setInternalSelected(next);
      }
      onValueChange?.(next);
    },
    [isControlled, onValueChange],
  );

  const saveItem = useCallback(
    (next: string, comment: string | null) => {
      onSave?.(next, comment);
    },
    [onSave],
  );

  const contextValue = useMemo<VerdictFormContextValue>(
    () => ({
      selectedValue,
      savedValue: saved,
      pendingValue,
      withLetters,
      itemValues,
      registerItem,
      unregisterItem,
      selectItem,
      saveItem,
    }),
    [
      selectedValue,
      saved,
      pendingValue,
      withLetters,
      itemValues,
      registerItem,
      unregisterItem,
      selectItem,
      saveItem,
    ],
  );

  return (
    <VerdictFormContext.Provider value={contextValue}>
      <div role="radiogroup" className={cn('flex flex-col gap-3', className)}>
        {children}
      </div>
    </VerdictFormContext.Provider>
  );
};

// ─── Item ───────────────────────────────────────────────────────

export interface VerdictFormItemProps {
  value: string;
  title: string;
  description?: string;
  savedDescription?: string;
  verdictType?: VerdictType;
  status?: VerdictResultStatus;
  letter?: string;
  withInput?: boolean;
  inputPlaceholder?: string;
  confirmLabel?: string;
  disabled?: boolean;
  className?: string;
}

export const VerdictFormItem = ({
  value,
  title,
  description,
  savedDescription,
  verdictType,
  status,
  letter,
  withInput = false,
  inputPlaceholder,
  confirmLabel,
  disabled = false,
  className,
}: VerdictFormItemProps) => {
  const ctx = useVerdictFormContext();
  const { registerItem, unregisterItem } = ctx;
  const [inputValue, setInputValue] = useState('');

  useEffect(() => {
    registerItem(value);

    return () => {
      unregisterItem(value);
    };
  }, [registerItem, unregisterItem, value]);

  const selected = ctx.selectedValue === value;
  const saved = ctx.savedValue === value;
  const isPending = ctx.pendingValue === value;
  const derivedLetter = resolveLetter(letter, ctx, value);

  const handleSelect = () => {
    ctx.selectItem(value);
  };

  const handleConfirm = () => {
    const comment = withInput ? inputValue.trim() || null : null;
    ctx.saveItem(value, comment);
  };

  const inputProp: VerdictFormOptionProps['input'] = withInput
    ? {
        value: inputValue,
        onChange: setInputValue,
        placeholder: inputPlaceholder,
      }
    : undefined;

  const confirmationProp: VerdictFormOptionProps['confirmation'] = confirmLabel
    ? {
        label: confirmLabel,
        onConfirm: handleConfirm,
        isPending,
      }
    : undefined;

  return (
    <VerdictFormOption
      letter={derivedLetter}
      title={title}
      description={description}
      savedDescription={savedDescription}
      verdictType={verdictType}
      status={status}
      selected={selected}
      saved={saved}
      onSelect={handleSelect}
      disabled={disabled}
      input={inputProp}
      confirmation={confirmationProp}
      className={className}
    />
  );
};

// ─── Helpers ────────────────────────────────────────────────────

const resolveLetter = (
  explicit: string | undefined,
  ctx: VerdictFormContextValue,
  value: string,
): string | undefined => {
  if (explicit !== undefined) {
    return explicit;
  }
  if (!ctx.withLetters) {
    return undefined;
  }

  const index = ctx.itemValues.indexOf(value);
  if (index < 0) {
    return undefined;
  }

  return String.fromCharCode(65 + index);
};
