import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@heal/front-core/ui';
import type { useForm } from 'react-hook-form';

import type { CreateTriageVerdictFormValues } from '../_lib/create-triage-verdict-form-schema';

interface StepOption {
  value: number;
  label: string;
  status: 'passed' | 'failed';
}

interface StepFieldProps {
  form: ReturnType<typeof useForm<CreateTriageVerdictFormValues>>;
  stepOptions: StepOption[];
}

const getStepDotClass = (status: StepOption['status']) => {
  if (status === 'failed') {
    return 'bg-danger-solid';
  }

  return 'bg-success-solid';
};

export const StepField = ({ form, stepOptions }: StepFieldProps) => {
  if (stepOptions.length === 0) {
    return null;
  }

  return (
    <FormField
      control={form.control}
      name="failingStatementIndex"
      render={({ field }) => {
        const selectValue =
          field.value !== undefined ? String(field.value) : undefined;
        const handleValueChange = (next: string) =>
          field.onChange(Number(next));

        return (
          <FormItem>
            <FormLabel className="text-xs">Step</FormLabel>
            <Select value={selectValue} onValueChange={handleValueChange}>
              <FormControl>
                <SelectTrigger className="h-8 w-full border-border bg-background text-xs">
                  <SelectValue placeholder="Select a step" />
                </SelectTrigger>
              </FormControl>
              <SelectContent>
                {stepOptions.map((option) => (
                  <SelectItem key={option.value} value={String(option.value)}>
                    <span
                      aria-hidden
                      className={`mr-2 inline-block size-2 shrink-0 rounded-full ${getStepDotClass(option.status)}`}
                    />
                    <span className="mr-2 font-mono text-[10px] tabular-nums text-muted-foreground">
                      {option.value + 1}
                    </span>
                    <span className="truncate">{option.label}</span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormItem>
        );
      }}
    />
  );
};
