import { Badge } from '../../../../components/badge/badge';
import { CustomTooltip } from '../../../../components/custom-tooltip/custom-tooltip';

export interface AttemptMajorityBadgeProps {
  /**
   * Compact form (star only) for the closed selector trigger. The full form
   * (star + "Majority") is used inside the open dropdown.
   */
  compact?: boolean;
}

/**
 * Highlights the "majority" attempt — the one the deduplication algorithm
 * selected as the representative failure for a test.
 */
export const AttemptMajorityBadge = ({
  compact = false,
}: AttemptMajorityBadgeProps) => {
  if (compact) {
    return (
      <CustomTooltip content="To investigate run results and determine the verdict, Heal first determines what attempt is the most relevant.">
        <div className={'h-2 w-2 rounded-full bg-brand-solid'} />
      </CustomTooltip>
    );
  }

  return (
    <CustomTooltip content="To investigate run results and determine the verdict, Heal first determines what attempt is the most relevant.">
      <Badge variant="brand" tiny>
        Most relevant
      </Badge>
    </CustomTooltip>
  );
};
