import { baseApiPath, handle } from '../http';
import type { TraceModel } from '../types';

/** Query-key factory ("tags") for the traces domain. */
export const tracesKeys = {
  all: ['traces'] as const,
  detail: (executionId: string, playwrightTestId: string, attempt: number) =>
    [
      ...tracesKeys.all,
      'detail',
      executionId,
      playwrightTestId,
      attempt,
    ] as const,
  /**
   * Keyed by the full `SourceRef.url`, which embeds the content hash — so the
   * key changes when the file content changes and the cache entry is immutable.
   */
  source: (url: string) => [...tracesKeys.all, 'source', url] as const,
};

export const getTrace = async (
  executionId: string,
  playwrightTestId: string,
  attempt: number,
): Promise<TraceModel> =>
  handle<TraceModel>(
    await fetch(
      baseApiPath(
        `/api/executions/${encodeURIComponent(executionId)}/tests/${encodeURIComponent(playwrightTestId)}/${attempt}`,
      ),
    ),
  );

/**
 * Fetches a source file's raw text from a `SourceRef.url`. The URL is
 * pre-encoded by the server — pass it verbatim. Throws on a non-200 (e.g.
 * a 404 for a truncated/absent file) so callers can skip it.
 *
 * Backs the `<Tracer onLoadSourceContent>` callback; cached via
 * {@link useLoadSourceContent} so each content-addressed URL is fetched once.
 */
export const getSource = async (url: string): Promise<string> => {
  const res = await fetch(baseApiPath(url));
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  }

  return res.text();
};
