import {
  TraceViewerSidePanel,
  TraceViewerTestListItem,
  SidePanelState,
} from '@heal/front-core/ui';
import { ReactNode, useMemo, useState } from 'react';

import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { useNavigationProvider } from '../../../context/navigation-provider/navigation-provider.hooks';
import { useViewProvider } from '../../../context/view-provider/view-provider.hooks';
import { TestListItem, TestListItemAttempt } from '../../../types/test-list';
import { formatDuration } from '../../../utils/format-duration';
import { getMajorityAttempt } from '../../../utils/get-majority-attempt';
import { mapAttemptStatusToVerdict } from '../../../utils/map-attempt-status-to-verdict';

import { TestListGroupHeader } from './_components/test-list-group-header';
import { TestListItemSkeleton } from './_components/test-list-item-skeleton';
import { TestListToolbar } from './_components/test-list-toolbar';
import { filterTests, groupTests } from './_utils/filter-and-group-tests';

export const TEST_LIST_VIEW_ID = 'test-list';
export const TestListView = () => {
  return (
    <Wrapper foldedContent={<FoldedList />}>
      <ExpandedList />
    </Wrapper>
  );
};

const FoldedList = () => {
  const { testList, currentTest } = useDataProvider();
  const { goToTest } = useNavigationProvider();

  const handleSelectTest = (test: (typeof testList)[number]) => {
    goToTest(test.attempts[0]?.playwrightTestId, {
      executionId: test.executionId,
      attemptNumber: getMajorityAttempt(test.attempts)?.attempt,
    });
  };

  function isTestSelected(test: TestListItem) {
    const currentId = currentTest?.playwrightTestId;

    if (!currentId) {
      return false;
    }

    const attemptIds = test.attempts.map((attempt) => attempt.playwrightTestId);

    return attemptIds.includes(currentId);
  }

  return (
    <div className="flex-1 overflow-auto">
      {testList.map((test, index) => {
        const lastAttempt = getLastAttempt(test);

        return (
          <TraceViewerTestListItem
            key={test.attempts[0]?.playwrightTestId ?? index}
            label={test.title ?? ''}
            onClick={() => handleSelectTest(test)}
            status={mapAttemptStatusToVerdict(lastAttempt?.status)}
            verdictType={
              lastAttempt?.finalVerdict?.payload.type ??
              lastAttempt?.triagedVerdict?.payload.type
            }
            duration={formatDuration(lastAttempt?.durationMs ?? 0)}
            folded
            selected={isTestSelected(test)}
          />
        );
      })}
    </div>
  );
};

const ExpandedList = () => {
  const { testList, currentTest, pendingRun } = useDataProvider();
  const { goToTest } = useNavigationProvider();
  const { testListFilters } = useViewProvider();
  const { searchQuery, statusFilter, groupBy } = testListFilters;

  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(
    new Set(),
  );

  const filtered = useMemo(
    () => filterTests(testList, searchQuery, statusFilter),
    [testList, searchQuery, statusFilter],
  );

  const groups = useMemo(
    () => groupTests(filtered, groupBy),
    [filtered, groupBy],
  );

  const isGrouped = groupBy !== 'none';

  const handleToggleGroup = (label: string) => {
    setCollapsedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(label)) {
        next.delete(label);
      } else {
        next.add(label);
      }

      return next;
    });
  };

  const handleSelectTest = (test: (typeof testList)[number]) => {
    goToTest(test.attempts[0]?.playwrightTestId, {
      executionId: test.executionId,
      attemptNumber: getMajorityAttempt(test.attempts)?.attempt,
    });
  };

  function isTestSelected(test: TestListItem) {
    const currentId = currentTest?.playwrightTestId;

    if (!currentId) {
      return false;
    }

    const attemptIds = test.attempts.map((attempt) => attempt.playwrightTestId);

    return attemptIds.includes(currentId);
  }

  function getVerdictType(test: TestListItem) {
    return test.attempts
      .map(
        (attempt) =>
          attempt.finalVerdict?.payload.type ??
          attempt.triagedVerdict?.payload.type,
      )
      .filter((v) => v !== undefined)[0];
  }

  return (
    <div className="flex h-full flex-col">
      <TestListToolbar />
      <div className="flex-1 overflow-auto">
        {groups.map((group) => {
          const isCollapsed = collapsedGroups.has(group.label);

          return (
            <div key={group.label}>
              {isGrouped && (
                <TestListGroupHeader
                  label={group.label}
                  count={group.tests.length}
                  isOpen={!isCollapsed}
                  onToggle={() => handleToggleGroup(group.label)}
                />
              )}
              {!isCollapsed &&
                group.tests.map((test, index) => {
                  const lastAttempt = getLastAttempt(test);

                  return (
                    <TraceViewerTestListItem
                      key={test.attempts[0]?.playwrightTestId ?? index}
                      label={test.title ?? ''}
                      onClick={() => handleSelectTest(test)}
                      status={mapAttemptStatusToVerdict(lastAttempt?.status)}
                      duration={formatDuration(lastAttempt?.durationMs ?? 0)}
                      selected={isTestSelected(test)}
                      verdictType={getVerdictType(test)}
                    />
                  );
                })}
            </div>
          );
        })}
        <TestListPlaceholder
          hasTests={testList.length > 0}
          hasVisibleTests={filtered.length > 0}
          pendingRun={pendingRun}
        />
      </div>
    </div>
  );
};

const TestListPlaceholder = ({
  hasTests,
  hasVisibleTests,
  pendingRun,
}: {
  hasTests: boolean;
  hasVisibleTests: boolean;
  pendingRun: boolean;
}) => {
  if (hasVisibleTests) {
    return null;
  }

  if (!hasTests && pendingRun) {
    return (
      <>
        <div className="w-full h-4" />
        <TestListItemSkeleton />
        <TestListItemSkeleton />
        <TestListItemSkeleton />
        <div className="px-3 py-6 text-center text-xs text-muted-foreground">
          Execution is still running — tests will appear shortly…
        </div>
      </>
    );
  }

  return (
    <div className="px-3 py-6 text-center text-xs text-muted-foreground">
      No tests match your filters
    </div>
  );
};

const Wrapper = ({
  children,
  foldedContent,
}: {
  children: ReactNode;
  foldedContent: ReactNode;
}) => {
  const { testListVisibility } = useViewProvider();
  function handleStateChange(state: SidePanelState) {
    if (state === 'folded') {
      testListVisibility.onFold();
    } else {
      testListVisibility.onUnfold();
    }
  }

  return (
    <TraceViewerSidePanel
      state={testListVisibility.isFolded ? 'folded' : 'open'}
      onStateChange={handleStateChange}
      children={children}
      foldedContent={foldedContent}
      title="Tests"
      closable={false}
    />
  );
};

function getLastAttempt(test: TestListItem): TestListItemAttempt | null {
  if (test.attempts.length === 0) {
    return null;
  }

  return test.attempts[test.attempts.length - 1];
}
