import type { VerdictResultStatus, VerdictType } from '@heal/front-core/ui';

import type { CodeLineAnnotation } from '../code-editor.types';

type AnnotationTone =
  | 'danger'
  | 'brand'
  | 'success'
  | 'warning'
  | 'info'
  | 'neutral';

export type AnnotationStyle = {
  /** Whole-line + margin background tint. */
  lineClass: string;
};

const STATUS_TONE: Record<VerdictResultStatus, AnnotationTone> = {
  passed: 'success',
  failed: 'danger',
  running: 'info',
  pending: 'neutral',
  skipped: 'neutral',
};

const VERDICT_TONE: Record<VerdictType, AnnotationTone> = {
  BUG: 'danger',
  UI_CHANGED: 'brand',
  HEAL_SYSTEM_ISSUE: 'danger',
  UNSTABLE_LOCATOR: 'danger',
  BROKEN_TEST_LOGIC: 'warning',
  NO_VERDICT: 'neutral',
};

const TONE_STYLE: Record<AnnotationTone, AnnotationStyle> = {
  danger: { lineClass: 'bg-danger-subtle' },
  brand: { lineClass: 'bg-brand-subtle' },
  success: { lineClass: 'bg-success-subtle' },
  warning: { lineClass: 'bg-warning-subtle' },
  info: { lineClass: 'bg-info-subtle' },
  neutral: { lineClass: '' },
};

const getTone = (annotation: CodeLineAnnotation): AnnotationTone => {
  if (annotation.verdictType) {
    return VERDICT_TONE[annotation.verdictType];
  }
  if (annotation.status === 'failed') {
    return STATUS_TONE[annotation.status];
  }

  return 'neutral';
};

export const resolveAnnotationStyle = (
  annotation: CodeLineAnnotation,
): AnnotationStyle => TONE_STYLE[getTone(annotation)];
