import { useMemo } from 'react';

import { flattenStatements } from '../../utils/flatten-statements';

import { DataProviderContext } from './data-provider.context';
import { DataProviderProps } from './data-provider.types';

export const DataProvider = ({
  children,
  testList,
  currentTest,
  loading = false,
  loadSourceContent,
  pendingRun = false,
}: DataProviderProps) => {
  const flatStatements = useMemo(
    () => (currentTest ? flattenStatements(currentTest.statements) : []),
    [currentTest],
  );

  const value = useMemo(
    () => ({
      testList,
      currentTest,
      flatStatements,
      loading,
      loadSourceContent,
      pendingRun,
    }),
    [
      testList,
      currentTest,
      flatStatements,
      loading,
      loadSourceContent,
      pendingRun,
    ],
  );

  return (
    <DataProviderContext.Provider value={value}>
      {children}
    </DataProviderContext.Provider>
  );
};
