import type * as Monaco from 'monaco-editor/esm/vs/editor/editor.api.js';

class NoopWorker implements Worker {
  onmessage: ((this: Worker, ev: MessageEvent) => unknown) | null = null;
  onmessageerror: ((this: Worker, ev: MessageEvent) => unknown) | null = null;
  onerror: ((this: AbstractWorker, ev: ErrorEvent) => unknown) | null = null;

  postMessage(): void {}
  terminate(): void {}
  addEventListener(): void {}
  removeEventListener(): void {}
  dispatchEvent(): boolean {
    return false;
  }
}

let bootstrapPromise: Promise<typeof Monaco> | null = null;

// Dynamic imports keep monaco-editor's side effects off the SSR path; nothing
// touches `self`/`window` until a browser caller resolves the promise.
export const bootstrapMonaco = (): Promise<typeof Monaco> => {
  if (bootstrapPromise) {
    return bootstrapPromise;
  }

  if (typeof window === 'undefined') {
    return Promise.reject(
      new Error('bootstrapMonaco can only be called in a browser environment'),
    );
  }

  globalThis.MonacoEnvironment = {
    getWorker: () => new NoopWorker() as unknown as Worker,
  };

  bootstrapPromise = (async () => {
    const monaco = await import('monaco-editor/esm/vs/editor/editor.api.js');
    const [, , , jsonContribution] = await Promise.all([
      import('monaco-editor/esm/vs/basic-languages/typescript/typescript.contribution.js'),
      import('monaco-editor/esm/vs/basic-languages/javascript/javascript.contribution.js'),
      import('monaco-editor/esm/vs/basic-languages/python/python.contribution.js'),
      import('monaco-editor/esm/vs/language/json/monaco.contribution.js'),
    ]);

    // JSON ships a language service that would otherwise reach for a worker
    // even in read-only mode (schema fetches, validation). Turn it all off so
    // the stub worker is never invoked. The `.d.ts` ships as `export {}` so
    // we type the runtime shape ourselves rather than rely on the module's
    // empty declarations.
    const { jsonDefaults } = jsonContribution as unknown as {
      jsonDefaults: {
        setDiagnosticsOptions: (options: {
          validate?: boolean;
          allowComments?: boolean;
          schemas?: readonly unknown[];
          enableSchemaRequest?: boolean;
        }) => void;
      };
    };
    jsonDefaults.setDiagnosticsOptions({
      validate: false,
      allowComments: true,
      schemas: [],
      enableSchemaRequest: false,
    });

    return monaco;
  })();

  return bootstrapPromise;
};

export type { Monaco };

/** The resolved monaco-editor API namespace returned by {@link bootstrapMonaco}. */
export type MonacoApi = typeof Monaco;
