// Shared HTTP plumbing for the standalone viewer's data layer. The SPA
// talks to the heal-playwright-tracer Node server; server contract lives in:
//   heal-playwright-tracer/src/infrastructure/local-viewer-adapter/local-viewer-server.ts

export const handle = async <T>(res: Response): Promise<T> => {
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  }

  return (await res.json()) as T;
};

/**
 * Resolves an API `path` against the configured base. In dev, point the
 * SPA at a standalone heal-tracer server via `VITE_TRACER_API_PATH`
 * (e.g. `http://localhost:7777`). When unset (the vendored production
 * bundle), the base is '' so requests stay same-origin.
 */
export const baseApiPath = (path: string): string =>
  `${import.meta.env.VITE_TRACER_API_PATH ?? ''}${path}`;
