import { ComponentPropsWithoutRef, useEffect, useState } from 'react';

import { VerdictResultIndicator } from '../../../../../../core/ui/features/verdict-result-indicator/verdict-result-indicator';
import { VerdictType } from '../../../../types/verdict';

import { VerdictFormResult } from './verdict-form-result';

const CYCLE_MS = 2000;
const CARD_HEIGHT_PX = 50;
const CARD_GAP_PX = 12;
const SLOT_PX = CARD_HEIGHT_PX + CARD_GAP_PX;
const ACTIVE_POSITION = 1;
const INACTIVE_INSET_PX = 18;

const CARDS: { key: string; verdictType: VerdictType }[] = [
  { key: 'bug', verdictType: 'BUG' },
  { key: 'ui-changed', verdictType: 'UI_CHANGED' },
  { key: 'broken-test-logic', verdictType: 'BROKEN_TEST_LOGIC' },
];

const STACK_HEIGHT_PX = SLOT_PX * CARDS.length - CARD_GAP_PX;

const BASE_CARD_CLASS =
  'absolute overflow-hidden rounded-lg border transition-all duration-700 ease-[cubic-bezier(0.4,0,0.2,1)]';
const ACTIVE_CARD_CLASS =
  'border-primary/40 bg-background shadow-[0_8px_30px_-8px_rgba(99,102,241,0.35)] ring-1 ring-primary/20';
const INACTIVE_CARD_CLASS = 'border-border bg-muted/20 opacity-30 blur-[0.5px]';

const getPosition = (index: number, cycle: number): number =>
  (((index - cycle) % CARDS.length) + CARDS.length) % CARDS.length;

type ResultCardProps = {
  position: number;
  verdictType: VerdictType;
  failureMessage?: string;
};

const ResultCard = ({
  position,
  verdictType,
  failureMessage,
}: ResultCardProps) => {
  const isActive = position === ACTIVE_POSITION;
  const className = `${BASE_CARD_CLASS} ${isActive ? ACTIVE_CARD_CLASS : INACTIVE_CARD_CLASS}`;

  return (
    <div
      className={className}
      style={{
        top: position * SLOT_PX,
        left: isActive ? 0 : INACTIVE_INSET_PX,
        right: isActive ? 0 : INACTIVE_INSET_PX,
        height: CARD_HEIGHT_PX,
      }}
      aria-hidden={!isActive}
    >
      <div className="flex h-full items-center gap-2 px-4 text-sm leading-relaxed text-foreground">
        <VerdictResultIndicator
          verdictType={verdictType}
          variant="iconOnly"
          size="md"
          showTooltip={false}
        />
        <p className="line-clamp-1">
          {failureMessage ??
            'Looking through the run to identify the root cause'}
        </p>
      </div>
    </div>
  );
};

type VerdictFormLoadingProps = {
  formResult: ComponentPropsWithoutRef<typeof VerdictFormResult>;
};

export const VerdictFormLoading = ({ formResult }: VerdictFormLoadingProps) => {
  const [cycle, setCycle] = useState(0);

  useEffect(() => {
    const tick = setInterval(() => {
      setCycle((c) => c + 1);
    }, CYCLE_MS);

    return () => clearInterval(tick);
  }, []);

  return (
    <div
      className="flex h-full flex-col items-center justify-center gap-8 px-4"
      role="status"
      aria-live="polite"
      aria-label="Heal is analysing this failure"
    >
      <div className="flex flex-col items-center gap-1">
        <span className="text-sm font-medium text-foreground">
          Heal is analysing this failure
        </span>
        <span className="text-xs text-muted-foreground">
          Looking through the run to identify the root cause
        </span>
      </div>
      <div
        className="relative w-full max-w-[520px]"
        style={{ height: STACK_HEIGHT_PX }}
      >
        {CARDS.map((card, index) => (
          <ResultCard
            key={card.key}
            position={getPosition(index, cycle)}
            verdictType={card.verdictType}
            failureMessage={formResult.failure?.message}
          />
        ))}
      </div>
    </div>
  );
};
