import { ChevronLeftIcon, ChevronRightIcon, XIcon } from 'lucide-react';
import type { ReactNode } from 'react';

import { cn } from '../../../../lib/utils';
import { Button } from '../../../components/button/button';
import type { ViewPane } from '../view/trace-viewer-view';

export type SidePanelState = 'open' | 'closed' | 'folded';

const FOLDED_SIZE = 40;

export interface TraceViewerSidePanelClassNames {
  /** Outermost wrapper */
  root?: string;
  /** The panel itself (open state) */
  panel?: string;
  /** Header bar inside the panel (open state) */
  header?: string;
  /** Scrollable panel body (open state) */
  panelContent?: string;
  /** Folded strip (folded state) */
  folded?: string;
}

export interface TraceViewerSidePanelProps {
  /** Current panel state */
  state: SidePanelState;
  /** Callback when the user toggles state */
  onStateChange: (state: SidePanelState) => void;
  /** Panel content (rendered inside the panel when open) */
  children?: ReactNode;
  /** Header title for the panel */
  title?: ReactNode;
  /** Extra actions rendered in the header before fold/close buttons */
  actions?: ReactNode;
  /** Custom content shown in the folded strip */
  foldedContent?: ReactNode;
  /** Whether the panel can be fully closed. Default: true */
  closable?: boolean;
  /** Override classNames for internal elements */
  classNames?: TraceViewerSidePanelClassNames;
}

/**
 * Returns `ViewPane` size/visibility props derived from the panel state.
 * Spread the result into the pane config passed to `TraceViewerView`.
 *
 * @example
 * ```tsx
 * <TraceViewerView
 *   panes={[
 *     {
 *       id: 'side-panel',
 *       content: <TraceViewerSidePanel ...><PanelContent /></TraceViewerSidePanel>,
 *       ...getSidePanelPaneConfig(panelState, { minSize: 200, maxSize: 400, preferredSize: 280 }),
 *     },
 *     { id: 'main', content: <MainContent /> },
 *   ]}
 * />
 * ```
 */
export const getSidePanelPaneConfig = (
  state: SidePanelState,
  options?: {
    minSize?: number;
    maxSize?: number;
    preferredSize?: number | string;
    foldedSize?: number;
  },
): Pick<ViewPane, 'visible' | 'minSize' | 'maxSize' | 'preferredSize'> => {
  const foldedSize = options?.foldedSize ?? FOLDED_SIZE;

  if (state === 'closed') {
    return { visible: false };
  }

  if (state === 'folded') {
    return {
      visible: true,
      minSize: foldedSize,
      maxSize: foldedSize,
      preferredSize: foldedSize,
    };
  }

  return {
    visible: true,
    minSize: options?.minSize,
    maxSize: options?.maxSize,
    preferredSize: options?.preferredSize,
  };
};

export const TraceViewerSidePanel = ({
  state,
  onStateChange,
  children,
  title,
  actions,
  foldedContent,
  closable = true,
  classNames,
}: TraceViewerSidePanelProps) => {
  const handleFold = () => onStateChange('folded');
  const handleClose = () => onStateChange('closed');
  const handleOpen = () => onStateChange('open');

  if (state === 'folded') {
    return (
      <div
        className={cn(
          'flex h-full w-full flex-col items-center bg-surface py-2',
          classNames?.root,
          classNames?.folded,
        )}
      >
        <Button
          variant="ghost"
          size="iconSm"
          tooltip="Expand panel"
          onClick={handleOpen}
        >
          <ChevronRightIcon className="size-4" />
        </Button>
        {foldedContent}
      </div>
    );
  }

  return (
    <div
      className={cn(
        'flex h-full w-full flex-col overflow-hidden bg-surface',
        classNames?.root,
        classNames?.panel,
      )}
    >
      <div
        className={cn(
          'flex shrink-0 items-center justify-between px-3 py-2',
          classNames?.header,
        )}
      >
        <span className="text-sm font-medium">{title}</span>
        <div className="flex items-center gap-1">
          {actions}
          <Button
            variant="ghost"
            size="iconSm"
            tooltip="Fold panel"
            onClick={handleFold}
          >
            <ChevronLeftIcon className="size-3.5" />
          </Button>
          {closable && (
            <Button
              variant="ghost"
              size="iconSm"
              tooltip="Close panel"
              onClick={handleClose}
            >
              <XIcon className="size-3.5" />
            </Button>
          )}
        </div>
      </div>

      <div className={cn('flex-1 overflow-auto', classNames?.panelContent)}>
        {children}
      </div>
    </div>
  );
};
