import type { CodeEditorFile, CodeEditorLanguage } from '../code-editor.types';

const LANGUAGE_BY_EXTENSION: Record<string, CodeEditorLanguage> = {
  ts: 'typescript',
  tsx: 'typescript',
  mts: 'typescript',
  cts: 'typescript',
  js: 'javascript',
  jsx: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  py: 'python',
  pyi: 'python',
  json: 'json',
};

export const resolveLanguage = (file: CodeEditorFile): string => {
  if (file.language) {
    return file.language;
  }

  const extension = file.path.split('.').pop()?.toLowerCase() ?? '';

  return LANGUAGE_BY_EXTENSION[extension] ?? 'plaintext';
};

export const getBaseName = (path: string): string =>
  path.split('/').pop() || path;
