import { TestListItemAttempt } from '../types/test-list';

/***
 * Copyright (c) Myia 2023-2026 - All Rights Reserved
 */
export const getMajorityAttempt = (attempts: TestListItemAttempt[]) => {
  const majorityAttempt = attempts.find((a) => isMajorityAttempt(a));

  if (!majorityAttempt) {
    return attempts.at(-1);
  }

  return majorityAttempt;
};

export const isMajorityAttempt = (attempt: TestListItemAttempt) => {
  if (attempt.finalVerdict || attempt.triagedVerdict) {
    return false;
  }

  return attempt.selectedForFailure;
};
