import { ChevronRightIcon } from 'lucide-react';
import { Fragment, type ReactNode } from 'react';

import { cn } from '../../../../../lib/utils';

export interface BreadcrumbItem {
  /** Display label */
  label: ReactNode;
  /** Click handler (makes it a link) */
  onClick?: () => void;
  /** Optional icon before the label */
  icon?: ReactNode;
}

export interface HeaderBreadcrumbClassNames {
  /** Root wrapper */
  root?: string;
  /** Individual breadcrumb item */
  item?: string;
  /** Separator icon */
  separator?: string;
}

export interface HeaderBreadcrumbProps {
  /** Breadcrumb items in order */
  items: BreadcrumbItem[];
  /** Style overrides */
  classNames?: HeaderBreadcrumbClassNames;
}

export const HeaderBreadcrumb = ({
  items,
  classNames,
}: HeaderBreadcrumbProps) => {
  if (items.length === 0) {
    return null;
  }

  return (
    <nav
      className={cn(
        'flex min-w-0 items-center gap-1 text-sm',
        classNames?.root,
      )}
    >
      {items.map((item, index) => {
        const isLast = index === items.length - 1;

        return (
          <Fragment key={index}>
            {item.onClick ? (
              <button
                type="button"
                onClick={item.onClick}
                className={cn(
                  'flex shrink-0 items-center gap-1.5 transition-colors',
                  isLast
                    ? 'font-medium text-foreground'
                    : 'text-muted-foreground hover:text-foreground',
                  classNames?.item,
                )}
              >
                {item.icon}
                <span className="max-w-[400px] truncate">{item.label}</span>
              </button>
            ) : (
              <span
                className={cn(
                  'flex shrink-0 items-center gap-1.5',
                  isLast
                    ? 'font-medium text-foreground'
                    : 'text-muted-foreground',
                  classNames?.item,
                )}
              >
                {item.icon}
                <span className="max-w-[400px] truncate">{item.label}</span>
              </span>
            )}

            {!isLast && (
              <ChevronRightIcon
                className={cn(
                  'size-3.5 shrink-0 text-muted-foreground/40',
                  classNames?.separator,
                )}
              />
            )}
          </Fragment>
        );
      })}
    </nav>
  );
};
