import { cn } from '@heal/front-core/lib/utils';
import type { ReactNode } from 'react';

interface EmptyStateProps {
  icon: ReactNode;
  message: string;
  size?: 'default' | 'compact';
}

export const EmptyState = ({
  icon,
  message,
  size = 'default',
}: EmptyStateProps) => {
  const messageClass = size === 'compact' ? 'text-xs' : 'text-sm';

  return (
    <div className="flex h-full flex-col items-center justify-center gap-3 text-muted-foreground">
      {icon}
      <p className={cn(messageClass, 'w-[95%] mx-auto text-center')}>
        {message}
      </p>
    </div>
  );
};
