import { createContext, useContext } from 'react';

import type { ViewLayout } from '../../../../core/ui/features/trace-viewer';

export interface LayoutContextValue {
  getDefaultSizes: (paneIds: string[]) => number[] | undefined;
  onLayoutChange: (layout: ViewLayout) => void;
}

export const LayoutContext = createContext<LayoutContextValue | null>(null);

export const useLayoutContext = (): LayoutContextValue => {
  const ctx = useContext(LayoutContext);
  if (!ctx) {
    throw new Error('Row/Col must be used inside a <ModeLayout>');
  }

  return ctx;
};
