import { useContext } from 'react';

import { TriageVerdictFormProviderContext } from './triage-verdict-form-provider.context';

export const useTriageVerdictForm = () => {
  const context = useContext(TriageVerdictFormProviderContext);
  if (!context) {
    throw new Error(
      'useTriageVerdictForm must be used within a TriageVerdictFormProvider',
    );
  }

  return context;
};
