import type { CodeEditorFile } from '../code-editor.types';

const QUOTES = ['"', "'", '`'];

const CANDIDATE_EXTENSIONS = [
  'ts',
  'tsx',
  'mts',
  'cts',
  'js',
  'jsx',
  'mjs',
  'cjs',
  'py',
  'json',
];

const INDEX_FILES = ['index.ts', 'index.tsx', 'index.js'];

/**
 * Returns the contents of the quoted string spanning `column` (1-based) in
 * `lineText`, or `null` when the column is not inside a quoted string. Used to
 * anchor "go to file" on the import specifier under the cursor.
 */
export const getQuotedStringAt = (
  lineText: string,
  column: number,
): string | null => {
  const index = column - 1;

  for (const quote of QUOTES) {
    let searchFrom = 0;

    while (searchFrom <= lineText.length) {
      const open = lineText.indexOf(quote, searchFrom);
      if (open === -1) {
        break;
      }

      const close = lineText.indexOf(quote, open + 1);
      if (close === -1) {
        break;
      }

      if (index >= open && index <= close) {
        return lineText.slice(open + 1, close);
      }

      searchFrom = close + 1;
    }
  }

  return null;
};

const getDirName = (path: string): string => {
  const lastSlash = path.lastIndexOf('/');
  if (lastSlash === -1) {
    return '';
  }

  return path.slice(0, lastSlash);
};

const normalizeSegments = (segments: string[]): string[] => {
  const result: string[] = [];

  for (const segment of segments) {
    if (segment === '' || segment === '.') {
      continue;
    }
    if (segment === '..') {
      result.pop();
      continue;
    }
    result.push(segment);
  }

  return result;
};

const joinPath = (dir: string, specifier: string): string => {
  const segments = [...dir.split('/'), ...specifier.split('/')];

  return normalizeSegments(segments).join('/');
};

/**
 * Resolves a module `specifier` (relative to `fromPath`'s directory) to a file
 * `path` within `files`, trying common source/JSON extensions and `index`
 * files. Returns `null` for bare or unresolved specifiers.
 */
export const resolveImportTarget = (
  fromPath: string,
  specifier: string,
  files: CodeEditorFile[],
): string | null => {
  const filePaths = new Set(files.map((file) => file.path));

  if (filePaths.has(specifier)) {
    return specifier;
  }

  const base = joinPath(getDirName(fromPath), specifier);

  const candidates = [
    base,
    ...CANDIDATE_EXTENSIONS.map((extension) => `${base}.${extension}`),
    ...INDEX_FILES.map((indexFile) => `${base}/${indexFile}`),
  ];

  return candidates.find((candidate) => filePaths.has(candidate)) ?? null;
};

const IMPORT_STATEMENT =
  /import\s+(?:type\s+)?([^;]*?)\s+from\s+['"]([^'"]+)['"]/g;

// Local binding names introduced by one import clause, e.g.
// `def, { a, b as c }` → ['def', 'a', 'c']; `* as ns` → ['ns'].
const getClauseBindings = (clause: string): string[] => {
  const names: string[] = [];

  const named = clause.match(/\{([^}]*)\}/);
  if (named) {
    for (const part of named[1].split(',')) {
      const token = part.trim().replace(/^type\s+/, '');
      if (!token) {
        continue;
      }
      const aliased = token.match(/\sas\s+(\w+)/);
      names.push(aliased ? aliased[1] : token);
    }
  }

  const namespace = clause.match(/\*\s+as\s+(\w+)/);
  if (namespace) {
    names.push(namespace[1]);
  }

  const defaultBinding = clause.split('{')[0].split(',')[0].trim();
  if (defaultBinding && /^\w+$/.test(defaultBinding)) {
    names.push(defaultBinding);
  }

  return names;
};

/**
 * Maps each locally-imported name to the module specifier it came from, by
 * scanning the file's `import … from '…'` statements. Lets "go to file" work
 * when the cursor is on an imported symbol (e.g. a function call) rather than
 * on the import path itself.
 */
export const getImportBindings = (text: string): Map<string, string> => {
  const bindings = new Map<string, string>();

  for (const match of text.matchAll(IMPORT_STATEMENT)) {
    const [, clause, specifier] = match;
    for (const name of getClauseBindings(clause)) {
      if (!bindings.has(name)) {
        bindings.set(name, specifier);
      }
    }
  }

  return bindings;
};
