import { useContext } from 'react';

import { AnalyzeSlotProviderContext } from './analyze-slot-provider.context';

/**
 * Returns the host-supplied analyze slot, or `null` when no host wired
 * one in. Unlike most providers in this package, this hook does NOT
 * throw when the provider is absent — the analyze slot is opt-in.
 */
export const useAnalyzeSlot = () => useContext(AnalyzeSlotProviderContext);
