import { ReactNode } from 'react';

import { cn } from '../../../lib/utils';

export type BadgeVariant =
  | 'important'
  | 'pass'
  | 'warn'
  | 'fail'
  | 'neutral'
  | 'failOutline'
  | 'passOutline'
  | 'danger'
  | 'warning'
  | 'success'
  | 'info'
  | 'brand';
export interface BadgeProps {
  variant: BadgeVariant;
  children: ReactNode;
  /** When true, no dot is shown and padding is reduced. Use for compact status labels (e.g. cache hit). */
  compact?: boolean;
  /** When true (with compact), even smaller text and padding. Use for inline step/test CCA badge. */
  tiny?: boolean;
  dot?: boolean;
}

const badgeStyles: Record<BadgeVariant, { container: string; dot: string }> = {
  important: {
    container: 'bg-brand-subtle text-brand-solid',
    dot: 'bg-brand-solid',
  },
  pass: {
    container:
      'border border-success-subtle-border bg-success-subtle text-success-solid',
    dot: 'bg-success-solid',
  },
  warn: {
    container:
      'border border-warning-subtle-border bg-warning-subtle text-warning-solid',
    dot: 'bg-warning-subtle',
  },
  fail: {
    container:
      'border border-danger-subtle-border bg-danger-subtle text-danger-solid',
    dot: 'bg-danger-solid',
  },
  neutral: {
    container: 'border border-border bg-surface text-muted-foreground',
    dot: 'bg-muted-foreground',
  },
  failOutline: {
    container:
      'border border-danger-subtle-border bg-transparent text-danger-solid',
    dot: 'bg-danger-solid',
  },
  passOutline: {
    container:
      'border border-success-subtle-border bg-transparent text-success-solid',
    dot: 'bg-success-solid',
  },
  danger: {
    container:
      'border border-danger-subtle-border bg-transparent text-danger-solid',
    dot: 'bg-danger-solid',
  },
  warning: {
    container:
      'border border-warning-subtle-border bg-transparent text-warning-solid',
    dot: 'bg-warning-solid',
  },
  success: {
    container:
      'border border-success-subtle-border bg-transparent text-success-solid',
    dot: 'bg-success-solid',
  },
  info: {
    container:
      'border border-info-subtle-border bg-transparent text-info-solid',
    dot: 'bg-info-solid',
  },
  brand: {
    container:
      'border border-brand-subtle-border bg-transparent text-brand-solid',
    dot: 'bg-brand-solid',
  },
};

const compactBadgeStyles: Record<BadgeVariant, string> = {
  important: 'bg-brand-solid text-brand-solid-contrast',
  pass: 'bg-success-solid text-success-solid-contrast',
  warn: 'bg-warning-solid text-warning-solid-contrast',
  fail: 'bg-danger-solid text-danger-solid-contrast',
  neutral: 'border-border bg-muted text-foreground',
  failOutline:
    'border border-danger-subtle-border bg-transparent text-danger-solid',
  passOutline:
    'border border-success-subtle-border bg-transparent text-success-solid',
  danger: 'border border-danger-subtle-border bg-transparent text-danger-solid',
  warning:
    'border border-warning-subtle-border bg-transparent text-warning-solid',
  success:
    'border border-success-subtle-border bg-transparent text-success-solid',
  info: 'border border-info-subtle-border bg-transparent text-info-solid',
  brand: 'border border-brand-subtle-border bg-transparent text-brand-solid',
};

export const Badge = ({
  variant,
  children,
  compact = false,
  tiny = false,
  dot = true,
}: BadgeProps) => {
  const styles = badgeStyles[variant];

  return (
    <div
      className={cn(
        'inline-flex w-fit shrink-0 items-center',
        tiny &&
          compact &&
          'rounded border-0 bg-transparent px-0.5 py-0 text-[8px] font-medium leading-none',
        compact &&
          !tiny &&
          'rounded-md gap-1 px-1.5 py-0.5 text-xs font-medium',
        !compact && 'rounded-full gap-2 px-3 py-1 text-xs',
        compact && compactBadgeStyles[variant],
        !compact && styles.container,
      )}
    >
      {!compact && dot && (
        <span className={cn('h-1.5 w-1.5 shrink-0 rounded-full', styles.dot)} />
      )}
      {children}
    </div>
  );
};
