// ─── heal analyze ─────────────────────────────────────────────────────
// POST /api/.../analyze spawns `heal analyze` as a subprocess. The
// subsequent polled GET reads the per-test `analyze.ndjson` and
// projects it into the discriminated union `AnalyzeRunStatus`.
// A 404 from the GET means no analyze has been run yet for the test.

import { baseApiPath } from '../http';
import type { AnalyzeRunStartResponse, AnalyzeRunStatus } from '../types';

/** Query-key factory ("tags") for the analyze domain. */
export const analyzeKeys = {
  all: ['analyze'] as const,
  status: (executionId: string, playwrightTestId: string, attempt: number) =>
    [
      ...analyzeKeys.all,
      'status',
      executionId,
      playwrightTestId,
      attempt,
    ] as const,
};

export const getAnalyzeStatus = async (
  executionId: string,
  playwrightTestId: string,
  attempt: number,
): Promise<AnalyzeRunStatus | null> => {
  const res = await fetch(
    baseApiPath(
      `/api/executions/${encodeURIComponent(executionId)}/tests/${encodeURIComponent(playwrightTestId)}/${attempt}/analyze`,
    ),
  );
  if (res.status === 404) {
    return null;
  }
  if (!res.ok) {
    throw new Error(`getAnalyzeStatus failed: ${res.status}`);
  }

  return (await res.json()) as AnalyzeRunStatus;
};

export const startAnalyze = async (
  executionId: string,
  playwrightTestId: string,
  attempt: number,
): Promise<AnalyzeRunStartResponse> => {
  const res = await fetch(
    baseApiPath(
      `/api/executions/${encodeURIComponent(executionId)}/tests/${encodeURIComponent(playwrightTestId)}/${attempt}/analyze`,
    ),
    { method: 'POST' },
  );
  if (!res.ok) {
    throw new Error(`startAnalyze failed: ${res.status}`);
  }

  return (await res.json()) as AnalyzeRunStartResponse;
};
