import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';

import { CreateTriageVerdictForm } from './_components/create-triage-verdict-form';

export const CREATE_TRIAGE_VERDICT_FORM_VIEW_ID = 'create-triage-verdict-form';

export const CreateTriageVerdictFormView = () => {
  const capabilities = useCapabilities();

  if (!capabilities.canWriteTriagedVerdict) {
    return null;
  }

  return (
    <div className="flex h-full min-h-0 flex-col overflow-auto px-4 py-4">
      <CreateTriageVerdictForm />
    </div>
  );
};
