import type { ViewPane } from '../view/trace-viewer-view';

import {
  getSidePanelPaneConfig,
  type SidePanelState,
} from './trace-viewer-side-panel';

const PANEL_OPTIONS = {
  minSize: 200,
  maxSize: 400,
  preferredSize: 280,
};

/**
 * Returns `ViewPane` size/visibility props for the test-list side panel.
 * Spread the result into the pane config passed to `TraceViewerView`.
 *
 * @example
 * ```tsx
 * const testListPaneConfig = useTestListPaneConfig(isFolded);
 *
 * <TraceViewerView
 *   panes={[
 *     { id: 'test-list', content: <TestListView />, ...testListPaneConfig },
 *     { id: 'test-content', content: <TestContentView /> },
 *   ]}
 * />
 * ```
 */
export const useTestListPaneConfig = (
  isFolded: boolean,
): Pick<ViewPane, 'visible' | 'minSize' | 'maxSize' | 'preferredSize'> => {
  const getState = (): SidePanelState => {
    if (isFolded) {
      return 'folded';
    }

    return 'open';
  };

  return getSidePanelPaneConfig(getState(), PANEL_OPTIONS);
};
