import { useMutation, useQueryClient } from '@tanstack/react-query';

import type { AnalyzeRunStatus } from '../../types';
import { analyzeKeys, startAnalyze } from '../analyze.api';

interface StartAnalyzeVariables {
  executionId: string;
  playwrightTestId: string;
  attempt: number;
}

/**
 * Triggers `heal analyze` for a single attempt. On `mutate` it optimistically
 * seeds the status query with `{ status: 'running' }` so the verdict pane
 * shows the spinner immediately and polling has a non-terminal state to latch
 * onto. `onSettled` invalidates the status key so the next poll re-syncs.
 */
export const useStartAnalyzeMutation = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({
      executionId,
      playwrightTestId,
      attempt,
    }: StartAnalyzeVariables) =>
      startAnalyze(executionId, playwrightTestId, attempt),
    onMutate: ({ executionId, playwrightTestId, attempt }) => {
      queryClient.setQueryData<AnalyzeRunStatus | null>(
        analyzeKeys.status(executionId, playwrightTestId, attempt),
        { status: 'running' },
      );
    },
    onSettled: (_data, _error, { executionId, playwrightTestId, attempt }) => {
      queryClient.invalidateQueries({
        queryKey: analyzeKeys.status(executionId, playwrightTestId, attempt),
      });
    },
  });
};
