import { useCallback, useMemo, useState } from 'react';

import { TriageVerdictFormProviderContext } from './triage-verdict-form-provider.context';
import {
  TriageVerdictFormOpenInput,
  TriageVerdictFormProviderProps,
  TriageVerdictFormState,
} from './triage-verdict-form-provider.types';

const CLOSED_STATE: TriageVerdictFormState = { isOpen: false };

export const TriageVerdictFormProvider = ({
  children,
}: TriageVerdictFormProviderProps) => {
  const [state, setState] = useState<TriageVerdictFormState>(CLOSED_STATE);

  const open = useCallback((input?: TriageVerdictFormOpenInput) => {
    setState({
      isOpen: true,
      selectedFailingStatementIndex: input?.selectedFailingStatementIndex,
      selectedType: input?.selectedType,
    });
  }, []);

  const close = useCallback(() => {
    setState(CLOSED_STATE);
  }, []);

  const value = useMemo(() => ({ state, open, close }), [state, open, close]);

  return (
    <TriageVerdictFormProviderContext.Provider value={value}>
      {children}
    </TriageVerdictFormProviderContext.Provider>
  );
};
