import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react';

import {
  CodeNavigationContext,
  type CodeNavigationTarget,
} from './code-navigation-provider.context';

export const CodeNavigationProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const [target, setTarget] = useState<CodeNavigationTarget | null>(null);
  const nonceRef = useRef(0);

  const goToCode = useCallback((path: string, line: number) => {
    nonceRef.current += 1;
    setTarget({ path, line, nonce: nonceRef.current });
  }, []);

  const value = useMemo(() => ({ target, goToCode }), [target, goToCode]);

  return (
    <CodeNavigationContext.Provider value={value}>
      {children}
    </CodeNavigationContext.Provider>
  );
};
