import { useMemo } from 'react';

import { AnalyzeSlotProviderContext } from './analyze-slot-provider.context';
import type { AnalyzeSlotProviderProps } from './analyze-slot-provider.types';

export const AnalyzeSlotProvider = ({
  children,
  analyzeSlot,
}: AnalyzeSlotProviderProps) => {
  const value = useMemo(() => analyzeSlot ?? null, [analyzeSlot]);

  return (
    <AnalyzeSlotProviderContext.Provider value={value}>
      {children}
    </AnalyzeSlotProviderContext.Provider>
  );
};
