import { QueryClient } from '@tanstack/react-query';

/**
 * QueryClient for the standalone viewer. Mirrors the apps/web defaults
 * (see apps/web/src/shared/contexts/QueryProvider.tsx):
 *  - staleTime 5 min, gcTime 10 min
 *  - no refetch on window focus
 *  - mutations never retry
 * The tracer server is local, so a single query retry is plenty.
 */
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5,
      gcTime: 1000 * 60 * 10,
      retry: 1,
      refetchOnWindowFocus: false,
      refetchOnReconnect: true,
      refetchOnMount: true,
    },
    mutations: {
      retry: 0,
    },
  },
});
