import { useQuery } from '@tanstack/react-query';

import { getTrace, tracesKeys } from '../traces.api';

interface UseTraceQueryParams {
  executionId?: string;
  playwrightTestId?: string;
  attempt?: number;
}

export const useTraceQuery = ({
  executionId,
  playwrightTestId,
  attempt,
}: UseTraceQueryParams) =>
  useQuery({
    queryKey: tracesKeys.detail(
      executionId ?? '',
      playwrightTestId ?? '',
      attempt ?? 0,
    ),
    queryFn: () =>
      getTrace(
        executionId as string,
        playwrightTestId as string,
        attempt as number,
      ),
    enabled: Boolean(executionId && playwrightTestId && attempt),
  });
