import { cn } from '../../../../lib/utils';
import { CustomTooltip } from '../../../components/custom-tooltip/custom-tooltip';
import {
  VerdictResultIndicator,
  type VerdictResultStatus,
  type VerdictType,
} from '../../verdict-result-indicator/verdict-result-indicator';

export interface TraceViewerTestListItemClassNames {
  /** Root wrapper */
  root?: string;
  /** Icon area */
  indicator?: string;
  /** Label text */
  label?: string;
  /** Duration text */
  duration?: string;
}

export interface TraceViewerTestListItemProps {
  /** Test name */
  label: string;
  /** Test status */
  status: VerdictResultStatus;
  /** Verdict type (if available) */
  verdictType?: VerdictType;
  /** Duration text (e.g. "23.5s") */
  duration?: string;
  /** Whether this item is selected */
  selected?: boolean;
  /** Whether the list is in folded mode (icon + tooltip only) */
  folded?: boolean;
  /** Click handler */
  onClick?: () => void;
  /** Style overrides */
  classNames?: TraceViewerTestListItemClassNames;
}

export const TraceViewerTestListItem = ({
  label,
  status,
  verdictType,
  duration,
  selected = false,
  folded = false,
  onClick,
  classNames,
}: TraceViewerTestListItemProps) => {
  const icon = (
    <VerdictResultIndicator
      status={status}
      verdictType={verdictType}
      variant="iconOnly"
      size="md"
      showTooltip={!folded}
    />
  );

  if (folded) {
    return (
      <CustomTooltip content={label} enabled>
        <button
          type="button"
          onClick={onClick}
          className={cn(
            'flex items-center justify-center rounded-md p-2 transition-colors',
            selected ? 'bg-muted' : 'hover:bg-muted/50',
            onClick && 'cursor-pointer',
            classNames?.root,
          )}
        >
          {icon}
        </button>
      </CustomTooltip>
    );
  }

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'flex w-full items-center gap-2.5 rounded-md px-3 py-2 text-left text-sm transition-colors',
        selected ? 'bg-muted' : 'hover:bg-muted/50',
        onClick && 'cursor-pointer',
        classNames?.root,
      )}
    >
      <div
        className={cn(
          'shrink-0 flex items-center justify-center',
          classNames?.indicator,
        )}
      >
        {icon}
      </div>

      <span
        className={cn(
          'min-w-0 flex-1 truncate',
          selected ? 'font-medium text-foreground' : 'text-muted-foreground',
          classNames?.label,
        )}
      >
        {label}
      </span>

      {duration && (
        <span
          className={cn(
            'shrink-0 text-xs tabular-nums text-muted-foreground/60',
            classNames?.duration,
          )}
        >
          {duration}
        </span>
      )}
    </button>
  );
};
