import { cn } from '@heal/front-core/lib/utils';
import {
  Button,
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  Popover,
  PopoverContent,
  PopoverTrigger,
  Tabs,
  TabsList,
  TabsTrigger,
} from '@heal/front-core/ui';
import { CircleNotchIcon } from '@phosphor-icons/react';
import { CaretSortIcon } from '@radix-ui/react-icons';
import { useState } from 'react';

import { ExecutionDropdownItem } from './execution-dropdown-item';
import type { ExecutionItem } from './types';

interface ExecutionDropdownProps {
  currentKey: string;
  items: ExecutionItem[];
  handleSwitch: (key: string) => void;
  label: string;
  popOverWidth?: string;
  selectedDisplayValue?: string;
  hasMore?: boolean;
  isLoadingMore?: boolean;
  onLoadMore?: () => void;
  filterMode?: 'all' | 'mine';
  onFilterModeChange?: (mode: 'all' | 'mine') => void;
}

export const ExecutionDropdown = ({
  currentKey,
  items,
  handleSwitch,
  label,
  popOverWidth,
  selectedDisplayValue,
  hasMore,
  isLoadingMore,
  onLoadMore,
  filterMode,
  onFilterModeChange,
}: ExecutionDropdownProps) => {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          role="combobox"
          aria-expanded={open}
          aria-label={`Select a ${label}`}
          className={cn(
            'min-w-0 justify-between gap-1.5 overflow-hidden text-body',
            'bg-transparent border-transparent hover:bg-neutral-200 dark:hover:bg-muted',
            selectedDisplayValue ? 'px-1.5' : 'w-[200px] px-1.5',
          )}
        >
          {selectedDisplayValue ? (
            <>
              <span
                className="min-w-0 truncate font-medium! text-body"
                title={selectedDisplayValue}
              >
                {selectedDisplayValue}
              </span>
              <CaretSortIcon className="size-4 shrink-0 opacity-60" />
            </>
          ) : (
            <>
              <span className="min-w-0 truncate">Select a {label}</span>
              <CaretSortIcon className="ml-auto size-4 shrink-0 opacity-60" />
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className={cn(popOverWidth ?? 'w-[200px]', 'p-0')}
      >
        <Command>
          <CommandList>
            <CommandInput placeholder={`Search ${label}`} />
            {onFilterModeChange && (
              <div className="border-b px-2 py-1.5">
                <Tabs
                  value={filterMode ?? 'all'}
                  onValueChange={(v) => onFilterModeChange(v as 'all' | 'mine')}
                >
                  <TabsList className="w-full h-6">
                    <TabsTrigger
                      value="all"
                      className="flex-1 text-xs h-5 cursor-pointer"
                    >
                      All
                    </TabsTrigger>
                    <TabsTrigger
                      value="mine"
                      className="flex-1 text-xs h-5 cursor-pointer"
                    >
                      Mine
                    </TabsTrigger>
                  </TabsList>
                </Tabs>
              </div>
            )}
            <CommandEmpty>No {label} found.</CommandEmpty>
            <CommandGroup>
              {items.map((item, index) => (
                <ExecutionDropdownItem
                  key={`${item.key}-${index}`}
                  index={index}
                  item={item}
                  isSelected={currentKey === item.key}
                  onSelect={() => {
                    handleSwitch(item.key);
                    setOpen(false);
                  }}
                />
              ))}
              {hasMore && (
                <CommandItem
                  onSelect={() => {
                    if (!isLoadingMore) onLoadMore?.();
                  }}
                  className="flex items-center justify-center gap-1.5 py-2 text-xs text-muted-foreground"
                  disabled={isLoadingMore}
                >
                  {isLoadingMore ? (
                    <>
                      <CircleNotchIcon
                        size={12}
                        className="animate-spin"
                        aria-hidden
                      />
                      <span>Loading…</span>
                    </>
                  ) : (
                    <span>Load more</span>
                  )}
                </CommandItem>
              )}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};
