import type {
  VideoControllerActions,
  VideoControllerState,
} from '@heal/front-core/ui';
import { useContext } from 'react';

import { VideoProviderContext } from './video-provider.context';

export const useVideoProvider = () => {
  const context = useContext(VideoProviderContext);
  if (!context) {
    throw new Error('useVideoProvider must be used within a VideoProvider');
  }

  return context;
};

/** Shortcut to the video controller's reactive state slice. */
export const useVideoState = (): VideoControllerState =>
  useVideoProvider().controller.state;

/** Shortcut to the video controller's stable action set. */
export const useVideoActions = (): VideoControllerActions =>
  useVideoProvider().controller.actions;
