import { cn } from '@heal/front-core/lib/utils';

import type { AuthProfile } from '../../../../lib/auth-context';

const getInitials = (profile: AuthProfile): string => {
  const first = profile.firstName?.trim()?.[0];
  const last = profile.lastName?.trim()?.[0];
  if (first && last) {
    return (first + last).toUpperCase();
  }
  if (first) {
    return first.toUpperCase();
  }
  if (profile.username) {
    return profile.username.slice(0, 2).toUpperCase();
  }

  return profile.email.slice(0, 2).toUpperCase();
};

const getDisplayName = (profile: AuthProfile): string => {
  const full = [profile.firstName, profile.lastName]
    .filter(Boolean)
    .join(' ')
    .trim();
  if (full) {
    return full;
  }
  if (profile.username) {
    return profile.username;
  }

  return profile.email;
};

const getTitle = (name: string, org: string | undefined): string => {
  if (org) {
    return `${name} — ${org}`;
  }

  return name;
};

interface AuthLoggedInProps {
  profile: AuthProfile;
}

export const AuthLoggedIn = ({ profile }: AuthLoggedInProps) => {
  const name = getDisplayName(profile);
  const org = profile.organization?.name;

  return (
    <div
      className={cn(
        'inline-flex h-8 max-w-[260px] items-center gap-2',
        'rounded-md border border-muted bg-surface-elevated px-1.5',
      )}
      title={getTitle(name, org)}
    >
      <span
        className={cn(
          'flex size-6 shrink-0 items-center justify-center',
          'rounded-full bg-brand-solid text-[10px] font-semibold uppercase',
          'text-brand-solid-contrast',
        )}
        aria-hidden
      >
        {getInitials(profile)}
      </span>
      <div className="flex min-w-0 flex-col leading-tight">
        <span className="truncate text-xs text-foreground">{name}</span>
        {org && (
          <span className="truncate text-[10px] text-muted-foreground">
            {org}
          </span>
        )}
      </div>
    </div>
  );
};
