import { cn } from '@heal/front-core/lib/utils';
import { useEffect, useState } from 'react';
import { codeToTokens, type BundledLanguage, type ThemedToken } from 'shiki';

export type CodeViewerLanguage =
  | 'typescript'
  | 'javascript'
  | 'markdown'
  | 'gherkin'
  | 'json'
  | 'plaintext';

export interface CodeViewerProps {
  /** Full content to display. Rendered as a single block — not per-line. */
  content: string;
  /** Language for syntax highlighting. Defaults to typescript. */
  language?: CodeViewerLanguage;
  /** Shiki theme name. Defaults to github-light/dark based on the `dark` class on <html>. */
  theme?: string;
  /** Show line numbers in the gutter. Default: true. */
  showLineNumbers?: boolean;
  /** Override outer wrapper classes. */
  className?: string;
}

const useIsDarkMode = (): boolean => {
  const [isDark, setIsDark] = useState(
    () =>
      typeof document !== 'undefined' &&
      document.documentElement.classList.contains('dark'),
  );

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    const update = () => setIsDark(root.classList.contains('dark'));
    update();
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ['class'] });

    return () => observer.disconnect();
  }, []);

  return isDark;
};

/**
 * Lightweight read-only code viewer — single-block rendering with shiki
 * syntax highlighting. Built for content that should be shown as-is
 * (test case sources: typescript / markdown / gherkin), distinct from
 * `TraceViewerCodeBlock` which is purpose-built for per-statement step rows.
 */
export const CodeViewer = ({
  content,
  language = 'typescript',
  theme,
  showLineNumbers = true,
  className,
}: CodeViewerProps) => {
  const [tokens, setTokens] = useState<ThemedToken[][] | null>(null);
  const isDark = useIsDarkMode();
  const resolvedTheme =
    theme ?? (isDark ? 'github-dark-default' : 'github-light-default');

  useEffect(() => {
    let cancelled = false;
    const tokenize = async () => {
      try {
        const result = await codeToTokens(content, {
          lang: language as BundledLanguage,
          theme: resolvedTheme,
        });
        if (!cancelled) {
          setTokens(result.tokens);
        }
      } catch {
        // Language unsupported by shiki / parse error — fall back to plain text.
        if (!cancelled) {
          setTokens(null);
        }
      }
    };
    tokenize();

    return () => {
      cancelled = true;
    };
  }, [content, language, resolvedTheme]);

  const plainLines = content.split('\n');
  const lines: ThemedToken[][] =
    tokens ??
    plainLines.map(
      (line) => [{ content: line, color: undefined }] as ThemedToken[],
    );

  return (
    <pre
      className={cn(
        'm-0 h-full overflow-auto bg-background p-4 font-mono text-xs leading-relaxed',
        className,
      )}
    >
      <code className="block">
        {lines.map((tokenLine, lineIdx) => (
          <div key={lineIdx} className="flex">
            {showLineNumbers && (
              <span
                aria-hidden
                className="shrink-0 pr-4 text-right text-muted-foreground/50 select-none"
                style={{ minWidth: '2.5rem' }}
              >
                {lineIdx + 1}
              </span>
            )}
            <span className="flex-1 whitespace-pre">
              {tokenLine.length === 0
                ? ' '
                : tokenLine.map((token, i) => (
                    <span key={i} style={{ color: token.color }}>
                      {token.content}
                    </span>
                  ))}
            </span>
          </div>
        ))}
      </code>
    </pre>
  );
};
