// Thin wrapper around `@heal-dev/front-run-viewer`'s `<Tracer>` that
// feeds it from the local heal-playwright-tracer server (`/api/*`).
// Mirrors the structure of `apps/web/src/pages/tracer/tracer.tsx`.

import { ExecutionDropdown, Tracer } from '@heal-dev/front-run-viewer';
import type {
  AnalyzeSlotProps,
  Test,
  TestList,
} from '@heal-dev/front-run-viewer';
import { useEffect, useMemo, useState } from 'react';
import { BrowserRouter, useLocation, useNavigate } from 'react-router';

import { useAnalyze } from './api/analyze/hooks/use-analyze';
import { useExecutionIndexQuery } from './api/executions/hooks/use-execution-index-query';
import { useExecutionsQuery } from './api/executions/hooks/use-executions-query';
import { useLoadSourceContent } from './api/traces/hooks/use-load-source-content';
import { useTraceQuery } from './api/traces/hooks/use-trace-query';
import type { TraceModel } from './api/types';
import { AuthProvider } from './lib/auth-context';
import { toTestList, toTracerTest } from './lib/map-trace';
import { QueryProvider } from './lib/query-provider';
import { Header } from './shared/features/header/header';

export const App = () => (
  <QueryProvider>
    <AuthProvider>
      <BrowserRouter>
        <AppContent />
      </BrowserRouter>
    </AuthProvider>
  </QueryProvider>
);

/**
 * `heal analyze` only makes sense for failed runs. We treat
 * "interrupted" as failed too — Playwright reports it on assertion
 * timeouts and the analyzer happily classifies them. Passed/skipped
 * tests get no button.
 */
const isAnalyzable = (trace: TraceModel | null): boolean => {
  if (!trace?.result) return false;
  const s = trace.result.status;

  return s === 'failed' || s === 'timedOut' || s === 'interrupted';
};

const AppContent = () => {
  const [params, setParams] = useState<{
    executionId?: string;
    testId?: string;
    attemptNumber?: number;
  }>({});

  const { pathname } = useLocation();
  const navigate = useNavigate();
  const loadSourceContent = useLoadSourceContent();
  const isOnIndex = !pathname.includes('/executions/');

  // 1. List executions.
  const executionsQuery = useExecutionsQuery();
  const executions = useMemo(
    () => executionsQuery.data?.executions ?? [],
    [executionsQuery.data],
  );

  // 2. Redirect to the latest execution when landing on the bare index.
  useEffect(() => {
    const firstId = executions[0]?.executionId;
    if (isOnIndex && firstId) {
      navigate(`/executions/${encodeURIComponent(firstId)}`, { replace: true });
    }
  }, [isOnIndex, executions, navigate]);

  // 3. The current execution's test index. Raw per-attempt summaries drive
  // the "Analyze all" batch; the grouped `TestList` feeds the sidebar.
  const indexQuery = useExecutionIndexQuery(params.executionId);
  const rawSummaries = useMemo(
    () => indexQuery.data?.tests ?? [],
    [indexQuery.data],
  );
  const testList = useMemo<TestList>(
    () =>
      params.executionId && indexQuery.data
        ? toTestList(params.executionId, indexQuery.data.tests)
        : [],
    [params.executionId, indexQuery.data],
  );

  // 4. The selected test's trace.
  const traceQuery = useTraceQuery({
    executionId: params.executionId,
    playwrightTestId: params.testId,
    attempt: params.attemptNumber,
  });
  const currentTrace = traceQuery.data ?? null;

  // 5. Analyze lifecycle (status polling + triggers) for the viewed attempt.
  const analyze = useAnalyze({
    executionId: params.executionId,
    testId: params.testId,
    attempt: params.attemptNumber,
    analyzable: isAnalyzable(currentTrace),
    rawSummaries,
  });

  const currentTest = useMemo<Test | null>(
    () =>
      currentTrace && params.testId
        ? toTracerTest(currentTrace, params.testId, analyze.triagedVerdict)
        : null,
    [currentTrace, params.testId, analyze.triagedVerdict],
  );

  const analyzeSlot = useMemo<AnalyzeSlotProps>(
    () => ({
      state: analyze.analyzeState,
      onTrigger: analyze.onTrigger,
      isTriggering: analyze.isTriggering,
      onTriggerAll: analyze.onTriggerAll,
      isTriggeringAll: analyze.isTriggeringAll,
      failingTestCount: analyze.failingTestCount,
    }),
    [analyze],
  );

  const tracerExecutions = useMemo(
    () =>
      executions.map((e) => ({
        id: e.executionId,
        startedAt: e.startedAt,
        totals: e.totals,
        git: e.git,
      })),
    [executions],
  );

  if (executionsQuery.error) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load executions: {executionsQuery.error.message}
        </div>
      </div>
    );
  }

  if (executions.length === 0) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-muted-foreground">
          No executions found under <code>./heal-traces/</code>. Run your
          Playwright tests with the heal tracer wired up to populate this
          viewer.
        </div>
      </div>
    );
  }

  if (indexQuery.error) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load trace index: {indexQuery.error.message}
        </div>
      </div>
    );
  }

  function getSelectedDisplayValue(executionId: string): string {
    const execution = executions.find((e) => e.executionId === executionId);
    if (!execution) return '';

    return `Ran on ${new Date(execution.startedAt ?? '').toLocaleString()}`;
  }

  return (
    <div className="flex h-screen flex-col bg-background text-foreground">
      <Header>
        <ExecutionDropdown
          popOverWidth="min-w-[280px] w-fit"
          currentKey={params.executionId ?? ''}
          items={executions.map((e) => ({
            key: e.executionId,
            label: new Date(e.startedAt ?? '').toLocaleString(),
            startedAt: e.startedAt,
            timeAgo: '',
            totals: e.totals,
            git: e.git,
            passCount: e.totals?.passed,
            failCount: e.totals?.failed,
            skipCount: e.totals?.skipped,
          }))}
          handleSwitch={(v) => v && setParams({ ...params, executionId: v })}
          label="execution"
          selectedDisplayValue={getSelectedDisplayValue(
            params.executionId ?? '',
          )}
          hasMore={false}
          isLoadingMore={false}
          onLoadMore={() => {}}
        />
      </Header>
      <div className="flex-1 overflow-hidden">
        <Tracer
          testList={testList}
          currentTest={currentTest}
          basePath=""
          onParamsChange={setParams}
          onLoadSourceContent={loadSourceContent}
          mode="local"
          features={{ showGroupBy: false, verdictForm: true }}
          executions={tracerExecutions}
          analyzeSlot={analyzeSlot}
        />
      </div>
    </div>
  );
};
