import { useContext } from 'react';

import { CodeNavigationContext } from './code-navigation-provider.context';

export const useCodeNavigation = () => {
  const context = useContext(CodeNavigationContext);
  if (!context) {
    throw new Error(
      'useCodeNavigation must be used within a CodeNavigationProvider',
    );
  }

  return context;
};
