import {
  FileTextIcon,
  FileXIcon,
  HourglassHighIcon,
} from '@phosphor-icons/react';

import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { useEventProvider } from '../../../context/event-provider/event-provider.hooks';
import { EmptyState } from '../_components/empty-state';

import { VerdictFormFinalCard } from './_components/verdict-form-final-card';
import { VerdictFormOptions } from './_components/verdict-form-options';
import { VerdictFormResult } from './_components/verdict-form-result';
import { VerdictFormLoading } from './_components/verdict-form.loading';

export const VERDICT_FORM_VIEW_ID = 'verdict-form';

interface VerdictFormViewProps {
  /**
   * When true, render the read-only final-card layout regardless of whether
   * a final verdict exists. Kept as a dev/preview convenience.
   */
  forceReadOnly?: boolean;
}

export const VerdictFormView = ({
  forceReadOnly = false,
}: VerdictFormViewProps = {}) => {
  const { currentTest } = useDataProvider();
  const { onVerdictClassify } = useEventProvider();
  const mode = useVerdictFormViewMode({ forceReadOnly });

  if (!currentTest) {
    return (
      <Shell>
        <EmptyState
          icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
          message="No test selected."
        />
      </Shell>
    );
  }

  const { triagedVerdict, finalVerdict } = currentTest;

  if (mode === 'loading') {
    return (
      <Shell>
        <VerdictFormLoading
          formResult={{
            failure: currentTest.failure,
            verdict: triagedVerdict,
          }}
        />
      </Shell>
    );
  }

  if (mode === 'readonly' && finalVerdict) {
    return (
      <Shell>
        <VerdictFormFinalCard verdict={finalVerdict} />
      </Shell>
    );
  }

  if (mode === 'readonly' && triagedVerdict) {
    return (
      <Shell>
        <VerdictFormResult
          failure={currentTest.failure}
          verdict={triagedVerdict}
        />
      </Shell>
    );
  }

  if (mode === 'form' && triagedVerdict) {
    return (
      <Shell
        bottomContent={
          <VerdictFormOptions
            currentType={triagedVerdict.payload.type}
            onClassify={onVerdictClassify}
          />
        }
      >
        <VerdictFormResult
          failure={currentTest.failure}
          verdict={triagedVerdict}
        />
      </Shell>
    );
  }

  if (mode === 'error') {
    return (
      <Shell>
        <EmptyState
          icon={<FileXIcon className="h-10 w-10" weight="thin" />}
          message="The analysis failed to complete."
        />
      </Shell>
    );
  }

  if (mode === 'waiting') {
    return (
      <Shell>
        <EmptyState
          icon={<HourglassHighIcon className="h-10 w-10" weight="thin" />}
          message="We are waiting for the test to be completed before we can analyse it."
        />
      </Shell>
    );
  }

  // empty or default
  return (
    <Shell>
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="No verdict available."
      />
    </Shell>
  );
};

function Shell({
  children,
  bottomContent,
}: {
  children: React.ReactNode;
  bottomContent?: React.ReactNode;
}) {
  return (
    <div className="flex h-full min-h-0 flex-col py-4">
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-auto px-4">
        {children}
      </div>
      {bottomContent && (
        <div className="shrink-0 px-4 py-4">{bottomContent}</div>
      )}
    </div>
  );
}

const useVerdictFormViewMode = ({
  forceReadOnly,
}: {
  forceReadOnly: boolean;
}): 'form' | 'loading' | 'readonly' | 'error' | 'waiting' | 'empty' => {
  const { currentTest } = useDataProvider();
  const triagedVerdict = currentTest?.triagedVerdict;
  const finalVerdict = currentTest?.finalVerdict;
  const canWriteFinalVerdict = useCapabilities().canWriteFinalVerdict;
  const analysisStatus = currentTest?.analysisStatus;

  if (analysisStatus === 'running') {
    return 'loading';
  }

  if (analysisStatus === 'not_started' || !analysisStatus) {
    return 'waiting';
  }

  if (analysisStatus === 'not_applicable' && !triagedVerdict) {
    return 'empty';
  }

  if (analysisStatus === 'failed') {
    return 'error';
  }

  if (forceReadOnly) {
    return 'readonly';
  }

  if (finalVerdict) {
    return 'readonly';
  }

  if (canWriteFinalVerdict && triagedVerdict) {
    return 'form';
  }

  return 'readonly';
};
