import { useQueryClient } from '@tanstack/react-query';
import { useCallback } from 'react';

import { getSource, tracesKeys } from '../traces.api';

/**
 * Returns a stable `onLoadSourceContent` callback for `<Tracer>` that serves
 * source files through the React Query cache. The `<Tracer>` invokes it lazily
 * with a `SourceRef.url`, so we use `fetchQuery` (imperative) rather than a
 * `useQuery` hook. The URL embeds a content hash, so each file is immutable —
 * `staleTime`/`gcTime` are `Infinity` and the same file is never re-fetched
 * within a session (e.g. re-opening it or revisiting a test).
 */
export const useLoadSourceContent = () => {
  const queryClient = useQueryClient();

  return useCallback(
    (url: string) =>
      queryClient.fetchQuery({
        queryKey: tracesKeys.source(url),
        queryFn: () => getSource(url),
        staleTime: Infinity,
        gcTime: Infinity,
      }),
    [queryClient],
  );
};
