import { FileTextIcon } from '@phosphor-icons/react';

import { useAnalyzeSlot } from '../../../context/analyze-slot-provider/analyze-slot-provider.hooks';
import type { AnalyzeSlotProviderContextValue } from '../../../context/analyze-slot-provider/analyze-slot-provider.types';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { AnalyzeSlot } from '../../analyze-slot/analyze-slot';
import { EmptyState } from '../_components/empty-state';
import { VerdictFormResult } from '../verdict-form/_components/verdict-form-result';
import { VerdictFormLoading } from '../verdict-form/_components/verdict-form.loading';

export const ANALYSE_VIEW_ID = 'analyse';

/**
 * Host wired an analyze slot AND there's no verdict yet: render the analyze
 * affordance (button / spinner) as primary content. `kind === 'completed'` is
 * transient — the host promotes the verdict onto `currentTest.triagedVerdict`.
 */
const shouldShowAnalyzeSlotAsPrimary = (
  analyzeSlot: AnalyzeSlotProviderContextValue,
  hasTriagedVerdict: boolean,
): boolean => {
  if (analyzeSlot === null) {
    return false;
  }
  if (hasTriagedVerdict) {
    return false;
  }

  return (
    analyzeSlot.state.kind === 'none' || analyzeSlot.state.kind === 'running'
  );
};

export const AnalyseView = () => {
  const { currentTest } = useDataProvider();
  const analyzeSlot = useAnalyzeSlot();

  if (!currentTest) {
    return (
      <Shell>
        <EmptyState
          icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
          message="No verdict available."
        />
      </Shell>
    );
  }

  const { triagedVerdict } = currentTest;

  if (analyzeSlot?.state.kind === 'running') {
    return (
      <Shell>
        <VerdictFormLoading
          formResult={{
            failure: currentTest.failure,
            verdict: triagedVerdict,
          }}
        />
      </Shell>
    );
  }

  const showAnalyzeSlotAsPrimary = shouldShowAnalyzeSlotAsPrimary(
    analyzeSlot,
    Boolean(triagedVerdict),
  );

  if (showAnalyzeSlotAsPrimary) {
    return (
      <Shell>
        <AnalyzeSlot />
      </Shell>
    );
  }

  const showAnalyzeSlotSecondary =
    analyzeSlot !== null && analyzeSlot.state.kind === 'failed';

  return (
    <Shell>
      <VerdictFormResult
        failure={currentTest.failure}
        verdict={triagedVerdict}
      />
      {showAnalyzeSlotSecondary && <AnalyzeSlot />}
    </Shell>
  );
};

function Shell({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex h-full min-h-0 flex-col py-4">
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-auto px-4">
        {children}
      </div>
    </div>
  );
}
